window.RA_REV = [{"page":"learn","title":["Learn robotics, step by step","Apprendre la robotique, pas à pas"],"lessons":[{"id":"l1","n":"1","m":3,"t":["What is a robot?","Qu'est-ce qu'un robot ?"],"ess":[["A robot <b>senses</b> (sensors), <b>decides</b> (computer) and <b>acts</b> (motors), again and again.","It is <b>programmable</b>: the same robot can do a new task with a new program.","A washing machine follows a fixed cycle; a robot adapts what it does to what it measures."],["Un robot <b>perçoit</b> (capteurs), <b>décide</b> (ordinateur) et <b>agit</b> (moteurs), encore et encore.","Il est <b>programmable</b> : le même robot peut faire une nouvelle tâche avec un nouveau programme.","Une machine à laver suit un cycle fixe ; un robot adapte ce qu'il fait à ce qu'il mesure."]],"keep":[[],[]],"eq":[[],[]],"kt":[["sensor","controller","actuator"],["capteur","contrôleur","actionneur"]]},{"id":"l2","n":"2","m":3,"t":["Links and joints","Corps et liaisons"],"ess":[["A <b>link</b> is a rigid piece; a <b>joint</b> connects two links and lets them move relative to each other.","A robot arm is a chain: base – joint – link – joint – link … – tool.","In a serial arm, n joints connect n + 1 links (the base counts as link 0)."],["Un <b>segment</b> est une pièce rigide ; une <b>liaison</b> relie deux segments et les laisse bouger l'un par rapport à l'autre.","Un bras robot est une chaîne : base – liaison – segment – liaison – segment … – outil.","Dans un bras série, n liaisons relient n + 1 segments (la base compte comme segment 0)."]],"keep":[[],[]],"eq":[[],[]],"kt":[["link","joint","base"],["corps","liaison","base"]]},{"id":"l3","n":"3","m":4,"t":["Two kinds of joints","Deux types de liaisons"],"ess":[["A <b>revolute</b> joint (R) turns, like an elbow; we measure an angle θ in degrees or radians.","A <b>prismatic</b> joint (P) slides, like a drawer; we measure a distance d in metres.","A robot is named by its joints from the base: a SCARA is R-R-P-R, a gantry is P-P-P."],["Une liaison <b>rotoïde</b> (R) tourne, comme un coude ; on mesure un angle θ en degrés ou en radians.","Une liaison <b>prismatique</b> (P) glisse, comme un tiroir ; on mesure une distance d en mètres.","On nomme un robot par ses liaisons depuis la base : un SCARA est R-R-P-R, un portique est P-P-P."]],"keep":[[],[]],"eq":[[],[]],"kt":[["revolute (R)","prismatic (P)","joint variable"],["rotoïde (R)","prismatique (P)","variable articulaire"]]},{"id":"l4","n":"4","m":4,"t":["Degrees of freedom (DOF)","Degrés de liberté (DDL)"],"ess":[["The <b>degrees of freedom</b> (DOF) are the independent movements a body can make.","A free object in space has 6 DOF: 3 positions (x, y, z) and 3 orientations.","A serial arm usually has as many DOF as joints: 6 joints are needed to place a tool anywhere with any orientation."],["Les <b>degrés de liberté</b> (DDL) sont les mouvements indépendants qu'un corps peut faire.","Un objet libre dans l'espace a 6 DDL : 3 positions (x, y, z) et 3 orientations.","Un bras série a en général autant de DDL que de liaisons : il faut 6 liaisons pour placer un outil n'importe où dans n'importe quelle orientation."]],"keep":[[],[]],"eq":[[],[]],"kt":[["DOF","position","orientation"],["DDL","position","orientation"]]},{"id":"l5","n":"5","m":2,"t":["End effector (the tool)","Organe terminal (l'outil)"],"ess":[["The <b>end effector</b> is the tool at the end of the arm: gripper, suction cup, welding torch, screwdriver…","The robot only moves the tool; the tool does the real job.","The <b>TCP</b> (tool centre point) is the point of the tool the robot places: the tip of the torch, the middle of the fingers."],["L'<b>effecteur</b> est l'outil au bout du bras : pince, ventouse, torche de soudure, visseuse…","Le robot ne fait que déplacer l'outil ; c'est l'outil qui fait le vrai travail.","Le <b>TCP</b> (point central de l'outil) est le point de l'outil que le robot place : le bout de la torche, le milieu des doigts."]],"keep":[[],[]],"eq":[[],[]],"kt":[["end effector","gripper","tool centre point (TCP)"],["organe terminal","pince","point central de l'outil (TCP)"]]},{"id":"l6","n":"6","m":4,"t":["The kinematic diagram","Le schéma cinématique"],"ess":[["A <b>kinematic diagram</b> draws a robot with simple symbols: lines for links, circles or rectangles for joints.","It keeps only what matters for the motion: the joints, their axes and the distances between them.","It is the first thing to draw before any calculation."],["Un <b>schéma cinématique</b> dessine un robot avec des symboles simples : des traits pour les segments, des cercles ou rectangles pour les liaisons.","Il ne garde que ce qui compte pour le mouvement : les liaisons, leurs axes et les distances entre elles.","C'est la première chose à dessiner avant tout calcul."]],"keep":[[],[]],"eq":[[],[]],"kt":[["kinematic diagram","symbol"],["schéma cinématique","symbole"]]},{"id":"l7","n":"7","m":5,"t":["Forward kinematics (FK)","Cinématique directe (MGD)"],"ess":[["<b>Forward kinematics</b> (FK): from the joint values, compute where the tool is.","For a 2-axis planar arm: x = L₁ cos θ₁ + L₂ cos(θ₁ + θ₂), y = L₁ sin θ₁ + L₂ sin(θ₁ + θ₂).","FK always has exactly one answer: one set of angles gives one tool position."],["<b>Modèle géométrique direct</b> (MGD) : à partir des valeurs des liaisons, calculer où est l'outil.","Pour un bras plan à 2 axes : x = L₁ cos θ₁ + L₂ cos(θ₁ + θ₂), y = L₁ sin θ₁ + L₂ sin(θ₁ + θ₂).","Le MGD a toujours une seule réponse : un jeu d'angles donne une seule position de l'outil."]],"keep":[[],[]],"eq":[[],[]],"kt":[["forward kinematics","pose"],["cinématique directe","pose"]]},{"id":"l8","n":"8","m":5,"t":["Inverse kinematics (IK)","Cinématique inverse (MGI)"],"ess":[["<b>Inverse kinematics</b> (IK): from the wanted tool position, find the joint values.","It can have 2 answers (elbow up / elbow down), many answers, or none (point out of reach).","For 2 links: cos θ₂ = (x² + y² − L₁² − L₂²) / (2 L₁ L₂)."],["<b>Modèle géométrique inverse</b> (MGI) : à partir de la position voulue de l'outil, trouver les valeurs des liaisons.","Il peut avoir 2 réponses (coude en haut / coude en bas), beaucoup de réponses, ou aucune (point hors d'atteinte).","Pour 2 segments : cos θ₂ = (x² + y² − L₁² − L₂²) / (2 L₁ L₂)."]],"keep":[[],[]],"eq":[[],[]],"kt":[["inverse kinematics","singularity","elbow up / down"],["cinématique inverse","singularité","coude haut / bas"]]},{"id":"l9","n":"9","m":3,"t":["Workspace","Espace de travail"],"ess":[["The <b>workspace</b> is the set of all points the tool can reach.","For a 2-link arm it is a ring: outer radius L₁ + L₂, inner radius |L₁ − L₂|.","Joint limits and obstacles make it smaller."],["L'<b>espace de travail</b> est l'ensemble des points que l'outil peut atteindre.","Pour un bras à 2 segments, c'est un anneau : rayon extérieur L₁ + L₂, rayon intérieur |L₁ − L₂|.","Les butées des liaisons et les obstacles le réduisent."]],"keep":[[],[]],"eq":[["| <i>L</i><sub>1</sub> − <i>L</i><sub>2</sub> | ≤ √( <i>x</i>² + <i>y</i>² ) ≤ <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub>"],["| <i>L</i><sub>1</sub> − <i>L</i><sub>2</sub> | ≤ √( <i>x</i>² + <i>y</i>² ) ≤ <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub>"]],"kt":[["workspace","joint limit","reach"],["espace de travail","butée de liaison","portée"]]},{"id":"l10","n":"10","m":5,"t":["Actuators, sensors and control","Actionneurs, capteurs et commande"],"ess":[["<b>Actuators</b> (motors) make the robot move; <b>sensors</b> measure; the <b>controller</b> compares and corrects.","A gearbox slows the motor down and multiplies its torque by the same ratio.","Closed loop: measure → compare with the target → correct → measure again."],["Les <b>actionneurs</b> (moteurs) font bouger le robot ; les <b>capteurs</b> mesurent ; le <b>contrôleur</b> compare et corrige.","Un réducteur ralentit le moteur et multiplie son couple du même rapport.","Boucle fermée : mesurer → comparer à la consigne → corriger → mesurer à nouveau."]],"keep":[[],[]],"eq":[[],[]],"kt":[["encoder","motor","PID"],["codeur","moteur","PID"]]},{"id":"l11","n":"11","m":8,"t":["DH and DHM: describing a robot with a table","DH et DHM : décrire un robot avec un tableau"],"ess":[["<b>DH</b> describes each link with 4 numbers: θ (turn), d (offset along z), a (length along x), α (twist).","One line of the table per joint; for a revolute joint θ is the variable, for a prismatic joint d is.","Multiplying the matrices of all the lines gives the position of the tool."],["La convention <b>DH</b> décrit chaque segment avec 4 nombres : θ (rotation), d (décalage selon z), a (longueur selon x), α (torsion).","Une ligne du tableau par liaison ; pour une liaison rotoïde la variable est θ, pour une prismatique c'est d.","En multipliant les matrices de toutes les lignes, on obtient la position de l'outil."]],"keep":[[],[]],"eq":[[],[]],"kt":[["DH table","DHM table","frame","homogeneous matrix"],["tableau DH","tableau DHM","repère","matrice homogène"]]},{"id":"l12","n":"12","m":6,"t":["The maths you need (very little)","Les maths dont vous avez besoin (très peu)"],"ess":[["Angles: 1 turn = 360° = 2π rad; to convert, rad = deg × π / 180.","cos gives the horizontal part, sin the vertical part: a vector of length L at angle θ is (L cos θ, L sin θ).","Pythagoras gives a distance: d = √(x² + y²); atan2(y, x) gives the direction."],["Angles : 1 tour = 360° = 2π rad ; pour convertir, rad = deg × π / 180.","cos donne la partie horizontale, sin la partie verticale : un vecteur de longueur L à l'angle θ vaut (L cos θ, L sin θ).","Pythagore donne une distance : d = √(x² + y²) ; atan2(y, x) donne la direction."]],"keep":[[],[]],"eq":[[],[]],"kt":[["radian","matrix","vector"],["radian","matrice","vecteur"]]}],"t":["Foundations","Les fondations"]},{"page":"learn-mathkit","title":["The maths of robotics, one tool per lesson","Les maths de la robotique, un outil par leçon"],"lessons":[{"id":"l1","n":"1","m":10,"t":["Angles and trigonometry","Angles et trigonométrie"],"ess":[["Radians = degrees × π / 180. A full turn is 2π.","The end of an arm of length L at angle θ is at x = L cos θ, y = L sin θ.","To find an angle from a point, use atan2(y, x), never arctan(y/x) alone."],["Radians = degrés × π / 180. Un tour complet fait 2π.","Le bout d'un bras de longueur L à l'angle θ est en x = L cos θ, y = L sin θ.","Pour trouver un angle à partir d'un point, utilisez atan2(y, x), jamais arctan(y/x) seul."]],"keep":[[],[]],"eq":[["radians = degrees × π / 180 degrees = radians × 180 / π","<i>x</i> = <i>L</i> cos <i>θ</i> <i>y</i> = <i>L</i> sin <i>θ</i>"],["radians = degrés × π / 180 degrés = radians × 180 / π","<i>x</i> = <i>L</i> cos <i>θ</i> <i>y</i> = <i>L</i> sin <i>θ</i>"]],"kt":[["radian","sine / cosine","Pythagoras","atan2"],["radian","sinus / cosinus","Pythagore","atan2"]]},{"id":"l2","n":"2","m":11,"t":["Vectors","Les vecteurs"],"ess":[["A vector is an arrow written as a column of numbers. Add vectors component by component.","Length: √(x² + y² + z²). A unit vector has length 1.","Dot product = 0 means perpendicular. The cross product gives a perpendicular vector."],["Un vecteur est une flèche écrite comme une colonne de nombres. On additionne les vecteurs composante par composante.","Longueur : √(x² + y² + z²). Un vecteur unitaire a une longueur de 1.","Produit scalaire = 0 veut dire perpendiculaires. Le produit vectoriel donne un vecteur perpendiculaire."]],"keep":[[],[]],"eq":[["<strong>a</strong> · <strong>b</strong> = <i>a</i><sub>x</sub><i>b</i><sub>x</sub> + <i>a</i><sub>y</sub><i>b</i><sub>y</sub> + <i>a</i><sub>z</sub><i>b</i><sub>z</sub> = ‖<strong>a</strong>‖ ‖<strong>b</strong>‖ cos <i>φ</i>","<strong>x</strong> × <strong>y</strong> = <strong>z</strong> <strong>y</strong> × <strong>z</strong> = <strong>x</strong> <strong>z</strong> × <strong>x</strong> = <strong>y</strong>"],["<strong>a</strong> · <strong>b</strong> = <i>a</i><sub>x</sub><i>b</i><sub>x</sub> + <i>a</i><sub>y</sub><i>b</i><sub>y</sub> + <i>a</i><sub>z</sub><i>b</i><sub>z</sub> = ‖<strong>a</strong>‖ ‖<strong>b</strong>‖ cos <i>φ</i>","<strong>x</strong> × <strong>y</strong> = <strong>z</strong> <strong>y</strong> × <strong>z</strong> = <strong>x</strong> <strong>z</strong> × <strong>x</strong> = <strong>y</strong>"]],"kt":[["vector","component","norm","unit vector","dot product","cross product"],["vecteur","composante","norme","vecteur unitaire","produit scalaire","produit vectoriel"]]},{"id":"l3","n":"3","m":12,"t":["Matrices","Les matrices"],"ess":[["Matrix × vector: row times column. The columns of a matrix say where the axes go.","A B does B first, then A. In general A B ≠ B A.","det = 0 means no inverse. For a 2×2 matrix: det = ad − bc."],["Matrice × vecteur : ligne fois colonne. Les colonnes d'une matrice disent où vont les axes.","A B fait d'abord B, puis A. En général A B ≠ B A.","dét = 0 veut dire pas d'inverse. Pour une matrice 2×2 : dét = ad − bc."]],"keep":[[],[]],"eq":[["<span class=\"mx c2\"><span><i>a</i></span><span><i>b</i></span><span><i>c</i></span><span><i>d</i></span></span> <span class=\"mx c1\"><span><i>x</i></span><span><i>y</i></span></span> = <span class=\"mx c1\"><span><i>a</i><i>x</i> + <i>b</i><i>y</i></span><span><i>c</i><i>x</i> + <i>d</i><i>y</i></span></span>","<span class=\"mx c2\"><span>1</span><span>2</span><span>3</span><span>4</span></span> <span class=\"mx c2\"><span>0</span><span>1</span><span>1</span><span>0</span></span> = <span class=\"mx c2\"><span>1×0 + 2×1</span><span>1×1 + 2×0</span><span>3×0 + 4×1</span><span>3×1 + 4×0</span></span> = <span class=\"mx c2\"><span>2</span><span>1</span><span>4</span><span>3</span></span>"],["<span class=\"mx c2\"><span><i>a</i></span><span><i>b</i></span><span><i>c</i></span><span><i>d</i></span></span> <span class=\"mx c1\"><span><i>x</i></span><span><i>y</i></span></span> = <span class=\"mx c1\"><span><i>a</i><i>x</i> + <i>b</i><i>y</i></span><span><i>c</i><i>x</i> + <i>d</i><i>y</i></span></span>","<span class=\"mx c2\"><span>1</span><span>2</span><span>3</span><span>4</span></span> <span class=\"mx c2\"><span>0</span><span>1</span><span>1</span><span>0</span></span> = <span class=\"mx c2\"><span>1×0 + 2×1</span><span>1×1 + 2×0</span><span>3×0 + 4×1</span><span>3×1 + 4×0</span></span> = <span class=\"mx c2\"><span>2</span><span>1</span><span>4</span><span>3</span></span>"]],"kt":[["matrix","identity","transpose","determinant","inverse"],["matrice","identité","transposée","déterminant","inverse"]]},{"id":"l4","n":"4","m":12,"t":["Rotation matrices","Les matrices de rotation"],"ess":[["R(θ) has the columns (cos θ, sin θ) and (−sin θ, cos θ): where the axes go.","A rotation keeps lengths; its inverse is its transpose.","In the plane the angles add; in 3D the order of rotations matters."],["R(θ) a pour colonnes (cos θ, sin θ) et (−sin θ, cos θ) : là où vont les axes.","Une rotation garde les longueurs ; son inverse est sa transposée.","Dans le plan les angles s'ajoutent ; en 3D l'ordre des rotations compte."]],"keep":[["<p class=\"eq\"><i>R</i>(<i>θ</i>) = <span class=\"mx c2\"><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>sin <i>θ</i></span><span>cos <i>θ</i></span></span></p>"],["<p class=\"eq\"><i>R</i>(<i>θ</i>) = <span class=\"mx c2\"><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>sin <i>θ</i></span><span>cos <i>θ</i></span></span></p>"]],"eq":[["<i>R</i>(<i>θ</i>) = <span class=\"mx c2\"><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>sin <i>θ</i></span><span>cos <i>θ</i></span></span>","<i>R</i><sub>z</sub>(<i>θ</i>) = <span class=\"mx c3\"><span>c</span><span>−s</span><span>0</span><span>s</span><span>c</span><span>0</span><span>0</span><span>0</span><span>1</span></span> <i>R</i><sub>y</sub>(<i>θ</i>) = <span class=\"mx c3\"><span>c</span><span>0</span><span>s</span><span>0</span><span>1</span><span>0</span><span>−s</span><span>0</span><span>c</span></span> <i>R</i><sub>x</sub>(<i>θ</i>) = <span class=\"mx c3\"><span>1</span><span>0</span><span>0</span><span>0</span><span>c</span><span>−s</span><span>0</span><span>s</span><span>c</span></span>"],["<i>R</i>(<i>θ</i>) = <span class=\"mx c2\"><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>sin <i>θ</i></span><span>cos <i>θ</i></span></span>","<i>R</i><sub>z</sub>(<i>θ</i>) = <span class=\"mx c3\"><span>c</span><span>−s</span><span>0</span><span>s</span><span>c</span><span>0</span><span>0</span><span>0</span><span>1</span></span> <i>R</i><sub>y</sub>(<i>θ</i>) = <span class=\"mx c3\"><span>c</span><span>0</span><span>s</span><span>0</span><span>1</span><span>0</span><span>−s</span><span>0</span><span>c</span></span> <i>R</i><sub>x</sub>(<i>θ</i>) = <span class=\"mx c3\"><span>1</span><span>0</span><span>0</span><span>0</span><span>c</span><span>−s</span><span>0</span><span>s</span><span>c</span></span>"]],"kt":[["rotation matrix","right-hand rule","orthogonal matrix"],["matrice de rotation","règle de la main droite","matrice orthogonale"]]},{"id":"l5","n":"5","m":14,"t":["Frames and transformations","Repères et transformations"],"ess":[["Change of frame: p_A = R p_B + t (turn, then add the position of the frame).","A homogeneous matrix holds R and t; its last column is the position.","Chain the frames by multiplying: ⁰T₂ = ⁰T₁ ¹T₂."],["Changement de repère : p_A = R p_B + t (tourner, puis ajouter la position du repère).","Une matrice homogène contient R et t ; sa dernière colonne est la position.","On enchaîne les repères en multipliant : ⁰T₂ = ⁰T₁ ¹T₂."]],"keep":[["<p class=\"eq\"><strong>p</strong><sub>A</sub> = <i>R</i> <strong>p</strong><sub>B</sub> + <strong>t</strong></p> <p><i>R</i> = the orientation of B seen from A (its columns are the axes of B, written in A). <strong>t</strong> = the origin of B, written in A.</p>"],["<p class=\"eq\"><strong>p</strong><sub>A</sub> = <i>R</i> <strong>p</strong><sub>B</sub> + <strong>t</strong></p> <p><i>R</i> = l'orientation de B vue depuis A (ses colonnes sont les axes de B, écrits dans A). <strong>t</strong> = l'origine de B, écrite dans A.</p>"]],"eq":[["<strong>p</strong><sub>A</sub> = <i>R</i> <strong>p</strong><sub>B</sub> + <strong>t</strong>","<span class=\"mx c1\"><span><strong>p</strong><sub>A</sub></span><span>1</span></span> = <span class=\"mx c2\"><span><i>R</i></span><span><strong>t</strong></span><span>0</span><span>1</span></span> <span class=\"mx c1\"><span><strong>p</strong><sub>B</sub></span><span>1</span></span> <sup>A</sup><i>T</i><sub>B</sub> = <span class=\"mx c2\"><span><i>R</i></span><span><strong>t</strong></span><span>0</span><span>1</span></span>","<sup>0</sup><i>T</i><sub>2</sub> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>T</i><sub>2</sub>","<sup>0</sup><i>T</i><sub>1</sub> = <span class=\"mx c3\"><span>0.866</span><span>−0.5</span><span>0.433</span><span>0.5</span><span>0.866</span><span>0.25</span><span>0</span><span>0</span><span>1</span></span> <sup>1</sup><i>T</i><sub>2</sub> = <span class=\"mx c3\"><span>0.707</span><span>−0.707</span><span>0.283</span><span>0.707</span><span>0.707</span><span>0.283</span><span>0</span><span>0</span><span>1</span></span> <sup>0</sup><i>T</i><sub>2</sub> = <span class=\"mx c3\"><span>0.259</span><span>−0.966</span><span><strong>0.537</strong></span><span>0.966</span><span>0.259</span><span><strong>0.636</strong></span><span>0</span><span>0</span><span>1</span></span>"],["<strong>p</strong><sub>A</sub> = <i>R</i> <strong>p</strong><sub>B</sub> + <strong>t</strong>","<span class=\"mx c1\"><span><strong>p</strong><sub>A</sub></span><span>1</span></span> = <span class=\"mx c2\"><span><i>R</i></span><span><strong>t</strong></span><span>0</span><span>1</span></span> <span class=\"mx c1\"><span><strong>p</strong><sub>B</sub></span><span>1</span></span> <sup>A</sup><i>T</i><sub>B</sub> = <span class=\"mx c2\"><span><i>R</i></span><span><strong>t</strong></span><span>0</span><span>1</span></span>","<sup>0</sup><i>T</i><sub>2</sub> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>T</i><sub>2</sub>","<sup>0</sup><i>T</i><sub>1</sub> = <span class=\"mx c3\"><span>0,866</span><span>−0,5</span><span>0,433</span><span>0,5</span><span>0,866</span><span>0,25</span><span>0</span><span>0</span><span>1</span></span> <sup>1</sup><i>T</i><sub>2</sub> = <span class=\"mx c3\"><span>0,707</span><span>−0,707</span><span>0,283</span><span>0,707</span><span>0,707</span><span>0,283</span><span>0</span><span>0</span><span>1</span></span> <sup>0</sup><i>T</i><sub>2</sub> = <span class=\"mx c3\"><span>0,259</span><span>−0,966</span><span><strong>0,537</strong></span><span>0,966</span><span>0,259</span><span><strong>0,636</strong></span><span>0</span><span>0</span><span>1</span></span>"]],"kt":[["frame","translation","homogeneous matrix","homogeneous coordinates","chain of transformations"],["repère","translation","matrice homogène","coordonnées homogènes","chaîne de transformations"]]},{"id":"l6","n":"6","m":15,"t":["The Denavit–Hartenberg method (standard DH)","La méthode de Denavit–Hartenberg (DH standard)"],"ess":[["Standard DH: frame i is at the far end of link i; z_i is the axis of joint i+1.","One row = θ, d (along z), then a, α (along x).","Revolute joint: θ moves. Prismatic joint: d moves. a and α are the shape of the link."],["DH standard : le repère i est à l'extrémité du segment i ; z_i est l'axe de la liaison i+1.","Une ligne = θ, d (selon z), puis a, α (selon x).","Liaison rotoïde : θ bouge. Liaison prismatique : d bouge. a et α sont la forme du segment."]],"keep":[["<ul><li><i>a</i><sub>i</sub> and <i>α</i><sub>i</sub> never change: they are the <strong>shape of link <i>i</i></strong>.</li><li>Revolute joint: <i>θ</i><sub>i</sub> is the variable, <i>d</i><sub>i</sub> is fixed. Prismatic joint: <i>d</i><sub>i</sub> is the variable, <i>θ</i><sub>i</sub> is fixed.</li></ul>"],["<ul><li><i>a</i><sub>i</sub> et <i>α</i><sub>i</sub> ne changent jamais : c'est la <strong>forme du segment <i>i</i></strong>.</li><li>Liaison rotoïde : <i>θ</i><sub>i</sub> est la variable, <i>d</i><sub>i</sub> est fixe. Liaison prismatique : <i>d</i><sub>i</sub> est la variable, <i>θ</i><sub>i</sub> est fixe.</li></ul>"]],"eq":[["<sup>i−1</sup><i>T</i><sub>i</sub> = Rot(<i>z</i>, <i>θ</i><sub>i</sub>) · Trans(<i>z</i>, <i>d</i><sub>i</sub>) · Trans(<i>x</i>, <i>a</i><sub>i</sub>) · Rot(<i>x</i>, <i>α</i><sub>i</sub>)","<sup>i−1</sup><i>T</i><sub>i</sub> = <span class=\"mx c4\"><span>cθ</span><span>−sθ cα</span><span>sθ sα</span><span><i>a</i> cθ</span><span>sθ</span><span>cθ cα</span><span>−cθ sα</span><span><i>a</i> sθ</span><span>0</span><span>sα</span><span>cα</span><span><i>d</i></span><span>0</span><span>0</span><span>0</span><span>1</span></span>"],["<sup>i−1</sup><i>T</i><sub>i</sub> = Rot(<i>z</i>, <i>θ</i><sub>i</sub>) · Trans(<i>z</i>, <i>d</i><sub>i</sub>) · Trans(<i>x</i>, <i>a</i><sub>i</sub>) · Rot(<i>x</i>, <i>α</i><sub>i</sub>)","<sup>i−1</sup><i>T</i><sub>i</sub> = <span class=\"mx c4\"><span>cθ</span><span>−sθ cα</span><span>sθ sα</span><span><i>a</i> cθ</span><span>sθ</span><span>cθ cα</span><span>−cθ sα</span><span><i>a</i> sθ</span><span>0</span><span>sα</span><span>cα</span><span><i>d</i></span><span>0</span><span>0</span><span>0</span><span>1</span></span>"]],"kt":[["DH convention","common perpendicular","joint angle θ","offset d","link length a","twist α","DH table"],["convention DH","perpendiculaire commune","angle de liaison θ","décalage d","longueur de segment a","torsion α","tableau DH"]]},{"id":"l7","n":"7","m":14,"t":["The modified DH method (DHM)","La méthode DH modifiée (DHM)"],"ess":[["Modified DH: frame j is on the axis of joint j, at the start of link j.","One row = α, a (along x, shape of the previous link), then θ, d (along z, motion of joint j).","A fixed last row often brings the frame to the tool."],["DH modifié : le repère j est sur l'axe de la liaison j, au début du segment j.","Une ligne = α, a (selon x, forme du segment précédent), puis θ, d (selon z, mouvement de la liaison j).","Une dernière ligne fixe amène souvent le repère jusqu'à l'outil."]],"keep":[["<p><strong>Frame <i>j</i> is fixed to link <i>j</i> and sits on the axis of joint <i>j</i></strong>: the joint that moves this link. Joint 1 → frame 1, joint 2 → frame 2. Same number everywhere.</p>"],["<p><strong>Le repère <i>j</i> est fixé au segment <i>j</i> et se trouve sur l'axe de la liaison <i>j</i></strong> : la liaison qui fait bouger ce segment. Liaison 1 → repère 1, liaison 2 → repère 2. Le même numéro partout.</p>"]],"eq":[["<sup>j−1</sup><i>T</i><sub>j</sub> = Rot(<i>x</i>, <i>α</i><sub>j−1</sub>) · Trans(<i>x</i>, <i>a</i><sub>j−1</sub>) · Rot(<i>z</i>, <i>θ</i><sub>j</sub>) · Trans(<i>z</i>, <i>d</i><sub>j</sub>)","<sup>j−1</sup><i>T</i><sub>j</sub> = <span class=\"mx c4\"><span>cθ</span><span>−sθ</span><span>0</span><span><i>a</i></span><span>sθ cα</span><span>cθ cα</span><span>−sα</span><span>−<i>d</i> sα</span><span>sθ sα</span><span>cθ sα</span><span>cα</span><span><i>d</i> cα</span><span>0</span><span>0</span><span>0</span><span>1</span></span>"],["<sup>j−1</sup><i>T</i><sub>j</sub> = Rot(<i>x</i>, <i>α</i><sub>j−1</sub>) · Trans(<i>x</i>, <i>a</i><sub>j−1</sub>) · Rot(<i>z</i>, <i>θ</i><sub>j</sub>) · Trans(<i>z</i>, <i>d</i><sub>j</sub>)","<sup>j−1</sup><i>T</i><sub>j</sub> = <span class=\"mx c4\"><span>cθ</span><span>−sθ</span><span>0</span><span><i>a</i></span><span>sθ cα</span><span>cθ cα</span><span>−sα</span><span>−<i>d</i> sα</span><span>sθ sα</span><span>cθ sα</span><span>cα</span><span><i>d</i> cα</span><span>0</span><span>0</span><span>0</span><span>1</span></span>"]],"kt":[["modified DH (DHM)","Khalil–Kleinfinger","fixed row","twist α","offset d"],["DH modifié (DHM)","Khalil–Kleinfinger","ligne fixe","torsion α","décalage d"]]},{"id":"l8","n":"8","m":10,"t":["DH and DHM side by side","DH et DHM côte à côte"],"ess":[["Standard: frame at the far end of the link, row θ, d, a, α. Modified: frame on its own joint, row α, a, θ, d.","Both give the same tool position, if each table is used with its own matrix.","Always check a table with the zero pose."],["Standard : repère à l'extrémité du segment, ligne θ, d, a, α. Modifié : repère sur sa propre liaison, ligne α, a, θ, d.","Les deux donnent la même position d'outil, si chaque tableau est utilisé avec sa propre matrice.","Vérifiez toujours un tableau avec la pose zéro."]],"keep":[["<p>The two conventions describe <strong>the same robot</strong>. The frames in the middle of the chain are placed differently, so the intermediate matrices differ, but the final matrix from the base to the tool is the same. Lessons 6 and 7 showed it twice: (0.537, 0.636) and (0.479, 0.223, 0.757).</p>"],["<p>Les deux conventions décrivent <strong>le même robot</strong>. Les repères du milieu de la chaîne sont placés différemment, donc les matrices intermédiaires diffèrent, mais la matrice finale de la base à l'outil est la même. Les leçons 6 et 7 l'ont montré deux fois : (0,537 ; 0,636) et (0,479 ; 0,223 ; 0,757).</p>"]],"eq":[[],[]],"kt":[["standard DH","modified DH","zero pose","convention"],["DH standard","DH modifié","pose zéro","convention"]]},{"id":"l9","n":"9","m":15,"t":["Derivatives and partial derivatives: from positions to speeds","Dérivées et dérivées partielles : des positions aux vitesses"],"ess":[["A derivative is a rate of change: position → speed → acceleration.","Chain rule: (sin θ)′ = cos θ · θ̇. A computer estimates a derivative with (new − old) / Δt.","Partial derivatives (one variable at a time) form the Jacobian: Ẋ = J θ̇."],["Une dérivée est une vitesse de variation : position → vitesse → accélération.","Dérivée composée : (sin θ)′ = cos θ · θ̇. Un ordinateur estime une dérivée par (nouveau − ancien) / Δt.","Les dérivées partielles (une variable à la fois) forment la jacobienne : Ẋ = J θ̇."]],"keep":[[],[]],"eq":[["<i>ẋ</i> = −<i>L</i> sin <i>θ</i> · <i>θ̇</i> <i>ẏ</i> = <i>L</i> cos <i>θ</i> · <i>θ̇</i>","<i>θ̇</i> ≈ ( <i>θ</i>(<i>t</i> + Δ<i>t</i>) − <i>θ</i>(<i>t</i>) ) / Δ<i>t</i>","∂<i>x</i>/∂<i>θ</i><sub>1</sub> = −<i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>) ∂<i>x</i>/∂<i>θ</i><sub>2</sub> = −<i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)","∂<i>y</i>/∂<i>θ</i><sub>1</sub> = <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>) ∂<i>y</i>/∂<i>θ</i><sub>2</sub> = <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)"],["<i>ẋ</i> = −<i>L</i> sin <i>θ</i> · <i>θ̇</i> <i>ẏ</i> = <i>L</i> cos <i>θ</i> · <i>θ̇</i>","<i>θ̇</i> ≈ ( <i>θ</i>(<i>t</i> + Δ<i>t</i>) − <i>θ</i>(<i>t</i>) ) / Δ<i>t</i>","∂<i>x</i>/∂<i>θ</i><sub>1</sub> = −<i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>) ∂<i>x</i>/∂<i>θ</i><sub>2</sub> = −<i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)","∂<i>y</i>/∂<i>θ</i><sub>1</sub> = <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>) ∂<i>y</i>/∂<i>θ</i><sub>2</sub> = <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)"]],"kt":[["derivative","slope","chain rule","finite difference","partial derivative","Jacobian"],["dérivée","pente","dérivée composée","différence finie","dérivée partielle","jacobienne"]]},{"id":"l10","n":"10","m":14,"t":["Probability: living with noisy sensors","Probabilités : vivre avec des capteurs bruités"],"ess":[["Mean = best guess; standard deviation σ = typical error.","Normal law: 68 % within ±σ, 95 % within ±2σ, 99.7 % within ±3σ.","Averaging N measurements divides σ by √N; two sensors are combined with weights 1/σ²."],["Moyenne = meilleure estimation ; écart-type σ = erreur typique.","Loi normale : 68 % dans ±σ, 95 % dans ±2σ, 99,7 % dans ±3σ.","Moyenner N mesures divise σ par √N ; deux capteurs se combinent avec des poids 1/σ²."]],"keep":[["<p>A measurement without its <i>σ</i> is half a measurement. Robots carry, with every estimate, its uncertainty: this is what lets them combine sensors, decide when to trust them, and stop safely.</p>"],["<p>Une mesure sans son <i>σ</i> n'est qu'une demi-mesure. Les robots gardent, avec chaque estimation, son incertitude : c'est ce qui leur permet de combiner des capteurs, de décider quand leur faire confiance, et de s'arrêter en sécurité.</p>"]],"eq":[["<i>x</i> = (<i>x</i><sub>1</sub>/<i>σ</i><sub>1</sub>² + <i>x</i><sub>2</sub>/<i>σ</i><sub>2</sub>²) / (1/<i>σ</i><sub>1</sub>² + 1/<i>σ</i><sub>2</sub>²) 1/<i>σ</i>² = 1/<i>σ</i><sub>1</sub>² + 1/<i>σ</i><sub>2</sub>²"],["<i>x</i> = (<i>x</i><sub>1</sub>/<i>σ</i><sub>1</sub>² + <i>x</i><sub>2</sub>/<i>σ</i><sub>2</sub>²) / (1/<i>σ</i><sub>1</sub>² + 1/<i>σ</i><sub>2</sub>²) 1/<i>σ</i>² = 1/<i>σ</i><sub>1</sub>² + 1/<i>σ</i><sub>2</sub>²"]],"kt":[["mean","variance","standard deviation","normal (Gaussian) law","independent","sensor fusion"],["moyenne","variance","écart-type","loi normale (gaussienne)","indépendant","fusion de capteurs"]]},{"id":"l11","n":"11","m":16,"t":["Orientations in 3D: Euler angles, axis-angle and quaternions","Les orientations en 3D : angles d'Euler, axe-angle et quaternions"],"ess":[["An orientation has 3 degrees of freedom: rotation matrix (9 numbers), roll-pitch-yaw (3, with gimbal lock), axis-angle, quaternion (4).","Quaternion of θ around u: (cos θ/2, u sin θ/2). Chain by multiplying, undo with the conjugate.","ROS 2 writes (x, y, z, w): w last. Heading of a mobile robot: ψ = 2 atan2(z, w)."],["Une orientation a 3 degrés de liberté : matrice de rotation (9 nombres), roulis-tangage-lacet (3, avec blocage de cardan), axe-angle, quaternion (4).","Quaternion de θ autour de u : (cos θ/2, u sin θ/2). On enchaîne en multipliant, on défait avec le conjugué.","ROS 2 écrit (x, y, z, w) : w en dernier. Cap d'un robot mobile : ψ = 2 atan2(z, w)."]],"keep":[["<p class=\"eq\"><i>q</i> = ( <i>w</i>, <i>x</i>, <i>y</i>, <i>z</i> ) = ( cos <i>θ</i>/2, <i>u</i><sub>x</sub> sin <i>θ</i>/2, <i>u</i><sub>y</sub> sin <i>θ</i>/2, <i>u</i><sub>z</sub> sin <i>θ</i>/2 )</p> <p>Its length is always 1: <i>w</i>² + <i>x</i>² + <i>y</i>² + <i>z</i>² = 1.</p>","<p>Store and compute orientations as <strong>quaternions</strong>, show them to humans as <strong>roll, pitch, yaw</strong>, and convert to a <strong>rotation matrix</strong> when you need to turn many points. Let a library do the conversions, and check its order (w first or last).</p>"],["<p class=\"eq\"><i>q</i> = ( <i>w</i>, <i>x</i>, <i>y</i>, <i>z</i> ) = ( cos <i>θ</i>/2, <i>u</i><sub>x</sub> sin <i>θ</i>/2, <i>u</i><sub>y</sub> sin <i>θ</i>/2, <i>u</i><sub>z</sub> sin <i>θ</i>/2 )</p> <p>Sa longueur vaut toujours 1 : <i>w</i>² + <i>x</i>² + <i>y</i>² + <i>z</i>² = 1.</p>","<p>Stockez et calculez les orientations en <strong>quaternions</strong>, montrez-les aux humains en <strong>roulis, tangage, lacet</strong>, et convertissez en <strong>matrice de rotation</strong> quand vous devez tourner beaucoup de points. Laissez une bibliothèque faire les conversions, et vérifiez son ordre (w en premier ou en dernier).</p>"]],"eq":[["<i>R</i> = <i>R</i><sub>z</sub>(<i>ψ</i>) <i>R</i><sub>y</sub>(<i>θ</i>) <i>R</i><sub>x</sub>(<i>φ</i>)","cos <i>θ</i> = ( trace <i>R</i> − 1 ) / 2 (trace = <i>R</i><sub>11</sub> + <i>R</i><sub>22</sub> + <i>R</i><sub>33</sub>)","<i>q</i> = ( <i>w</i>, <i>x</i>, <i>y</i>, <i>z</i> ) = ( cos <i>θ</i>/2, <i>u</i><sub>x</sub> sin <i>θ</i>/2, <i>u</i><sub>y</sub> sin <i>θ</i>/2, <i>u</i><sub>z</sub> sin <i>θ</i>/2 )","<i>q</i> = ( cos <i>ψ</i>/2, 0, 0, sin <i>ψ</i>/2 ) <i>ψ</i> = 2 atan2(<i>z</i>, <i>w</i>)"],["<i>R</i> = <i>R</i><sub>z</sub>(<i>ψ</i>) <i>R</i><sub>y</sub>(<i>θ</i>) <i>R</i><sub>x</sub>(<i>φ</i>)","cos <i>θ</i> = ( trace <i>R</i> − 1 ) / 2 (trace = <i>R</i><sub>11</sub> + <i>R</i><sub>22</sub> + <i>R</i><sub>33</sub>)","<i>q</i> = ( <i>w</i>, <i>x</i>, <i>y</i>, <i>z</i> ) = ( cos <i>θ</i>/2, <i>u</i><sub>x</sub> sin <i>θ</i>/2, <i>u</i><sub>y</sub> sin <i>θ</i>/2, <i>u</i><sub>z</sub> sin <i>θ</i>/2 )","<i>q</i> = ( cos <i>ψ</i>/2, 0, 0, sin <i>ψ</i>/2 ) <i>ψ</i> = 2 atan2(<i>z</i>, <i>w</i>)"]],"kt":[["roll / pitch / yaw","gimbal lock","axis-angle","rotation vector","quaternion","conjugate","slerp"],["roulis / tangage / lacet","blocage de cardan","axe-angle","vecteur rotation","quaternion","conjugué","slerp"]]}],"t":["The maths of robotics","Les maths de la robotique"]},{"page":"learn-maths","title":["Maths and motion, step by step","Maths et mouvement, pas à pas"],"lessons":[{"id":"l1","n":"1","m":4,"t":["The maths toolbox (without pain)","La boîte à outils mathématique (sans douleur)"],"ess":[["cos θ is the horizontal \"shadow\" of a stick of length 1 turned by θ, sin θ its vertical shadow.","atan2(y, x) gives the angle of a point, in the right quarter, from −180° to 180°.","A matrix is a table of numbers that transforms a vector: each line × the vector gives one component."],["cos θ est l'« ombre » horizontale d'un bâton de longueur 1 tourné de θ, sin θ son ombre verticale.","atan2(y, x) donne l'angle d'un point, dans le bon quart, de −180° à 180°.","Une matrice est un tableau de nombres qui transforme un vecteur : chaque ligne × le vecteur donne une composante."]],"keep":[["<ul><li><strong>Sine and cosine</strong>: the end of a segment of length <i>L</i> at angle <i>θ</i> is at <i>x</i> = <i>L</i> cos <i>θ</i>, <i>y</i> = <i>L</i> sin <i>θ</i>.</li><li><strong>atan2(<i>y</i>, <i>x</i>)</strong>: the angle of a point, right in all four quadrants (never arctan(<i>y</i>/<i>x</i>) alone).</li><li><strong>Vectors</strong>: arrows written as columns; adding them chains moves. The tool of an arm is the sum of the arrows of its links.</li><li><strong>Matrices</strong>: “row times column”; the columns say where the axes go; the order of a product matters.</li></ul>"],[]],"eq":[[],[]],"kt":[["sine / cosine","atan2","vector","matrix"],["sinus / cosinus","atan2","vecteur","matrice"]]},{"id":"l2","n":"2","m":8,"t":["What is a manipulator robot?","Qu'est-ce qu'un robot manipulateur ?"],"ess":[["A manipulator robot is like a human arm: shoulder, elbow, wrist, hand.","Only two kinds of joints exist: revolute (it turns) and prismatic (it slides).","Two \"worlds\": the joint space (the angles) and the task space (where the tool is)."],["Un robot manipulateur ressemble à un bras humain : épaule, coude, poignet, main.","Il n'existe que deux sortes de liaisons : rotoïde (elle tourne) et prismatique (elle glisse).","Deux « mondes » : l'espace articulaire (les angles) et l'espace opérationnel (où est l'outil)."]],"keep":[[],[]],"eq":[[],[]],"kt":[["base","end effector","DOF","joint space","operational space","redundant"],["bâti","effecteur","ddl","espace articulaire","espace opérationnel","redondant"]]},{"id":"l3","n":"3","m":4,"t":["First robot: one single joint","Premier robot : un bras à une seule articulation"],"ess":[["One revolute joint and one link of length L: the tip moves on a circle of radius L.","Direct: x = L cos θ, y = L sin θ. Inverse: θ = atan2(y, x).","Speed of the tip: v = L × ω (ω in rad/s)."],["Une liaison rotoïde et un segment de longueur L : l'extrémité se déplace sur un cercle de rayon L.","Direct : x = L cos θ, y = L sin θ. Inverse : θ = atan2(y, x).","Vitesse de l'extrémité : v = L × ω (ω en rad/s)."]],"keep":[["<p>First important lesson: <strong>the direct model always has an answer, the inverse model not necessarily.</strong></p>"],["<p>Première leçon importante : <strong>le modèle direct a toujours une réponse, le modèle inverse pas forcément.</strong></p>"]],"eq":[["<i>x</i> = <i>L</i> cos <i>θ</i>, <i>y</i> = <i>L</i> sin <i>θ</i>"],["<i>x</i> = <i>L</i> cos <i>θ</i>, <i>y</i> = <i>L</i> sin <i>θ</i>"]],"kt":[["direct model (MGD)","inverse model (MGI)"],["modèle direct (MGD)","modèle inverse (MGI)"]]},{"id":"l4","n":"4","m":15,"t":["The two-joint arm (the heart of the subject)","Le bras à deux articulations (le cœur du sujet)"],"ess":[["Direct model: add the two arrows: x = L₁ cos θ₁ + L₂ cos(θ₁ + θ₂), y = L₁ sin θ₁ + L₂ sin(θ₁ + θ₂).","Inverse model: cos θ₂ = (x² + y² − L₁² − L₂²) / (2 L₁ L₂), then θ₁ from atan2.","Two solutions (elbow left/right); workspace = ring between |L₁ − L₂| and L₁ + L₂."],["Modèle direct : on additionne les deux flèches : x = L₁ cos θ₁ + L₂ cos(θ₁ + θ₂), y = L₁ sin θ₁ + L₂ sin(θ₁ + θ₂).","Modèle inverse : cos θ₂ = (x² + y² − L₁² − L₂²) / (2 L₁ L₂), puis θ₁ avec atan2.","Deux solutions (coude à gauche / à droite) ; espace de travail = anneau entre |L₁ − L₂| et L₁ + L₂."]],"keep":[["<p>The inverse model can have:</p> <ul><li><strong>0 solution</strong>: the point is too far or too close (the number inside the arccos is outside [−1, 1]);</li><li><strong>several solutions</strong>: 2 for this arm (elbow right/left), up to 8 for a 6-axis robot;</li><li><strong>infinitely many</strong>: for a redundant robot (7 axes), or in some particular positions.</li></ul>"],["<p>Le modèle inverse peut avoir :</p> <ul><li><strong>0 solution</strong> : le point est trop loin ou trop près (le nombre dans l'arccos sort de [−1, 1]) ;</li><li><strong>plusieurs solutions</strong> : 2 pour ce bras (coude droite/gauche), jusqu'à 8 pour un robot 6 axes ;</li><li><strong>une infinité</strong> : pour un robot redondant (7 axes), ou dans certaines positions particulières.</li></ul>"]],"eq":[["<i>x</i> = <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>)<br><i>y</i> = <i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>)","<i>x</i> = 0.5 × 0.866 + 0.3 × cos 90° = 0.433 + 0 = 0.433 m<br><i>y</i> = 0.5 × 0.5 + 0.3 × sin 90° = 0.25 + 0.3 = 0.55 m","cos <i>θ</i><sub>2</sub> = <span class=\"frac\"><span><i>x</i>² + <i>y</i>² − <i>L</i><sub>1</sub>² − <i>L</i><sub>2</sub>²</span><span>2 <i>L</i><sub>1</sub> <i>L</i><sub>2</sub></span></span> ⟹ <i>θ</i><sub>2</sub> = ± arccos(…)","<i>θ</i><sub>1</sub> = atan2(<i>y</i>, <i>x</i>) − atan2(<i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>, <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>)"],["<i>x</i> = <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>)<br><i>y</i> = <i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>)","<i>x</i> = 0.5 × 0.866 + 0.3 × cos 90° = 0.433 + 0 = 0.433 m<br><i>y</i> = 0.5 × 0.5 + 0.3 × sin 90° = 0.25 + 0.3 = 0.55 m","cos <i>θ</i><sub>2</sub> = <span class=\"frac\"><span><i>x</i>² + <i>y</i>² − <i>L</i><sub>1</sub>² − <i>L</i><sub>2</sub>²</span><span>2 <i>L</i><sub>1</sub> <i>L</i><sub>2</sub></span></span> ⟹ <i>θ</i><sub>2</sub> = ± arccos(…)","<i>θ</i><sub>1</sub> = atan2(<i>y</i>, <i>x</i>) − atan2(<i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>, <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>)"]],"kt":[["aspect (posture)","Al-Kashi formula","workspace","singularity","joint stops"],["aspect (posture)","formule d'Al-Kashi","espace de travail","singularité","butées"]]},{"id":"l5","n":"5","m":5,"t":["Frames: looking at the world from each piece","Les repères : regarder le monde depuis chaque pièce"],"ess":[["A rotation by θ in the plane is the matrix R = ( cos θ −sin θ ; sin θ cos θ ).","The homogeneous matrix puts rotation and translation in one 4 × 4 (or 3 × 3 in the plane) table.","To chain frames, we multiply the matrices: T₀₂ = T₀₁ × T₁₂."],["Une rotation de θ dans le plan est la matrice R = ( cos θ −sin θ ; sin θ cos θ ).","La matrice homogène met rotation et translation dans un seul tableau 4 × 4 (ou 3 × 3 dans le plan).","Pour enchaîner les repères, on multiplie les matrices : T₀₂ = T₀₁ × T₁₂."]],"keep":[[],[]],"eq":[[],[]],"kt":[["frame","rotation matrix","roll / pitch / yaw","homogeneous matrix"],["repère","matrice de rotation","roulis / tangage / lacet","matrice homogène"]]},{"id":"l6","n":"6","m":5,"t":["The Denavit–Hartenberg method, gently","La méthode Denavit–Hartenberg, en douceur"],"ess":[["DH places one frame per joint with simple rules, so each link is described by only 4 numbers.","Every step = turn θ around z, slide d along z, slide a along x, twist α around x.","For a planar arm, d = 0 and α = 0: only θ and a remain."],["DH place un repère par liaison avec des règles simples, si bien que chaque segment est décrit par seulement 4 nombres.","Chaque pas = tourner de θ autour de z, glisser de d selon z, glisser de a selon x, tordre de α autour de x.","Pour un bras plan, d = 0 et α = 0 : il ne reste que θ et a."]],"keep":[[],[]],"eq":[[],[]],"kt":[["DHm","common perpendicular","DH table"],["DHm","perpendiculaire commune","tableau DH"]]},{"id":"l7","n":"7","m":12,"t":["Moving the robot smoothly: the motion laws","Faire bouger le robot en douceur : les lois de mouvement"],"ess":[["A good motion starts and stops gently: the speed rises, stays constant, then falls (trapezoid).","The area under the speed curve is the distance travelled.","When several motors move together, we slow the fast ones so that all arrive at the same time."],["Un bon mouvement démarre et s'arrête en douceur : la vitesse monte, reste constante, puis descend (trapèze).","L'aire sous la courbe de vitesse est la distance parcourue.","Quand plusieurs moteurs bougent ensemble, on ralentit les plus rapides pour que tous arrivent en même temps."]],"keep":[[],[]],"eq":[[],[]],"kt":[["velocity trapezoid","bang-bang","homothetic trapezoids","joint / linear movement"],["trapèze de vitesse","bang-bang","trapèzes homothétiques","mouvement articulaire / linéaire"]]},{"id":"l8","n":"8","m":5,"t":["Recap: the map of the course","Récapitulatif : la carte du cours"],"ess":[["Geometry (where?) → direct and inverse models; speed (how fast?) → Jacobian; time (when?) → motion laws.","Tools: cos/sin, atan2, vectors, matrices, homogeneous transforms, DH tables.","Next step: the full modelling course (MGD, MGI, Jacobian in 3D)."],["Géométrie (où ?) → modèles direct et inverse ; vitesse (à quelle allure ?) → jacobienne ; temps (quand ?) → lois de mouvement.","Outils : cos/sin, atan2, vecteurs, matrices, transformations homogènes, tableaux DH.","Étape suivante : le cours complet de modélisation (MGD, MGI, jacobienne en 3D)."]],"keep":[["<p>You now have all the basic ideas. The <strong>full course</strong> “Robot modelling” takes these notions in 3D with the real notations (<sup>0</sup><i>T</i><sub>1</sub>, <i>σ</i><sub>j</sub>, <i>α</i><sub>j</sub>, <i>d</i><sub>j</sub>, <i>θ</i><sub>j</sub>, <i>r</i><sub>j</sub>) and real industrial robots (SCARA, Kuka, ABB, UR3). Read it keeping this course nearby: each time a formula looks complicated, look for its 2D equivalent here.</p>"],["<p>Vous avez toutes les idées de base. Le <strong>cours complet</strong> « Modélisation d'un robot » reprend ces notions en 3D avec les vraies notations (<sup>0</sup><i>T</i><sub>1</sub>, <i>σ</i><sub>j</sub>, <i>α</i><sub>j</sub>, <i>d</i><sub>j</sub>, <i>θ</i><sub>j</sub>, <i>r</i><sub>j</sub>) et des robots industriels (SCARA, Kuka, ABB, UR3). Lisez-le en gardant ce cours à côté : chaque fois qu'une formule paraît compliquée, cherchez ici son équivalent en 2D.</p>"]],"eq":[[],[]],"kt":[["MGD","MGI","aspect"],["MGD","MGI","aspect"]]}],"t":["Maths and motion, step by step","Maths et mouvement, pas à pas"]},{"page":"learn-model","title":["Robot modelling, full course","Modélisation d'un robot, cours complet"],"lessons":[{"id":"l1","n":"1","m":10,"t":["Locating an object: position and rotation matrix","Localiser un objet : position et matrice de rotation"],"ess":[["The position of a point is a vector (x, y, z) in a frame.","The orientation of a body is a 3 × 3 rotation matrix R: its columns are the axes of the body written in the reference frame.","R is orthonormal: Rᵀ R = I, so the inverse of R is simply its transpose; det R = +1."],["La position d'un point est un vecteur (x, y, z) dans un repère.","L'orientation d'un corps est une matrice de rotation R 3 × 3 : ses colonnes sont les axes du corps écrits dans le repère de référence.","R est orthonormée : Rᵀ R = I, donc l'inverse de R est simplement sa transposée ; det R = +1."]],"keep":[["<ul><li>It is orthogonal: <sup>0</sup><i>R</i><sub>1</sub><sup>−1</sup> = <sup>0</sup><i>R</i><sub>1</sub><sup>T</sup> = <sup>1</sup><i>R</i><sub>0</sub> (the inverse is computed by a simple transposition).</li><li>det <i>R</i> = +1; each column (and each row) is a unit vector; two columns are orthogonal.</li><li>Composition: <sup>0</sup><i>R</i><sub>2</sub> = <sup>0</sup><i>R</i><sub>1</sub> <sup>1</sup><i>R</i><sub>2</sub> (the indices “chain together”).</li></ul>"],["<ul><li>Elle est orthogonale : <sup>0</sup><i>R</i><sub>1</sub><sup>−1</sup> = <sup>0</sup><i>R</i><sub>1</sub><sup>T</sup> = <sup>1</sup><i>R</i><sub>0</sub> (l'inverse se calcule par simple transposition).</li><li>det <i>R</i> = +1 ; chaque colonne (et chaque ligne) est un vecteur unitaire ; colonnes deux à deux orthogonales.</li><li>Composition : <sup>0</sup><i>R</i><sub>2</sub> = <sup>0</sup><i>R</i><sub>1</sub> <sup>1</sup><i>R</i><sub>2</sub> (les indices « s'enchaînent »).</li></ul>"]],"eq":[["Rot(<i>x</i>, <i>θ</i>) = <span class=\"mx c3\"><span>1</span><span>0</span><span>0</span><span>0</span><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>0</span><span>sin <i>θ</i></span><span>cos <i>θ</i></span></span><br>Rot(<i>y</i>, <i>θ</i>) = <span class=\"mx c3\"><span>cos <i>θ</i></span><span>0</span><span>sin <i>θ</i></span><span>0</span><span>1</span><span>0</span><span>−sin <i>θ</i></span><span>0</span><span>cos <i>θ</i></span></span><br>Rot(<i>z</i>, <i>θ</i>) = <span class=\"mx c3\"><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>0</span><span>sin <i>θ</i></span><span>cos <i>θ</i></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<sup>0</sup><i>p</i> = <span class=\"mx c1\"><span>(√2/2)(−2) − (√2/2)(1)</span><span>(√2/2)(−2) + (√2/2)(1)</span><span>0</span></span> = <span class=\"mx c1\"><span>−3√2/2</span><span>−√2/2</span><span>0</span></span> ≈ <span class=\"mx c1\"><span>−2.121</span><span>−0.707</span><span>0</span></span>"],["Rot(<i>x</i>, <i>θ</i>) = <span class=\"mx c3\"><span>1</span><span>0</span><span>0</span><span>0</span><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>0</span><span>sin <i>θ</i></span><span>cos <i>θ</i></span></span><br>Rot(<i>y</i>, <i>θ</i>) = <span class=\"mx c3\"><span>cos <i>θ</i></span><span>0</span><span>sin <i>θ</i></span><span>0</span><span>1</span><span>0</span><span>−sin <i>θ</i></span><span>0</span><span>cos <i>θ</i></span></span><br>Rot(<i>z</i>, <i>θ</i>) = <span class=\"mx c3\"><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>0</span><span>sin <i>θ</i></span><span>cos <i>θ</i></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<sup>0</sup><i>p</i> = <span class=\"mx c1\"><span>(√2/2)(−2) − (√2/2)(1)</span><span>(√2/2)(−2) + (√2/2)(1)</span><span>0</span></span> = <span class=\"mx c1\"><span>−3√2/2</span><span>−√2/2</span><span>0</span></span> ≈ <span class=\"mx c1\"><span>−2.121</span><span>−0.707</span><span>0</span></span>"]],"kt":[["reference frame","rotation matrix","direction cosines","orthogonal matrix"],["repère de référence","matrice de rotation","cosinus directeurs","matrice orthogonale"]]},{"id":"l2","n":"2","m":15,"t":["Describing the orientation with 3 angles: Euler and Cardan","Décrire l'orientation avec 3 angles : Euler et Cardan"],"ess":[["Three angles are enough to describe any orientation (but 9 numbers are in R).","Euler (Z-Y-Z) or Cardan / roll-pitch-yaw (Z-Y-X): the order of the rotations matters.","At some angles two axes line up and one angle is lost: that is gimbal lock."],["Trois angles suffisent pour décrire n'importe quelle orientation (alors que R contient 9 nombres).","Euler (Z-Y-Z) ou Cardan / roulis-tangage-lacet (Z-Y-X) : l'ordre des rotations compte.","Pour certains angles, deux axes s'alignent et un angle est perdu : c'est le blocage de cardan."]],"keep":[[],[]],"eq":[["<sup>A</sup><i>R</i><sub>B</sub> = <i>R</i><sub>Euler</sub> = Rot(<i>z</i>, <i>φ</i>) Rot(<i>x</i>, <i>θ</i>) Rot(<i>z</i>, <i>ψ</i>) = <span class=\"mx c3\"><span>c<i>φ</i>c<i>ψ</i> − s<i>φ</i>c<i>θ</i>s<i>ψ</i></span><span>−c<i>φ</i>s<i>ψ</i> − s<i>φ</i>c<i>θ</i>c<i>ψ</i></span><span>s<i>φ</i>s<i>θ</i></span><span>s<i>φ</i>c<i>ψ</i> + c<i>φ</i>c<i>θ</i>s<i>ψ</i></span><span>−s<i>φ</i>s<i>ψ</i> + c<i>φ</i>c<i>θ</i>c<i>ψ</i></span><span>−c<i>φ</i>s<i>θ</i></span><span>s<i>θ</i>s<i>ψ</i></span><span>s<i>θ</i>c<i>ψ</i></span><span>c<i>θ</i></span></span>","<sup>A</sup><i>R</i><sub>B</sub> = <i>R</i><sub>Cardan</sub> = Rot(<i>z</i>, <i>α</i>) Rot(<i>y</i>, <i>β</i>) Rot(<i>x</i>, <i>γ</i>) = <span class=\"mx c3\"><span>c<i>α</i>c<i>β</i></span><span>c<i>α</i>s<i>β</i>s<i>γ</i> − s<i>α</i>c<i>γ</i></span><span>c<i>α</i>s<i>β</i>c<i>γ</i> + s<i>α</i>s<i>γ</i></span><span>s<i>α</i>c<i>β</i></span><span>s<i>α</i>s<i>β</i>s<i>γ</i> + c<i>α</i>c<i>γ</i></span><span>s<i>α</i>s<i>β</i>c<i>γ</i> − c<i>α</i>s<i>γ</i></span><span>−s<i>β</i></span><span>c<i>β</i>s<i>γ</i></span><span>c<i>β</i>c<i>γ</i></span></span>"],["<sup>A</sup><i>R</i><sub>B</sub> = <i>R</i><sub>Euler</sub> = Rot(<i>z</i>, <i>φ</i>) Rot(<i>x</i>, <i>θ</i>) Rot(<i>z</i>, <i>ψ</i>) = <span class=\"mx c3\"><span>c<i>φ</i>c<i>ψ</i> − s<i>φ</i>c<i>θ</i>s<i>ψ</i></span><span>−c<i>φ</i>s<i>ψ</i> − s<i>φ</i>c<i>θ</i>c<i>ψ</i></span><span>s<i>φ</i>s<i>θ</i></span><span>s<i>φ</i>c<i>ψ</i> + c<i>φ</i>c<i>θ</i>s<i>ψ</i></span><span>−s<i>φ</i>s<i>ψ</i> + c<i>φ</i>c<i>θ</i>c<i>ψ</i></span><span>−c<i>φ</i>s<i>θ</i></span><span>s<i>θ</i>s<i>ψ</i></span><span>s<i>θ</i>c<i>ψ</i></span><span>c<i>θ</i></span></span>","<sup>A</sup><i>R</i><sub>B</sub> = <i>R</i><sub>Cardan</sub> = Rot(<i>z</i>, <i>α</i>) Rot(<i>y</i>, <i>β</i>) Rot(<i>x</i>, <i>γ</i>) = <span class=\"mx c3\"><span>c<i>α</i>c<i>β</i></span><span>c<i>α</i>s<i>β</i>s<i>γ</i> − s<i>α</i>c<i>γ</i></span><span>c<i>α</i>s<i>β</i>c<i>γ</i> + s<i>α</i>s<i>γ</i></span><span>s<i>α</i>c<i>β</i></span><span>s<i>α</i>s<i>β</i>s<i>γ</i> + c<i>α</i>c<i>γ</i></span><span>s<i>α</i>s<i>β</i>c<i>γ</i> − c<i>α</i>s<i>γ</i></span><span>−s<i>β</i></span><span>c<i>β</i>s<i>γ</i></span><span>c<i>β</i>c<i>γ</i></span></span>"]],"kt":[["Euler angles","Cardan / roll–pitch–yaw","gimbal lock","atan2"],["angles d'Euler","Cardan / roulis–tangage–lacet","blocage de cardan","atan2"]]},{"id":"l3","n":"3","m":12,"t":["Homogeneous transformation matrices","Les matrices de transformation homogène"],"ess":[["T = ( R p ; 0 0 0 1 ) puts the rotation R and the position p in one 4 × 4 matrix.","A point is written (x, y, z, 1); then p₀ = T₀₁ p₁ in one multiplication.","Chaining: T₀₂ = T₀₁ T₁₂. Inverse: T⁻¹ = ( Rᵀ −Rᵀp ; 0 1 )."],["T = ( R p ; 0 0 0 1 ) met la rotation R et la position p dans une seule matrice 4 × 4.","Un point s'écrit (x, y, z, 1) ; alors p₀ = T₀₁ p₁ en une seule multiplication.","Enchaînement : T₀₂ = T₀₁ T₁₂. Inverse : T⁻¹ = ( Rᵀ −Rᵀp ; 0 1 )."]],"keep":[["<p>We add a 4th component:</p> <ul><li>for a <strong>point</strong>: 1, <sup>i</sup><i>P</i> = (<i>x</i>, <i>y</i>, <i>z</i>, 1)<sup>T</sup> ⟹ the translation applies;</li><li>for a <strong>vector</strong>: 0, <sup>i</sup><i>V</i> = (<i>α</i>, <i>β</i>, <i>γ</i>, 0)<sup>T</sup> ⟹ the translation does not apply (a free vector does not “translate”).</li></ul> <p>In both cases: <sup>0</sup><i>P</i> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>P</i> and <sup>0</sup><i>V</i> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>V</i>.</p>"],["<p>On ajoute une 4<sup>e</sup> composante :</p> <ul><li>pour un <strong>point</strong> : 1, <sup>i</sup><i>P</i> = (<i>x</i>, <i>y</i>, <i>z</i>, 1)<sup>T</sup> ⟹ la translation s'applique ;</li><li>pour un <strong>vecteur</strong> : 0, <sup>i</sup><i>V</i> = (<i>α</i>, <i>β</i>, <i>γ</i>, 0)<sup>T</sup> ⟹ la translation ne s'applique pas (un vecteur libre ne « se translate » pas).</li></ul> <p>Dans les deux cas : <sup>0</sup><i>P</i> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>P</i> et <sup>0</sup><i>V</i> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>V</i>.</p>"]],"eq":[["<sup>i</sup><i>T</i><sub>j</sub> = ( <sup>i</sup><i>R</i><sub>j</sub> | <sup>i</sup><i>P</i><sub>j</sub> ; 0 0 0 | 1 ) = <span class=\"mx c4\"><span><i>s</i><sub>x</sub></span><span><i>n</i><sub>x</sub></span><span><i>a</i><sub>x</sub></span><span><i>P</i><sub>x</sub></span><span><i>s</i><sub>y</sub></span><span><i>n</i><sub>y</sub></span><span><i>a</i><sub>y</sub></span><span><i>P</i><sub>y</sub></span><span><i>s</i><sub>z</sub></span><span><i>n</i><sub>z</sub></span><span><i>a</i><sub>z</sub></span><span><i>P</i><sub>z</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","Trans(<i>a</i>, <i>b</i>, <i>c</i>) = <span class=\"mx c4\"><span>1</span><span>0</span><span>0</span><span><i>a</i></span><span>0</span><span>1</span><span>0</span><span><i>b</i></span><span>0</span><span>0</span><span>1</span><span><i>c</i></span><span>0</span><span>0</span><span>0</span><span>1</span></span> Rot(<i>x</i>, <i>θ</i>) = <span class=\"mx c4\"><span>1</span><span>0</span><span>0</span><span>0</span><span>0</span><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>0</span><span>0</span><span>sin <i>θ</i></span><span>cos <i>θ</i></span><span>0</span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<sup>0</sup><i>T</i><sub>n</sub> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>T</i><sub>2</sub> <sup>2</sup><i>T</i><sub>3</sub> … <sup>n−1</sup><i>T</i><sub>n</sub> <sup>j</sup><i>T</i><sub>i</sub> = (<sup>i</sup><i>T</i><sub>j</sub>)<sup>−1</sup> = ( <sup>i</sup><i>R</i><sub>j</sub><sup>T</sup> −<sup>i</sup><i>R</i><sub>j</sub><sup>T</sup> <sup>i</sup><i>P</i><sub>j</sub> ; 0 0 0 | 1 )","<sup>B</sup><i>T</i><sub>D</sub> = <sup>B</sup><i>T</i><sub>A</sub> <sup>A</sup><i>T</i><sub>U</sub> <sup>U</sup><i>T</i><sub>C</sub> <sup>C</sup><i>T</i><sub>D</sub> = (<sup>A</sup><i>T</i><sub>B</sub>)<sup>−1</sup> (<sup>U</sup><i>T</i><sub>A</sub>)<sup>−1</sup> <sup>U</sup><i>T</i><sub>C</sub> <sup>C</sup><i>T</i><sub>D</sub>"],["<sup>i</sup><i>T</i><sub>j</sub> = ( <sup>i</sup><i>R</i><sub>j</sub> | <sup>i</sup><i>P</i><sub>j</sub> ; 0 0 0 | 1 ) = <span class=\"mx c4\"><span><i>s</i><sub>x</sub></span><span><i>n</i><sub>x</sub></span><span><i>a</i><sub>x</sub></span><span><i>P</i><sub>x</sub></span><span><i>s</i><sub>y</sub></span><span><i>n</i><sub>y</sub></span><span><i>a</i><sub>y</sub></span><span><i>P</i><sub>y</sub></span><span><i>s</i><sub>z</sub></span><span><i>n</i><sub>z</sub></span><span><i>a</i><sub>z</sub></span><span><i>P</i><sub>z</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","Trans(<i>a</i>, <i>b</i>, <i>c</i>) = <span class=\"mx c4\"><span>1</span><span>0</span><span>0</span><span><i>a</i></span><span>0</span><span>1</span><span>0</span><span><i>b</i></span><span>0</span><span>0</span><span>1</span><span><i>c</i></span><span>0</span><span>0</span><span>0</span><span>1</span></span> Rot(<i>x</i>, <i>θ</i>) = <span class=\"mx c4\"><span>1</span><span>0</span><span>0</span><span>0</span><span>0</span><span>cos <i>θ</i></span><span>−sin <i>θ</i></span><span>0</span><span>0</span><span>sin <i>θ</i></span><span>cos <i>θ</i></span><span>0</span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<sup>0</sup><i>T</i><sub>n</sub> = <sup>0</sup><i>T</i><sub>1</sub> <sup>1</sup><i>T</i><sub>2</sub> <sup>2</sup><i>T</i><sub>3</sub> … <sup>n−1</sup><i>T</i><sub>n</sub> <sup>j</sup><i>T</i><sub>i</sub> = (<sup>i</sup><i>T</i><sub>j</sub>)<sup>−1</sup> = ( <sup>i</sup><i>R</i><sub>j</sub><sup>T</sup> −<sup>i</sup><i>R</i><sub>j</sub><sup>T</sup> <sup>i</sup><i>P</i><sub>j</sub> ; 0 0 0 | 1 )","<sup>B</sup><i>T</i><sub>D</sub> = <sup>B</sup><i>T</i><sub>A</sub> <sup>A</sup><i>T</i><sub>U</sub> <sup>U</sup><i>T</i><sub>C</sub> <sup>C</sup><i>T</i><sub>D</sub> = (<sup>A</sup><i>T</i><sub>B</sub>)<sup>−1</sup> (<sup>U</sup><i>T</i><sub>A</sub>)<sup>−1</sup> <sup>U</sup><i>T</i><sub>C</sub> <sup>C</sup><i>T</i><sub>D</sub>"]],"kt":[["homogeneous matrix","homogeneous coordinates","composition","inverse transformation"],["matrice homogène","coordonnées homogènes","composition","transformation inverse"]]},{"id":"l4","n":"4","m":25,"t":["Placing the frames: the modified Denavit–Hartenberg convention (DHm)","Placer les repères : la convention de Denavit–Hartenberg modifiée (DHm)"],"ess":[["Modified DH (Khalil–Kleinfinger): frame i is on the axis of joint i.","Each line: α (twist about x), d (along x), θ (about z), r (along z), in this order.","The variable is θ for a revolute joint and r for a prismatic joint (σ = 0 or 1)."],["DH modifiée (Khalil–Kleinfinger) : le repère i est sur l'axe de la liaison i.","Chaque ligne : α (torsion autour de x), d (selon x), θ (autour de z), r (selon z), dans cet ordre.","La variable est θ pour une liaison rotoïde et r pour une liaison prismatique (σ = 0 ou 1)."]],"keep":[["<ul><li><i>α</i><sub>j</sub> and <i>d</i><sub>j</sub> are <strong>always constant</strong> (dimensional parameters of the robot).</li><li><strong>Pivot</strong> joint (<i>σ</i><sub>j</sub> = 0): the joint variable is <i>q</i><sub>j</sub> = <i>θ</i><sub>j</sub>; <i>r</i><sub>j</sub> is constant.</li><li><strong>Slider</strong> joint (<i>σ</i><sub>j</sub> = 1): the joint variable is <i>q</i><sub>j</sub> = <i>r</i><sub>j</sub>; <i>θ</i><sub>j</sub> is constant.</li><li>In short: <i>q</i><sub>j</sub> = <i>σ̄</i><sub>j</sub> <i>θ</i><sub>j</sub> + <i>σ</i><sub>j</sub> <i>r</i><sub>j</sub> with <i>σ̄</i><sub>j</sub> = 1 − <i>σ</i><sub>j</sub>.</li><li>For a robot with <i>n</i> DOF: 5<i>n</i> parameters, arranged in the <strong>Denavit–Hartenberg table</strong>.</li></ul>"],["<ul><li><i>α</i><sub>j</sub> et <i>d</i><sub>j</sub> sont <strong>toujours constants</strong> (paramètres dimensionnels du robot).</li><li>Liaison <strong>pivot</strong> (<i>σ</i><sub>j</sub> = 0) : la variable articulaire est <i>q</i><sub>j</sub> = <i>θ</i><sub>j</sub> ; <i>r</i><sub>j</sub> est constant.</li><li>Liaison <strong>glissière</strong> (<i>σ</i><sub>j</sub> = 1) : la variable articulaire est <i>q</i><sub>j</sub> = <i>r</i><sub>j</sub> ; <i>θ</i><sub>j</sub> est constant.</li><li>En résumé : <i>q</i><sub>j</sub> = <i>σ̄</i><sub>j</sub> <i>θ</i><sub>j</sub> + <i>σ</i><sub>j</sub> <i>r</i><sub>j</sub> avec <i>σ̄</i><sub>j</sub> = 1 − <i>σ</i><sub>j</sub>.</li><li>Pour un robot à <i>n</i> ddl : 5<i>n</i> paramètres, rangés dans le <strong>tableau de Denavit–Hartenberg</strong>.</li></ul>"]],"eq":[["<sup>j−1</sup><i>T</i><sub>j</sub> = Rot(<i>x</i>, <i>α</i><sub>j</sub>) Trans(<i>x</i>, <i>d</i><sub>j</sub>) Rot(<i>z</i>, <i>θ</i><sub>j</sub>) Trans(<i>z</i>, <i>r</i><sub>j</sub>)","<sup>j−1</sup><i>T</i><sub>j</sub> = <span class=\"mx c4\"><span>cos <i>θ</i><sub>j</sub></span><span>−sin <i>θ</i><sub>j</sub></span><span>0</span><span><i>d</i><sub>j</sub></span><span>cos <i>α</i><sub>j</sub> sin <i>θ</i><sub>j</sub></span><span>cos <i>α</i><sub>j</sub> cos <i>θ</i><sub>j</sub></span><span>−sin <i>α</i><sub>j</sub></span><span>−<i>r</i><sub>j</sub> sin <i>α</i><sub>j</sub></span><span>sin <i>α</i><sub>j</sub> sin <i>θ</i><sub>j</sub></span><span>sin <i>α</i><sub>j</sub> cos <i>θ</i><sub>j</sub></span><span>cos <i>α</i><sub>j</sub></span><span><i>r</i><sub>j</sub> cos <i>α</i><sub>j</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<sup>0</sup><i>T</i><sub>4</sub> = <span class=\"mx c4\"><span><i>c</i><sub>124</sub></span><span>−<i>s</i><sub>124</sub></span><span>0</span><span><i>d</i><sub>2</sub><i>c</i><sub>1</sub> + <i>d</i><sub>3</sub><i>c</i><sub>12</sub></span><span><i>s</i><sub>124</sub></span><span><i>c</i><sub>124</sub></span><span>0</span><span><i>d</i><sub>2</sub><i>s</i><sub>1</sub> + <i>d</i><sub>3</sub><i>s</i><sub>12</sub></span><span>0</span><span>0</span><span>1</span><span><i>r</i><sub>1</sub> + <i>q</i><sub>3</sub> − <i>r</i><sub>4</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>"],["<sup>j−1</sup><i>T</i><sub>j</sub> = Rot(<i>x</i>, <i>α</i><sub>j</sub>) Trans(<i>x</i>, <i>d</i><sub>j</sub>) Rot(<i>z</i>, <i>θ</i><sub>j</sub>) Trans(<i>z</i>, <i>r</i><sub>j</sub>)","<sup>j−1</sup><i>T</i><sub>j</sub> = <span class=\"mx c4\"><span>cos <i>θ</i><sub>j</sub></span><span>−sin <i>θ</i><sub>j</sub></span><span>0</span><span><i>d</i><sub>j</sub></span><span>cos <i>α</i><sub>j</sub> sin <i>θ</i><sub>j</sub></span><span>cos <i>α</i><sub>j</sub> cos <i>θ</i><sub>j</sub></span><span>−sin <i>α</i><sub>j</sub></span><span>−<i>r</i><sub>j</sub> sin <i>α</i><sub>j</sub></span><span>sin <i>α</i><sub>j</sub> sin <i>θ</i><sub>j</sub></span><span>sin <i>α</i><sub>j</sub> cos <i>θ</i><sub>j</sub></span><span>cos <i>α</i><sub>j</sub></span><span><i>r</i><sub>j</sub> cos <i>α</i><sub>j</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<sup>0</sup><i>T</i><sub>4</sub> = <span class=\"mx c4\"><span><i>c</i><sub>124</sub></span><span>−<i>s</i><sub>124</sub></span><span>0</span><span><i>d</i><sub>2</sub><i>c</i><sub>1</sub> + <i>d</i><sub>3</sub><i>c</i><sub>12</sub></span><span><i>s</i><sub>124</sub></span><span><i>c</i><sub>124</sub></span><span>0</span><span><i>d</i><sub>2</sub><i>s</i><sub>1</sub> + <i>d</i><sub>3</sub><i>s</i><sub>12</sub></span><span>0</span><span>0</span><span>1</span><span><i>r</i><sub>1</sub> + <i>q</i><sub>3</sub> − <i>r</i><sub>4</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>"]],"kt":[["DHm convention","common perpendicular","joint variable","transition matrix"],["convention DHm","perpendiculaire commune","variable articulaire","matrice de passage"]]},{"id":"l5","n":"5","m":8,"t":["The Direct Geometric Model (MGD)","Le Modèle Géométrique Direct (MGD)"],"ess":[["The MGD gives the pose of the tool from the joint variables: T₀ₙ = T₀₁ T₁₂ … Tₙ₋₁ₙ.","For a planar chain, add the links like arrows, each one turned by the sum of the angles before it.","The MGD always has exactly one result."],["Le MGD donne la pose de l'outil à partir des variables articulaires : T₀ₙ = T₀₁ T₁₂ … Tₙ₋₁ₙ.","Pour une chaîne plane, on additionne les segments comme des flèches, chacun tourné de la somme des angles avant lui.","Le MGD a toujours exactement un résultat."]],"keep":[[],[]],"eq":[["<i>X</i> = <i>f</i>(<i>q</i>) ⟺ <sup>0</sup><i>T</i><sub>n</sub>(<i>q</i>) = <sup>0</sup><i>T</i><sub>1</sub>(<i>q</i><sub>1</sub>) <sup>1</sup><i>T</i><sub>2</sub>(<i>q</i><sub>2</sub>) … <sup>n−1</sup><i>T</i><sub>n</sub>(<i>q</i><sub>n</sub>)","<i>X</i><sub>E</sub> = <i>a</i><sub>1</sub> cos <i>q</i><sub>1</sub> + <i>a</i><sub>2</sub> cos(<i>q</i><sub>1</sub>+<i>q</i><sub>2</sub>)<br><i>Y</i><sub>E</sub> = <i>a</i><sub>1</sub> sin <i>q</i><sub>1</sub> + <i>a</i><sub>2</sub> sin(<i>q</i><sub>1</sub>+<i>q</i><sub>2</sub>)<br><i>Z</i><sub>E</sub> = <i>h</i> + <i>q</i><sub>3</sub><br><i>θ</i><sub>E</sub> = <i>q</i><sub>1</sub> + <i>q</i><sub>2</sub> + <i>q</i><sub>4</sub>"],["<i>X</i> = <i>f</i>(<i>q</i>) ⟺ <sup>0</sup><i>T</i><sub>n</sub>(<i>q</i>) = <sup>0</sup><i>T</i><sub>1</sub>(<i>q</i><sub>1</sub>) <sup>1</sup><i>T</i><sub>2</sub>(<i>q</i><sub>2</sub>) … <sup>n−1</sup><i>T</i><sub>n</sub>(<i>q</i><sub>n</sub>)","<i>X</i><sub>E</sub> = <i>a</i><sub>1</sub> cos <i>q</i><sub>1</sub> + <i>a</i><sub>2</sub> cos(<i>q</i><sub>1</sub>+<i>q</i><sub>2</sub>)<br><i>Y</i><sub>E</sub> = <i>a</i><sub>1</sub> sin <i>q</i><sub>1</sub> + <i>a</i><sub>2</sub> sin(<i>q</i><sub>1</sub>+<i>q</i><sub>2</sub>)<br><i>Z</i><sub>E</sub> = <i>h</i> + <i>q</i><sub>3</sub><br><i>θ</i><sub>E</sub> = <i>q</i><sub>1</sub> + <i>q</i><sub>2</sub> + <i>q</i><sub>4</sub>"]],"kt":[["MGD","situation","tool offset"],["MGD","situation","décalage d'outil"]]},{"id":"l6","n":"6","m":15,"t":["The Inverse Geometric Model (MGI)","Le Modèle Géométrique Inverse (MGI)"],"ess":[["The MGI finds the joint variables that put the tool at a wanted pose.","It may have no solution, a finite number (often 2, up to 8 for a 6-axis robot) or an infinity (redundant robot).","For a 6-axis robot with a spherical wrist: first the position of the wrist (3 first joints), then the orientation (3 last)."],["Le MGI trouve les variables articulaires qui placent l'outil à une pose voulue.","Il peut n'avoir aucune solution, un nombre fini (souvent 2, jusqu'à 8 pour un robot 6 axes) ou une infinité (robot redondant).","Pour un robot 6 axes à poignet sphérique : d'abord la position du poignet (3 premières liaisons), puis l'orientation (3 dernières)."]],"keep":[[],[]],"eq":[["<i>q</i> = <i>f</i><sup>−1</sup>(<i>X</i>) that is: solve <sup>0</sup><i>T</i><sub>n</sub>(<i>q</i>) = <i>U</i><sub>0</sub> = <span class=\"mx c4\"><span><i>s</i><sub>x</sub></span><span><i>n</i><sub>x</sub></span><span><i>a</i><sub>x</sub></span><span><i>P</i><sub>x</sub></span><span><i>s</i><sub>y</sub></span><span><i>n</i><sub>y</sub></span><span><i>a</i><sub>y</sub></span><span><i>P</i><sub>y</sub></span><span><i>s</i><sub>z</sub></span><span><i>n</i><sub>z</sub></span><span><i>a</i><sub>z</sub></span><span><i>P</i><sub>z</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<i>X</i><sub>E</sub>² + <i>Y</i><sub>E</sub>² = <i>a</i><sub>1</sub>² + <i>a</i><sub>2</sub>² + 2<i>a</i><sub>1</sub><i>a</i><sub>2</sub> cos <i>θ</i><sub>2</sub> ⟹ cos <i>θ</i><sub>2</sub> = <span class=\"frac\"><span><i>X</i><sub>E</sub>² + <i>Y</i><sub>E</sub>² − (<i>a</i><sub>1</sub>² + <i>a</i><sub>2</sub>²)</span><span>2<i>a</i><sub>1</sub><i>a</i><sub>2</sub></span></span>","<i>θ</i><sub>2</sub> = <i>δ</i> arccos( <span class=\"frac\"><span><i>X</i><sub>E</sub>² + <i>Y</i><sub>E</sub>² − (<i>a</i><sub>1</sub>² + <i>a</i><sub>2</sub>²)</span><span>2<i>a</i><sub>1</sub><i>a</i><sub>2</sub></span></span> ), <i>δ</i> = ±1","<i>θ</i><sub>1</sub> = atan2(<i>Y</i><sub>E</sub>, <i>X</i><sub>E</sub>) − atan2(<i>a</i><sub>2</sub> sin <i>θ</i><sub>2</sub>, <i>a</i><sub>1</sub> + <i>a</i><sub>2</sub> cos <i>θ</i><sub>2</sub>)"],["<i>q</i> = <i>f</i><sup>−1</sup>(<i>X</i>) c'est-à-dire résoudre <sup>0</sup><i>T</i><sub>n</sub>(<i>q</i>) = <i>U</i><sub>0</sub> = <span class=\"mx c4\"><span><i>s</i><sub>x</sub></span><span><i>n</i><sub>x</sub></span><span><i>a</i><sub>x</sub></span><span><i>P</i><sub>x</sub></span><span><i>s</i><sub>y</sub></span><span><i>n</i><sub>y</sub></span><span><i>a</i><sub>y</sub></span><span><i>P</i><sub>y</sub></span><span><i>s</i><sub>z</sub></span><span><i>n</i><sub>z</sub></span><span><i>a</i><sub>z</sub></span><span><i>P</i><sub>z</sub></span><span>0</span><span>0</span><span>0</span><span>1</span></span>","<i>X</i><sub>E</sub>² + <i>Y</i><sub>E</sub>² = <i>a</i><sub>1</sub>² + <i>a</i><sub>2</sub>² + 2<i>a</i><sub>1</sub><i>a</i><sub>2</sub> cos <i>θ</i><sub>2</sub> ⟹ cos <i>θ</i><sub>2</sub> = <span class=\"frac\"><span><i>X</i><sub>E</sub>² + <i>Y</i><sub>E</sub>² − (<i>a</i><sub>1</sub>² + <i>a</i><sub>2</sub>²)</span><span>2<i>a</i><sub>1</sub><i>a</i><sub>2</sub></span></span>","<i>θ</i><sub>2</sub> = <i>δ</i> arccos( <span class=\"frac\"><span><i>X</i><sub>E</sub>² + <i>Y</i><sub>E</sub>² − (<i>a</i><sub>1</sub>² + <i>a</i><sub>2</sub>²)</span><span>2<i>a</i><sub>1</sub><i>a</i><sub>2</sub></span></span> ), <i>δ</i> = ±1","<i>θ</i><sub>1</sub> = atan2(<i>Y</i><sub>E</sub>, <i>X</i><sub>E</sub>) − atan2(<i>a</i><sub>2</sub> sin <i>θ</i><sub>2</sub>, <i>a</i><sub>1</sub> + <i>a</i><sub>2</sub> cos <i>θ</i><sub>2</sub>)"]],"kt":[["MGI","aspect / posture","Paul method","decoupling"],["MGI","aspect / posture","méthode de Paul","découplage"]]},{"id":"l7","n":"7","m":12,"t":["Joint space, operational space and workspace","Espace articulaire, espace opérationnel et volume de travail"],"ess":[["Joint space: the vector q of the joint variables. Operational space: the pose X of the tool.","The workspace is the set of positions the tool can reach, with the joint limits.","The number of degrees of freedom of the task tells how many joints are needed."],["Espace articulaire : le vecteur q des variables articulaires. Espace opérationnel : la pose X de l'outil.","L'espace de travail est l'ensemble des positions que l'outil peut atteindre, avec les butées.","Le nombre de degrés de liberté de la tâche dit combien de liaisons il faut."]],"keep":[[],[]],"eq":[["| <i>L</i><sub>1</sub> − <i>L</i><sub>2</sub> | ≤ √( <i>x</i>² + <i>y</i>² ) ≤ <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub>"],["| <i>L</i><sub>1</sub> − <i>L</i><sub>2</sub> | ≤ √( <i>x</i>² + <i>y</i>² ) ≤ <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub>"]],"kt":[["joint space","operational space","workspace","joint stops"],["espace articulaire","espace opérationnel","volume de travail","butées articulaires"]]},{"id":"l8","n":"8","m":12,"t":["The kinematic model: the Jacobian matrix","Le modèle cinématique : la matrice jacobienne"],"ess":[["The Jacobian J links the joint speeds to the tool speed: Ẋ = J(q) q̇.","Each column of J is the tool speed when only one joint moves at 1 rad/s.","When det J = 0 the robot is singular: it cannot move the tool in some direction."],["La jacobienne J relie les vitesses articulaires à la vitesse de l'outil : Ẋ = J(q) q̇.","Chaque colonne de J est la vitesse de l'outil quand une seule liaison bouge à 1 rad/s.","Quand det J = 0, le robot est singulier : il ne peut plus déplacer l'outil dans une certaine direction."]],"keep":[[],[]],"eq":[["<i>X˙</i> = <i>J</i>(<i>q</i>) <i>q˙</i>, <i>J</i><sub>ij</sub> = <span class=\"frac\"><span>∂<i>f</i><sub>i</sub>(<i>q</i>)</span><span>∂<i>q</i><sub>j</sub></span></span> (matrix <i>m</i> × <i>n</i>)","<i>j</i><sub>k</sub> = <span class=\"mx c1\"><span><i>σ</i><sub>k</sub> <i>a</i><sub>k</sub> + <i>σ̄</i><sub>k</sub> (<i>a</i><sub>k</sub> ∧ <i>L</i><sub>k,n</sub>)</span><span><i>σ̄</i><sub>k</sub> <i>a</i><sub>k</sub></span></span>","<i>J</i> = <span class=\"mx c2\"><span>−<i>a</i><sub>1</sub><i>s</i><sub>1</sub> − <i>a</i><sub>2</sub><i>s</i><sub>12</sub></span><span>−<i>a</i><sub>2</sub><i>s</i><sub>12</sub></span><span><i>a</i><sub>1</sub><i>c</i><sub>1</sub> + <i>a</i><sub>2</sub><i>c</i><sub>12</sub></span><span><i>a</i><sub>2</sub><i>c</i><sub>12</sub></span></span>, det <i>J</i> = <i>a</i><sub>1</sub><i>a</i><sub>2</sub> sin <i>θ</i><sub>2</sub>"],["<i>X˙</i> = <i>J</i>(<i>q</i>) <i>q˙</i>, <i>J</i><sub>ij</sub> = <span class=\"frac\"><span>∂<i>f</i><sub>i</sub>(<i>q</i>)</span><span>∂<i>q</i><sub>j</sub></span></span> (matrix <i>m</i> × <i>n</i>)","<i>j</i><sub>k</sub> = <span class=\"mx c1\"><span><i>σ</i><sub>k</sub> <i>a</i><sub>k</sub> + <i>σ̄</i><sub>k</sub> (<i>a</i><sub>k</sub> ∧ <i>L</i><sub>k,n</sub>)</span><span><i>σ̄</i><sub>k</sub> <i>a</i><sub>k</sub></span></span>","<i>J</i> = <span class=\"mx c2\"><span>−<i>a</i><sub>1</sub><i>s</i><sub>1</sub> − <i>a</i><sub>2</sub><i>s</i><sub>12</sub></span><span>−<i>a</i><sub>2</sub><i>s</i><sub>12</sub></span><span><i>a</i><sub>1</sub><i>c</i><sub>1</sub> + <i>a</i><sub>2</sub><i>c</i><sub>12</sub></span><span><i>a</i><sub>2</sub><i>c</i><sub>12</sub></span></span>, det <i>J</i> = <i>a</i><sub>1</sub><i>a</i><sub>2</sub> sin <i>θ</i><sub>2</sub>"]],"kt":[["Jacobian matrix","singularity","pseudo-inverse","damped least squares"],["matrice jacobienne","singularité","pseudo-inverse","moindres carrés amortis"]]},{"id":"l9","n":"9","m":25,"t":["Motion generation: the speed laws","La génération de mouvement : les lois de vitesse"],"ess":[["A trajectory says where each joint is at every instant: q(t).","Trapezoid: simple, but the acceleration jumps. Polynomial of degree 5: speed and acceleration start and end at zero.","Degree 5: s(u) = 10u³ − 15u⁴ + 6u⁵ with u = t / T, then q = q₀ + (q₁ − q₀) s(u)."],["Une trajectoire dit où est chaque liaison à chaque instant : q(t).","Trapèze : simple, mais l'accélération saute. Polynôme de degré 5 : vitesse et accélération partent et finissent à zéro.","Degré 5 : s(u) = 10u³ − 15u⁴ + 6u⁵ avec u = t / T, puis q = q₀ + (q₁ − q₀) s(u)."]],"keep":[[],[]],"eq":[["<i>q</i>(<i>t</i>) = <i>q</i><sup>i</sup> + <i>r</i>(<i>t</i>) <i>D</i>, <i>D</i> = <i>q</i><sup>f</sup> − <i>q</i><sup>i</sup>, <i>r</i>(0) = 0, <i>r</i>(<i>t</i><sub>f</sub>) = 1","<i>q˙</i><sub>max</sub> = <span class=\"frac\"><span>2|<i>D</i>|</span><span><i>t</i><sub>f</sub></span></span>, <i>q¨</i><sub>max</sub> = <span class=\"frac\"><span>4|<i>D</i>|</span><span><i>t</i><sub>f</sub>²</span></span>, <i>t</i><sub>f</sub> = max( <span class=\"frac\"><span>2|<i>D</i>|</span><span><i>k</i><sub>v</sub></span></span> , 2 <span class=\"sqrt\">|<i>D</i>| / <i>k</i><sub>a</sub></span> )","<i>r</i>(<i>t</i>) = 10(<i>t</i>/<i>t</i><sub>f</sub>)³ − 15(<i>t</i>/<i>t</i><sub>f</sub>)⁴ + 6(<i>t</i>/<i>t</i><sub>f</sub>)⁵, <i>q˙</i><sub>max</sub> = <span class=\"frac\"><span>15|<i>D</i>|</span><span>8<i>t</i><sub>f</sub></span></span>, <i>q¨</i><sub>max</sub> = <span class=\"frac\"><span>10|<i>D</i>|</span><span>√3 <i>t</i><sub>f</sub>²</span></span>"],["<i>q</i>(<i>t</i>) = <i>q</i><sup>i</sup> + <i>r</i>(<i>t</i>) <i>D</i>, <i>D</i> = <i>q</i><sup>f</sup> − <i>q</i><sup>i</sup>, <i>r</i>(0) = 0, <i>r</i>(<i>t</i><sub>f</sub>) = 1","<i>q˙</i><sub>max</sub> = <span class=\"frac\"><span>2|<i>D</i>|</span><span><i>t</i><sub>f</sub></span></span>, <i>q¨</i><sub>max</sub> = <span class=\"frac\"><span>4|<i>D</i>|</span><span><i>t</i><sub>f</sub>²</span></span>, <i>t</i><sub>f</sub> = max( <span class=\"frac\"><span>2|<i>D</i>|</span><span><i>k</i><sub>v</sub></span></span> , 2 <span class=\"sqrt\">|<i>D</i>| / <i>k</i><sub>a</sub></span> )","<i>r</i>(<i>t</i>) = 10(<i>t</i>/<i>t</i><sub>f</sub>)³ − 15(<i>t</i>/<i>t</i><sub>f</sub>)⁴ + 6(<i>t</i>/<i>t</i><sub>f</sub>)⁵, <i>q˙</i><sub>max</sub> = <span class=\"frac\"><span>15|<i>D</i>|</span><span>8<i>t</i><sub>f</sub></span></span>, <i>q¨</i><sub>max</sub> = <span class=\"frac\"><span>10|<i>D</i>|</span><span>√3 <i>t</i><sub>f</sub>²</span></span>"]],"kt":[["bang-bang","speed trapezoid","jerk","homothetic trapezoids","minimum time"],["bang-bang","trapèze de vitesse","jerk (à-coup)","trapèzes homothétiques","temps minimal"]]},{"id":"l10","n":"10","m":8,"t":["Going further: dynamics and control","Pour aller plus loin : dynamique et commande"],"ess":[["Dynamics links torques and motions: τ = M(q) q̈ + C(q, q̇) q̇ + G(q).","G(q) is the torque needed just to hold the arm against gravity.","Control uses these models: gravity compensation, then a PID on the error."],["La dynamique relie couples et mouvements : τ = M(q) q̈ + C(q, q̇) q̇ + G(q).","G(q) est le couple nécessaire juste pour tenir le bras contre la gravité.","La commande utilise ces modèles : compensation de gravité, puis un PID sur l'erreur."]],"keep":[[],[]],"eq":[["<i>Γ</i> = <i>A</i>(<i>q</i>) <i>q¨</i> + <i>C</i>(<i>q</i>, <i>q˙</i>) <i>q˙</i> + <i>Q</i>(<i>q</i>) + <i>F</i><sub>v</sub><i>q˙</i> + <i>F</i><sub>s</sub> sign(<i>q˙</i>) + <i>J</i><sup>T</sup><i>F</i><sub>e</sub>"],["<i>Γ</i> = <i>A</i>(<i>q</i>) <i>q¨</i> + <i>C</i>(<i>q</i>, <i>q˙</i>) <i>q˙</i> + <i>Q</i>(<i>q</i>) + <i>F</i><sub>v</sub><i>q˙</i> + <i>F</i><sub>s</sub> sign(<i>q˙</i>) + <i>J</i><sup>T</sup><i>F</i><sub>e</sub>"]],"kt":[["inertia matrix","Coriolis","PID","computed torque"],["matrice d'inertie","Coriolis","PID","couple calculé"]]},{"id":"l11","n":"11","m":5,"t":["Revision sheet: the essentials on one page","Fiche de révision : l'essentiel en une page"],"ess":[["Position: rotation matrices, homogeneous transforms, DHm → MGD; inverse → MGI.","Speed: Jacobian; singularities when det J = 0.","Time: motion laws; force: dynamics and control."],["Position : matrices de rotation, transformations homogènes, DHm → MGD ; inverse → MGI.","Vitesse : jacobienne ; singularités quand det J = 0.","Temps : lois de mouvement ; effort : dynamique et commande."]],"keep":[[],[]],"eq":[[],[]],"kt":[[],[]]}],"t":["Robot modelling, full course","Modélisation d'un robot, cours complet"]},{"page":"learn-singularities","title":["Singularities and the Jacobian","Singularités et jacobienne"],"lessons":[{"id":"l1","n":"1","m":12,"t":["From joint speeds to tool speed: the Jacobian","Des vitesses articulaires à la vitesse de l'outil : la jacobienne"],"ess":[["The Jacobian J turns joint speeds into tool speed: Ẋ = J q̇.","Column i of J = tool speed when only joint i moves at 1 rad/s.","J changes with the posture q: the same joint speed gives a different tool speed in another posture."],["La jacobienne J transforme les vitesses articulaires en vitesse de l'outil : Ẋ = J q̇.","Colonne i de J = vitesse de l'outil quand seule la liaison i bouge à 1 rad/s.","J change avec la posture q : la même vitesse articulaire donne une autre vitesse d'outil dans une autre posture."]],"keep":[["<ul><li><strong>Velocity model:</strong> <i>ẋ</i> = <i>J</i>(<i>q</i>) <i>q̇</i>. The tool velocity is a linear combination of the columns of <i>J</i>.</li><li><i>J</i> depends on the pose <i>q</i>: it changes as the robot moves. For small moves, d<i>x</i> ≈ <i>J</i> d<i>q</i>.</li><li><strong>Inverse:</strong> if the tool must move at <i>ẋ</i>, the joints must move at <i>q̇</i> = <i>J</i><sup>−1</sup> <i>ẋ</i>. That is only possible if <i>J</i> can be inverted… and this is where the whole course begins.</li></ul>"],["<ul><li><strong>Modèle cinématique :</strong> <i>ẋ</i> = <i>J</i>(<i>q</i>) <i>q̇</i>. La vitesse de l'outil est une combinaison linéaire des colonnes de <i>J</i>.</li><li><i>J</i> dépend de la pose <i>q</i> : elle change quand le robot bouge. Pour de petits mouvements, d<i>x</i> ≈ <i>J</i> d<i>q</i>.</li><li><strong>Inverse :</strong> si l'outil doit bouger à <i>ẋ</i>, les articulations doivent bouger à <i>q̇</i> = <i>J</i><sup>−1</sup> <i>ẋ</i>. Ce n'est possible que si <i>J</i> est inversible… et c'est là que tout le cours commence.</li></ul>"]],"eq":[["<i>ẋ</i> = −<i>L</i> sin <i>θ</i> · <i>θ̇</i>, <i>ẏ</i> = <i>L</i> cos <i>θ</i> · <i>θ̇</i>","<span class=\"mx c1\"><span><i>ẋ</i></span><span><i>ẏ</i></span></span> = <span class=\"mx c2\"><span>−<i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span><span>−<i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span><span><i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span><span><i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span></span> <span class=\"mx c1\"><span><i>θ̇</i><sub>1</sub></span><span><i>θ̇</i><sub>2</sub></span></span> (<i>θ</i><sub>12</sub> = <i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)","<i>J</i> = <span class=\"mx c2\"><span>−0.3</span><span>−0.3</span><span>0.5</span><span>0</span></span>"],["<i>ẋ</i> = −<i>L</i> sin <i>θ</i> · <i>θ̇</i>, <i>ẏ</i> = <i>L</i> cos <i>θ</i> · <i>θ̇</i>","<span class=\"mx c1\"><span><i>ẋ</i></span><span><i>ẏ</i></span></span> = <span class=\"mx c2\"><span>−<i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span><span>−<i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span><span><i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span><span><i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span></span> <span class=\"mx c1\"><span><i>θ̇</i><sub>1</sub></span><span><i>θ̇</i><sub>2</sub></span></span> (<i>θ</i><sub>12</sub> = <i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)","<i>J</i> = <span class=\"mx c2\"><span>−0,3</span><span>−0,3</span><span>0,5</span><span>0</span></span>"]],"kt":[["Jacobian matrix","joint speed","tool velocity","column of J","linear / angular velocity"],["matrice jacobienne","vitesse articulaire","vitesse de l'outil","colonne de J","vitesse linéaire / angulaire"]]},{"id":"l2","n":"2","m":10,"t":["What is a singularity?","Qu'est-ce qu'une singularité ?"],"ess":[["A singularity is a posture where J loses rank: det J = 0 for a square J.","There, one direction of the tool cannot be reached by any joint speed.","Near it, small tool speeds need huge joint speeds."],["Une singularité est une posture où J perd du rang : det J = 0 pour une J carrée.","Là, une direction de l'outil ne peut être obtenue par aucune vitesse articulaire.","Près d'elle, de petites vitesses d'outil demandent d'énormes vitesses articulaires."]],"keep":[[],[]],"eq":[["<i>J</i> = <span class=\"mx c2\"><span>−(<i>L</i><sub>1</sub>+<i>L</i><sub>2</sub>) sin <i>θ</i><sub>1</sub></span><span>−<i>L</i><sub>2</sub> sin <i>θ</i><sub>1</sub></span><span>(<i>L</i><sub>1</sub>+<i>L</i><sub>2</sub>) cos <i>θ</i><sub>1</sub></span><span><i>L</i><sub>2</sub> cos <i>θ</i><sub>1</sub></span></span>","det <i>J</i> = <i>L</i><sub>1</sub> <i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>"],["<i>J</i> = <span class=\"mx c2\"><span>−(<i>L</i><sub>1</sub>+<i>L</i><sub>2</sub>) sin <i>θ</i><sub>1</sub></span><span>−<i>L</i><sub>2</sub> sin <i>θ</i><sub>1</sub></span><span>(<i>L</i><sub>1</sub>+<i>L</i><sub>2</sub>) cos <i>θ</i><sub>1</sub></span><span><i>L</i><sub>2</sub> cos <i>θ</i><sub>1</sub></span></span>","det <i>J</i> = <i>L</i><sub>1</sub> <i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>"]],"kt":[["singularity","rank","determinant","boundary singularity","internal singularity"],["singularité","rang","déterminant","singularité de frontière","singularité interne"]]},{"id":"l3","n":"3","m":14,"t":["The singularities of a 6-axis robot","Les singularités d'un robot 6 axes"],"ess":[["A 6-axis robot has 3 kinds of singularities: shoulder, elbow and wrist.","Elbow: arm stretched. Wrist: axes 4 and 6 aligned (θ₅ = 0). Shoulder: the wrist centre on the axis of joint 1.","Wrist singularity is the most common in practice (horizontal tool, θ₅ near 0)."],["Un robot 6 axes a 3 sortes de singularités : épaule, coude et poignet.","Coude : bras tendu. Poignet : axes 4 et 6 alignés (θ₅ = 0). Épaule : le centre du poignet sur l'axe de la liaison 1.","La singularité de poignet est la plus fréquente en pratique (outil horizontal, θ₅ proche de 0)."]],"keep":[["<ul><li>A 6-axis robot has <strong>three</strong> families of singular poses: elbow, shoulder, wrist.</li><li>In the joint space they are thin surfaces (for example <i>q</i><sub>5</sub> = 0). But the zone where the robot is <em>badly conditioned</em> around them is thick: you feel the problem well before the exact pose.</li><li>Elbow = edge of the workspace; shoulder and wrist = inside it.</li></ul>"],["<ul><li>Un robot 6 axes a <strong>trois</strong> familles de poses singulières : coude, épaule, poignet.</li><li>Dans l'espace articulaire ce sont des surfaces fines (par exemple <i>q</i><sub>5</sub> = 0). Mais la zone où le robot est <em>mal conditionné</em> autour d'elles est épaisse : on ressent le problème bien avant la pose exacte.</li><li>Coude = bord de l'espace de travail ; épaule et poignet = à l'intérieur.</li></ul>"]],"eq":[["det <i>J</i> = −<i>C</i><sub>3</sub> <i>D</i><sub>3</sub> <i>RL</i><sub>4</sub> <i>S</i><sub>5</sub> (<i>S</i><sub>23</sub> <i>RL</i><sub>4</sub> − <i>C</i><sub>2</sub> <i>D</i><sub>3</sub>)"],["det <i>J</i> = −<i>C</i><sub>3</sub> <i>D</i><sub>3</sub> <i>RL</i><sub>4</sub> <i>S</i><sub>5</sub> (<i>S</i><sub>23</sub> <i>RL</i><sub>4</sub> − <i>C</i><sub>2</sub> <i>D</i><sub>3</sub>)"]],"kt":[["elbow singularity","shoulder singularity","wrist singularity","spherical wrist","wrist centre"],["singularité de coude","singularité d'épaule","singularité de poignet","poignet sphérique","centre du poignet"]]},{"id":"l4","n":"4","m":12,"t":["How close am I? Manipulability and conditioning","À quel point suis-je proche ? Manipulabilité et conditionnement"],"ess":[["Manipulability w = √det(J Jᵀ) (for a square J: |det J|) measures how far we are from a singularity.","The condition number κ = σ max / σ min (ratio of the largest to the smallest singular value): 1 is perfect, very large is dangerous.","Good postures have a large w and a small κ."],["La manipulabilité w = √det(J Jᵀ) (pour J carrée : |det J|) mesure à quelle distance on est d'une singularité.","Le conditionnement κ = σ max / σ min (rapport de la plus grande à la plus petite valeur singulière) : 1 est parfait, très grand est dangereux.","Les bonnes postures ont un grand w et un petit κ."]],"keep":[[],[]],"eq":[[],[]],"kt":[["manipulability","manipulability ellipse","singular value","SVD","condition number","isotropic"],["manipulabilité","ellipse de manipulabilité","valeur singulière","SVD","conditionnement","isotrope"]]},{"id":"l5","n":"5","m":12,"t":["Why singularities hurt: speeds, forces and accuracy","Pourquoi les singularités gênent : vitesses, efforts et précision"],"ess":[["Speed: q̇ = J⁻¹ Ẋ blows up near a singularity.","Force: τ = Jᵀ F. In a singular direction the robot can resist a large force with almost no torque.","Accuracy: small joint errors give large tool errors in the bad directions."],["Vitesse : q̇ = J⁻¹ Ẋ explose près d'une singularité.","Effort : τ = Jᵀ F. Dans une direction singulière, le robot peut résister à une grande force avec presque aucun couple.","Précision : de petites erreurs articulaires donnent de grandes erreurs d'outil dans les mauvaises directions."]],"keep":[["<ul><li>The directions where the tool <strong>cannot move</strong> (lost by <i>J</i>) are the directions where the robot <strong>can carry any load without motor torque</strong> (null space of <i>J</i><sup>T</sup>).</li><li>It looks like a bonus (a strong, light robot), but the motors cannot <em>control</em> the force in that direction: no force control, no way to push gently, and the structure may be overloaded without any motor feeling it.</li></ul>"],["<ul><li>Les directions où l'outil <strong>ne peut pas bouger</strong> (perdues par <i>J</i>) sont les directions où le robot <strong>peut porter n'importe quelle charge sans couple moteur</strong> (noyau de <i>J</i><sup>T</sup>).</li><li>Cela ressemble à un bonus (un robot fort et léger), mais les moteurs ne peuvent pas <em>contrôler</em> l'effort dans cette direction : pas de commande en effort, pas de poussée douce, et la structure peut être surchargée sans qu'aucun moteur ne le sente.</li></ul>"]],"eq":[["<i>J</i><sup>−1</sup> = (1 / (<i>L</i><sub>1</sub><i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>)) <span class=\"mx c2\"><span><i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span><span><i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span><span>−<i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span><span>−<i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span></span>","<i>τ</i> = <i>J</i><sup>T</sup> <i>F</i>","<span class=\"mx c1\"><span><i>τ</i><sub>1</sub></span><span><i>τ</i><sub>2</sub></span></span> = <span class=\"mx c2\"><span>0</span><span>0.8</span><span>0</span><span>0.3</span></span> <span class=\"mx c1\"><span><i>F</i><sub><i>x</i></sub></span><span><i>F</i><sub><i>y</i></sub></span></span> = <span class=\"mx c1\"><span>0.8 <i>F</i><sub><i>y</i></sub></span><span>0.3 <i>F</i><sub><i>y</i></sub></span></span>"],["<i>J</i><sup>−1</sup> = (1 / (<i>L</i><sub>1</sub><i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>)) <span class=\"mx c2\"><span><i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span><span><i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span><span>−<i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> cos <i>θ</i><sub>12</sub></span><span>−<i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> − <i>L</i><sub>2</sub> sin <i>θ</i><sub>12</sub></span></span>","<i>τ</i> = <i>J</i><sup>T</sup> <i>F</i>","<span class=\"mx c1\"><span><i>τ</i><sub>1</sub></span><span><i>τ</i><sub>2</sub></span></span> = <span class=\"mx c2\"><span>0</span><span>0,8</span><span>0</span><span>0,3</span></span> <span class=\"mx c1\"><span><i>F</i><sub><i>x</i></sub></span><span><i>F</i><sub><i>y</i></sub></span></span> = <span class=\"mx c1\"><span>0,8 <i>F</i><sub><i>y</i></sub></span><span>0,3 <i>F</i><sub><i>y</i></sub></span></span>"]],"kt":[["inverse Jacobian","static model","joint torque","duality","speed limit"],["jacobienne inverse","modèle statique","couple articulaire","dualité","limite de vitesse"]]},{"id":"l6","n":"6","m":12,"t":["Orientation singularities: gimbal lock","Singularités d'orientation : le blocage de cardan"],"ess":[["Gimbal lock: with 3 angles, at some values two rotation axes line up and one rotation is lost.","It is a singularity of the angle description, not of the object.","Quaternions (4 numbers) describe every orientation without this problem."],["Blocage de cardan : avec 3 angles, pour certaines valeurs deux axes de rotation s'alignent et une rotation est perdue.","C'est une singularité de la description par angles, pas de l'objet lui-même.","Les quaternions (4 nombres) décrivent toutes les orientations sans ce problème."]],"keep":[["<ul><li>No set of <strong>three</strong> numbers can describe every orientation without a singularity (a mathematical fact about the rotation group). Four numbers (quaternion) or nine (matrix) can.</li><li>Controllers store orientations as quaternions or matrices and only convert to angles (ABC, RPY, WPR…) for the display and for the operator.</li><li>Never interpolate two orientations by interpolating their Euler angles.</li></ul>"],[]],"eq":[["<i>R</i> = <span class=\"mx c3\"><span>0</span><span>sin(<i>γ</i> − <i>α</i>)</span><span>cos(<i>γ</i> − <i>α</i>)</span><span>0</span><span>cos(<i>γ</i> − <i>α</i>)</span><span>−sin(<i>γ</i> − <i>α</i>)</span><span>−1</span><span>0</span><span>0</span></span>","<span class=\"mx c1\"><span><i>ω</i><sub>x</sub></span><span><i>ω</i><sub>y</sub></span><span><i>ω</i><sub>z</sub></span></span> = <span class=\"mx c3\"><span>0</span><span>−sin <i>α</i></span><span>cos <i>α</i> cos <i>β</i></span><span>0</span><span>cos <i>α</i></span><span>sin <i>α</i> cos <i>β</i></span><span>1</span><span>0</span><span>−sin <i>β</i></span></span> <span class=\"mx c1\"><span><i>α̇</i></span><span><i>β̇</i></span><span><i>γ̇</i></span></span> det <i>E</i> = −cos <i>β</i>"],["<i>R</i> = <span class=\"mx c3\"><span>0</span><span>sin(<i>γ</i> − <i>α</i>)</span><span>cos(<i>γ</i> − <i>α</i>)</span><span>0</span><span>cos(<i>γ</i> − <i>α</i>)</span><span>−sin(<i>γ</i> − <i>α</i>)</span><span>−1</span><span>0</span><span>0</span></span>","<span class=\"mx c1\"><span><i>ω</i><sub>x</sub></span><span><i>ω</i><sub>y</sub></span><span><i>ω</i><sub>z</sub></span></span> = <span class=\"mx c3\"><span>0</span><span>−sin <i>α</i></span><span>cos <i>α</i> cos <i>β</i></span><span>0</span><span>cos <i>α</i></span><span>sin <i>α</i> cos <i>β</i></span><span>1</span><span>0</span><span>−sin <i>β</i></span></span> <span class=\"mx c1\"><span><i>α̇</i></span><span><i>β̇</i></span><span><i>γ̇</i></span></span> det <i>E</i> = −cos <i>β</i>"]],"kt":[["gimbal lock","Cardan / Euler angles","quaternion","geometric Jacobian","analytical Jacobian","SLERP"],["blocage de cardan","angles de Cardan / d'Euler","quaternion","jacobienne géométrique","jacobienne analytique","SLERP"]]},{"id":"l7","n":"7","m":12,"t":["Redundancy and the null space","Redondance et espace nul"],"ess":[["A robot is redundant when it has more joints than the task needs (n &gt; m).","The extra motions form the null space: the joints move but the tool stays still (like moving your elbow while your hand holds a cup).","We use them to avoid singularities, joint limits and obstacles."],["Un robot est redondant quand il a plus de liaisons que la tâche n'en demande (n &gt; m).","Les mouvements en trop forment l'espace nul : les liaisons bougent mais l'outil reste immobile (comme bouger le coude en tenant une tasse).","On les utilise pour éviter singularités, butées et obstacles."]],"keep":[["<p>A robot can also be redundant for <em>one task</em> without having extra joints. A welding torch or a drill is symmetric about its own axis, so its rotation about that axis does not matter: the task has only 5 DOF and a 6-axis robot has one free degree. That free degree is precisely how programmers move the tool away from a wrist singularity.</p>"],["<p>Un robot peut aussi être redondant pour <em>une tâche</em> sans avoir d'articulation en plus. Une torche de soudage ou un foret sont symétriques autour de leur axe, donc leur rotation autour de cet axe n'a pas d'importance : la tâche n'a que 5 DDL et un robot 6 axes a un degré libre. Ce degré libre est précisément ce qui permet aux programmeurs d'éloigner l'outil d'une singularité de poignet.</p>"]],"eq":[["<i>J</i> = <span class=\"mx c3\"><span>1</span><span>0</span><span>1</span><span>0</span><span>1</span><span>1</span></span>","<i>q̇</i> = <i>J</i><sup>+</sup> <i>ẋ</i> + (<i>I</i> − <i>J</i><sup>+</sup><i>J</i>) <i>z</i>"],["<i>J</i> = <span class=\"mx c3\"><span>1</span><span>0</span><span>1</span><span>0</span><span>1</span><span>1</span></span>","<i>q̇</i> = <i>J</i><sup>+</sup> <i>ẋ</i> + (<i>I</i> − <i>J</i><sup>+</sup><i>J</i>) <i>z</i>"]],"kt":[["redundant robot","null space","self-motion","pseudo-inverse","secondary task","task redundancy"],["robot redondant","espace nul","auto-mouvement","pseudo-inverse","tâche secondaire","redondance de tâche"]]},{"id":"l8","n":"8","m":14,"t":["Living with singularities: detect, avoid, tame","Vivre avec les singularités : détecter, éviter, apprivoiser"],"ess":[["Detect: watch det J, w or κ; warn or slow down below a threshold.","Avoid: plan paths far from singular postures, or use a redundant robot.","Tame: damped least squares q̇ = Jᵀ (J Jᵀ + λ² I)⁻¹ Ẋ keeps the joint speeds bounded."],["Détecter : surveiller det J, w ou κ ; alerter ou ralentir sous un seuil.","Éviter : planifier les trajets loin des postures singulières, ou utiliser un robot redondant.","Apprivoiser : les moindres carrés amortis q̇ = Jᵀ (J Jᵀ + λ² I)⁻¹ Ẋ gardent les vitesses articulaires bornées."]],"keep":[[],[]],"eq":[["<i>q̇</i> = <i>J</i><sup>T</sup> (<i>J</i> <i>J</i><sup>T</sup> + <i>λ</i><sup>2</sup> <i>I</i>)<sup>−1</sup> <i>ẋ</i>"],["<i>q̇</i> = <i>J</i><sup>T</sup> (<i>J</i> <i>J</i><sup>T</sup> + <i>λ</i><sup>2</sup> <i>I</i>)<sup>−1</sup> <i>ẋ</i>"]],"kt":[["damped least squares","speed scaling","MoveJ / MoveL","direct kinematic singularity","inverse kinematic singularity","singularity-free workspace"],["moindres carrés amortis","réglage de la vitesse","MoveJ / MoveL","singularité cinématique directe","singularité cinématique inverse","espace de travail sans singularités"]]}],"t":["Singularities and the Jacobian","Singularités et jacobienne"]},{"page":"learn-control","title":["Dynamics, actuators and control","Dynamique, actionneurs et commande"],"lessons":[{"id":"l1","n":"1","m":14,"t":["Dynamics: forces, torques and the equation of a robot","Dynamique : forces, couples et équation d'un robot"],"ess":[["Kinematics says where; dynamics says which torque is needed to get there.","One link: τ = I θ̈ + b θ̇ + m g l cos θ (inertia + friction + gravity).","Holding the arm still already needs torque: the gravity term."],["La cinématique dit où ; la dynamique dit quel couple il faut pour y aller.","Un segment : τ = I θ̈ + b θ̇ + m g l cos θ (inertie + frottement + gravité).","Tenir le bras immobile demande déjà du couple : le terme de gravité."]],"keep":[[],[]],"eq":[["<i>τ</i> = <i>I</i> <i>θ̈</i> + <i>b</i> <i>θ̇</i> + <i>m</i> <i>g</i> <i>l</i> cos <i>θ</i>","<i>M</i>(<i>q</i>) <i>q̈</i> + <i>C</i>(<i>q</i>, <i>q̇</i>) <i>q̇</i> + <i>g</i>(<i>q</i>) + <i>f</i>(<i>q̇</i>) = <i>τ</i>","<i>M</i><sub>11</sub> = (<i>m</i><sub>1</sub>+<i>m</i><sub>2</sub>)<i>L</i><sub>1</sub>² + <i>m</i><sub>2</sub><i>L</i><sub>2</sub>² + 2<i>m</i><sub>2</sub><i>L</i><sub>1</sub><i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>, <i>M</i><sub>12</sub> = <i>m</i><sub>2</sub><i>L</i><sub>2</sub>² + <i>m</i><sub>2</sub><i>L</i><sub>1</sub><i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>, <i>M</i><sub>22</sub> = <i>m</i><sub>2</sub><i>L</i><sub>2</sub>²","<i>g</i><sub>1</sub> = (<i>m</i><sub>1</sub>+<i>m</i><sub>2</sub>) <i>g</i> <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>m</i><sub>2</sub> <i>g</i> <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>), <i>g</i><sub>2</sub> = <i>m</i><sub>2</sub> <i>g</i> <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>)"],["<i>τ</i> = <i>I</i> <i>θ̈</i> + <i>b</i> <i>θ̇</i> + <i>m</i> <i>g</i> <i>l</i> cos <i>θ</i>","<i>M</i>(<i>q</i>) <i>q̈</i> + <i>C</i>(<i>q</i>, <i>q̇</i>) <i>q̇</i> + <i>g</i>(<i>q</i>) + <i>f</i>(<i>q̇</i>) = <i>τ</i>","<i>M</i><sub>11</sub> = (<i>m</i><sub>1</sub>+<i>m</i><sub>2</sub>)<i>L</i><sub>1</sub>² + <i>m</i><sub>2</sub><i>L</i><sub>2</sub>² + 2<i>m</i><sub>2</sub><i>L</i><sub>1</sub><i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>, <i>M</i><sub>12</sub> = <i>m</i><sub>2</sub><i>L</i><sub>2</sub>² + <i>m</i><sub>2</sub><i>L</i><sub>1</sub><i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>, <i>M</i><sub>22</sub> = <i>m</i><sub>2</sub><i>L</i><sub>2</sub>²","<i>g</i><sub>1</sub> = (<i>m</i><sub>1</sub>+<i>m</i><sub>2</sub>) <i>g</i> <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub> + <i>m</i><sub>2</sub> <i>g</i> <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>), <i>g</i><sub>2</sub> = <i>m</i><sub>2</sub> <i>g</i> <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub>+<i>θ</i><sub>2</sub>)"]],"kt":[["dynamics","torque","inertia","Lagrange / Newton–Euler","Coriolis","gravity compensation","friction","payload"],["dynamique","couple","inertie","Lagrange / Newton–Euler","Coriolis","compensation de gravité","frottement","charge utile"]]},{"id":"l2","n":"2","m":14,"t":["Actuators: motors, gearboxes and how to size them","Actionneurs : moteurs, réducteurs et dimensionnement"],"ess":[["Robots mostly use brushless servomotors: fast, light, precise, controlled by a drive.","A gearbox of ratio N: speed ÷ N, torque × N × efficiency.","Sizing: the motor must give the peak torque and the RMS torque of the cycle, at the needed speed."],["Les robots utilisent surtout des servomoteurs sans balais : rapides, légers, précis, pilotés par un variateur.","Un réducteur de rapport N : vitesse ÷ N, couple × N × rendement.","Dimensionnement : le moteur doit donner le couple de pointe et le couple efficace du cycle, à la vitesse demandée."]],"keep":[["<ul><li>The torque that matters for heating is the <strong>RMS</strong> torque over the whole cycle, not the peak.</li><li>Torque is proportional to current: <i>τ</i><sub>motor</sub> = <i>K</i><sub>t</sub> · <i>I</i>. The drive controls the current.</li><li>Brakes: a robot arm falling when power is cut is dangerous, so most joints that carry gravity have a spring-applied brake.</li></ul>"],["<ul><li>Le couple qui compte pour l'échauffement est le couple <strong>efficace</strong> sur tout le cycle, pas la pointe.</li><li>Le couple est proportionnel au courant : <i>τ</i><sub>moteur</sub> = <i>K</i><sub>t</sub> · <i>I</i>. Le variateur commande le courant.</li><li>Freins : un bras robot qui tombe quand le courant est coupé est dangereux, donc la plupart des articulations qui portent la gravité ont un frein à manque de courant.</li></ul>"]],"eq":[["<i>τ</i><sub>joint</sub> = <i>N</i> · <i>η</i> · <i>τ</i><sub>motor</sub>, <i>ω</i><sub>joint</sub> = <i>ω</i><sub>motor</sub> / <i>N</i>, <i>J</i><sub>reflected</sub> = <i>N</i>² · <i>J</i><sub>motor</sub>"],["<i>τ</i><sub>joint</sub> = <i>N</i> · <i>η</i> · <i>τ</i><sub>motor</sub>, <i>ω</i><sub>joint</sub> = <i>ω</i><sub>motor</sub> / <i>N</i>, <i>J</i><sub>reflected</sub> = <i>N</i>² · <i>J</i><sub>motor</sub>"]],"kt":[["brushless motor","stepper","gear ratio","harmonic drive","backlash","reflected inertia","RMS torque","brake"],["moteur sans balais","moteur pas à pas","rapport de réduction","réducteur harmonique","jeu","inertie réfléchie","couple efficace","frein"]]},{"id":"l3","n":"3","m":12,"t":["Joint sensors: how the robot knows what it is doing","Capteurs articulaires : comment le robot sait ce qu'il fait"],"ess":[["Encoders measure the angle of each motor: incremental (counts steps) or absolute (knows the angle at power-on).","Resolution of an n-bit encoder: 2ⁿ steps per turn, i.e. 360° / 2ⁿ.","The speed is computed from the change of angle over time; torque sensors measure the effort."],["Les codeurs mesurent l'angle de chaque moteur : incrémentaux (comptent des pas) ou absolus (connaissent l'angle à la mise sous tension).","Résolution d'un codeur n bits : 2ⁿ pas par tour, soit 360° / 2ⁿ.","La vitesse se calcule à partir de la variation d'angle dans le temps ; des capteurs de couple mesurent l'effort."]],"keep":[["<ul><li>Absolute encoders remove the homing step; incremental ones need it.</li><li>Motor-side measurement is precise but does not see the gearbox elasticity; output-side measurement does.</li><li>Current is a free, rough torque sensor; strain gauges are a true torque sensor.</li></ul>"],["<ul><li>Les codeurs absolus évitent la prise d'origine ; les incrémentaux la demandent.</li><li>La mesure côté moteur est précise mais ne voit pas l'élasticité du réducteur ; la mesure côté sortie la voit.</li><li>Le courant est un capteur de couple gratuit et approximatif ; les jauges sont un vrai capteur de couple.</li></ul>"]],"eq":[[],[]],"kt":[["proprioceptive","encoder","homing","resolution","accuracy","repeatability","force / torque sensor","IMU"],["proprioceptif","codeur","prise d'origine","résolution","exactitude","répétabilité","capteur d'effort / couple","centrale inertielle"]]},{"id":"l4","n":"4","m":14,"t":["Feedback and PID control","Rétroaction et commande PID"],"ess":[["A PID computes u = Kp e + Ki ∫e dt + Kd de/dt, with e = target − measure.","P reacts to the error now, I removes the error that remains, D brakes before overshooting.","Too much gain → oscillations; too little → slow. The damping ζ sets the overshoot."],["Un PID calcule u = Kp e + Ki ∫e dt + Kd de/dt, avec e = consigne − mesure.","P réagit à l'erreur actuelle, I supprime l'erreur qui reste, D freine avant de dépasser.","Trop de gain → oscillations ; pas assez → lent. L'amortissement ζ fixe le dépassement."]],"keep":[[],[]],"eq":[["<i>u</i>(<i>t</i>) = <i>K</i><sub>p</sub> <i>e</i>(<i>t</i>) + <i>K</i><sub>i</sub> ∫ <i>e</i>(<i>t</i>) d<i>t</i> + <i>K</i><sub>d</sub> <i>ė</i>(<i>t</i>)"],["<i>u</i>(<i>t</i>) = <i>K</i><sub>p</sub> <i>e</i>(<i>t</i>) + <i>K</i><sub>i</sub> ∫ <i>e</i>(<i>t</i>) d<i>t</i> + <i>K</i><sub>d</sub> <i>ė</i>(<i>t</i>)"]],"kt":[["feedback","error","PID","overshoot","steady-state error","windup","cascaded loops","feedforward"],["rétroaction","erreur","PID","dépassement","erreur statique","emballement de l'intégrale","boucles en cascade","anticipation"]]},{"id":"l5","n":"5","m":12,"t":["Controlling a whole robot: gravity compensation and computed torque","Commander un robot entier : compensation de gravité et couple calculé"],"ess":[["Gravity compensation: add the computed gravity torque G(q) to the PID, so the PID only fights small errors.","Computed torque: τ = M(q) (q̈_d + Kd ė + Kp e) + C q̇ + G: the robot behaves like simple, independent springs.","It needs a good dynamic model of the robot."],["Compensation de gravité : on ajoute le couple de gravité calculé G(q) au PID, qui ne corrige plus que les petites erreurs.","Couple calculé : τ = M(q) (q̈_d + Kd ė + Kp e) + C q̇ + G : le robot se comporte comme des ressorts simples et indépendants.","Il faut un bon modèle dynamique du robot."]],"keep":[[],[]],"eq":[["<i>τ</i> = <i>K</i><sub>p</sub> (<i>q</i><sub>d</sub> − <i>q</i>) − <i>K</i><sub>d</sub> <i>q̇</i> + <i>g</i>(<i>q</i>)","<i>τ</i> = <i>M</i>(<i>q</i>) [ <i>q̈</i><sub>d</sub> + <i>K</i><sub>d</sub> (<i>q̇</i><sub>d</sub> − <i>q̇</i>) + <i>K</i><sub>p</sub> (<i>q</i><sub>d</sub> − <i>q</i>) ] + <i>C</i>(<i>q</i>, <i>q̇</i>) <i>q̇</i> + <i>g</i>(<i>q</i>)","<i>ë</i> + <i>K</i><sub>d</sub> <i>ė</i> + <i>K</i><sub>p</sub> <i>e</i> = 0"],["<i>τ</i> = <i>K</i><sub>p</sub> (<i>q</i><sub>d</sub> − <i>q</i>) − <i>K</i><sub>d</sub> <i>q̇</i> + <i>g</i>(<i>q</i>)","<i>τ</i> = <i>M</i>(<i>q</i>) [ <i>q̈</i><sub>d</sub> + <i>K</i><sub>d</sub> (<i>q̇</i><sub>d</sub> − <i>q̇</i>) + <i>K</i><sub>p</sub> (<i>q</i><sub>d</sub> − <i>q</i>) ] + <i>C</i>(<i>q</i>, <i>q̇</i>) <i>q̇</i> + <i>g</i>(<i>q</i>)","<i>ë</i> + <i>K</i><sub>d</sub> <i>ė</i> + <i>K</i><sub>p</sub> <i>e</i> = 0"]],"kt":[["independent joint control","gravity compensation","computed torque","inverse dynamics","adaptive control","MPC","operational space"],["commande articulation par articulation","compensation de gravité","couple calculé","dynamique inverse","commande adaptative","MPC","espace opérationnel"]]},{"id":"l6","n":"6","m":12,"t":["Touching the world: force, compliance and impedance control","Toucher le monde : commande en effort, compliance et impédance"],"ess":[["Position control is stiff: in contact it pushes as hard as it can.","Impedance control makes the robot act like a spring + damper: F = K (x_d − x) − B ẋ.","A force sensor at the wrist allows polishing, assembly, hand guiding."],["La commande en position est raide : au contact, elle pousse aussi fort qu'elle peut.","La commande en impédance fait agir le robot comme un ressort + amortisseur : F = K (x_d − x) − B ẋ.","Un capteur d'effort au poignet permet polissage, assemblage, guidage à la main."]],"keep":[["<p>The Cartesian stiffness of a robot with joint stiffness <i>K</i><sub>q</sub> is <i>K</i><sub>x</sub> = <i>J</i><sup>−T</sup> <i>K</i><sub>q</sub> <i>J</i><sup>−1</sup>. In a direction where the Jacobian is small (almost singular), the robot is <em>very stiff</em> and cannot be made soft by control: the structure carries the force (lesson 5 of the previous course). Compliant tasks are placed in well-conditioned poses.</p>"],["<p>La raideur cartésienne d'un robot de raideur articulaire <i>K</i><sub>q</sub> est <i>K</i><sub>x</sub> = <i>J</i><sup>−T</sup> <i>K</i><sub>q</sub> <i>J</i><sup>−1</sup>. Dans une direction où la jacobienne est petite (presque singulière), le robot est <em>très raide</em> et ne peut pas être rendu souple par la commande : la structure porte l'effort (leçon 5 du cours précédent). Les tâches avec compliance sont placées dans des poses bien conditionnées.</p>"]],"eq":[["<i>M</i><sub>d</sub> <i>ë</i> + <i>D</i><sub>d</sub> <i>ė</i> + <i>K</i><sub>d</sub> <i>e</i> = <i>F</i><sub>ext</sub>, <i>e</i> = <i>x</i> − <i>x</i><sub>d</sub>"],["<i>M</i><sub>d</sub> <i>ë</i> + <i>D</i><sub>d</sub> <i>ė</i> + <i>K</i><sub>d</sub> <i>e</i> = <i>F</i><sub>ext</sub>, <i>e</i> = <i>x</i> − <i>x</i><sub>d</sub>"]],"kt":[["compliance","stiffness","impedance control","admittance control","hybrid position/force control","hand guiding","RCC"],["compliance","raideur","commande en impédance","commande en admittance","commande hybride position/effort","guidage manuel","RCC"]]},{"id":"l7","n":"7","m":13,"t":["Trajectories in practice: PTP, linear, circular, splines","Trajectoires en pratique : PTP, linéaire, circulaire, splines"],"ess":[["PTP (point to point): each joint moves on its own; fast, but the tool path is a curve.","LIN and CIRC: the tool follows a straight line or an arc (IK at every point).","Splines join many points smoothly; blending rounds the corners to avoid stopping."],["PTP (point à point) : chaque liaison bouge à sa façon ; rapide, mais le trajet de l'outil est une courbe.","LIN et CIRC : l'outil suit une ligne droite ou un arc (MGI à chaque point).","Les splines relient beaucoup de points en douceur ; l'arrondi (blending) adoucit les coins pour ne pas s'arrêter."]],"keep":[[],[]],"eq":[[],[]],"kt":[["PTP","linear / circular move","blending","spline","quintic","S-curve","jerk","time-optimal"],["PTP","mouvement linéaire / circulaire","arrondi","spline","quintique","courbe en S","à-coup","temps minimal"]]},{"id":"l8","n":"8","m":10,"t":["The control stack: from the program to the motor current","La chaîne de commande : du programme au courant moteur"],"ess":[["Layers: program → trajectory planner → position loop → speed loop → current loop → motor.","Each inner loop is faster than the one around it (typ. current 16–32 kHz, speed 4–8 kHz, position 1–2 kHz).","A fieldbus (EtherCAT) sends the orders to all drives every millisecond."],["Couches : programme → planificateur de trajectoire → boucle de position → boucle de vitesse → boucle de courant → moteur.","Chaque boucle intérieure est plus rapide que celle qui l'entoure (typ. courant 16–32 kHz, vitesse 4–8 kHz, position 1–2 kHz).","Un bus de terrain (EtherCAT) envoie les consignes à tous les variateurs chaque milliseconde."]],"keep":[["<p><strong>Hard real time</strong> means that a late result is a wrong result: if the position loop is delayed by a few milliseconds the robot can vibrate or leave its path. That is why the controller uses a real-time operating system (RTOS, or Linux with PREEMPT_RT) and why a normal desktop computer is not enough to close fast loops.</p>"],["<p>Le <strong>temps réel dur</strong> signifie qu'un résultat en retard est un résultat faux : si la boucle de position est retardée de quelques millisecondes, le robot peut vibrer ou quitter son chemin. C'est pourquoi le contrôleur utilise un système d'exploitation temps réel (RTOS, ou Linux avec PREEMPT_RT) et pourquoi un ordinateur de bureau ordinaire ne suffit pas pour fermer des boucles rapides.</p>"]],"eq":[[],[]],"kt":[["interpolator","servo drive","FOC","fieldbus","EtherCAT","hard real time","safe torque off"],["interpolateur","variateur d'axe","FOC","bus de terrain","EtherCAT","temps réel dur","arrêt de couple sûr"]]},{"id":"l9","n":"9","m":12,"t":["The imperfect robot: friction, backlash, flexibility, vibration","Le robot imparfait : frottement, jeu, flexibilité, vibrations"],"ess":[["Friction (static and viscous) creates a small dead zone and wastes energy.","Backlash: a small play in the gears; flexibility: the links and gearboxes bend.","These effects make the robot less precise and can create vibrations; we model them or filter them."],["Le frottement (sec et visqueux) crée une petite zone morte et gaspille de l'énergie.","Jeu : un petit espace dans les engrenages ; flexibilité : les segments et réducteurs fléchissent.","Ces effets rendent le robot moins précis et peuvent créer des vibrations ; on les modélise ou on les filtre."]],"keep":[["<p>If you know the vibration frequency <i>f</i>, send each command as <strong>two half-size commands separated by half a period</strong> (1/(2<i>f</i>)). The vibrations created by the two halves cancel each other. This “zero-vibration shaper” is used on cranes, 3D printers and long robot arms, and costs only a delay of half a period.</p>"],["<p>Si l'on connaît la fréquence de vibration <i>f</i>, envoyer chaque commande en <strong>deux demi-commandes séparées d'une demi-période</strong> (1/(2<i>f</i>)). Les vibrations créées par les deux moitiés s'annulent. Ce « filtre sans vibration » est utilisé sur les grues, les imprimantes 3D et les longs bras robots, et ne coûte qu'un retard d'une demi-période.</p>"]],"eq":[["<i>f</i> = (1 / 2π) √( <i>k</i> (1/<i>J</i><sub>m</sub> + 1/<i>J</i><sub>l</sub>) )"],["<i>f</i> = (1 / 2π) √( <i>k</i> (1/<i>J</i><sub>m</sub> + 1/<i>J</i><sub>l</sub>) )"]],"kt":[["stick-slip","backlash","flexibility","resonance","notch filter","input shaping","identification","duty cycle"],["stick-slip","jeu","flexibilité","résonance","filtre coupe-bande","filtrage d'entrée","identification","rapport cyclique"]]},{"id":"l10","n":"10","m":22,"t":["Deriving the dynamic model step by step: the Lagrange method","Calculer le modèle dynamique pas à pas : la méthode de Lagrange"],"ess":[["Lagrange: write the kinetic energy T and the potential energy V, form ℒ = T − V, then τᵢ = d/dt(∂ℒ/∂q̇ᵢ) − ∂ℒ/∂qᵢ.","The terms sort into inertia M(q) q̈, Coriolis C(q, q̇) q̇ and gravity g(q); M is symmetric.","Inverse dynamics gives the torques for a motion; forward dynamics q̈ = M⁻¹(τ − C q̇ − g) simulates the robot."],["Lagrange : écrire l'énergie cinétique T et l'énergie potentielle V, former ℒ = T − V, puis τᵢ = d/dt(∂ℒ/∂q̇ᵢ) − ∂ℒ/∂qᵢ.","Les termes se rangent en inertie M(q) q̈, Coriolis C(q, q̇) q̇ et gravité g(q) ; M est symétrique.","La dynamique inverse donne les couples pour un mouvement ; la dynamique directe q̈ = M⁻¹(τ − C q̇ − g) simule le robot."]],"keep":[["<ul><li><strong>M is symmetric</strong>: the term in front of <i>θ̈</i><sub>2</sub> on joint 1 equals the term in front of <i>θ̈</i><sub>1</sub> on joint 2 (both <i>M</i><sub>12</sub>). Always true.</li><li><strong>M depends only on θ₂</strong>: turning the whole arm around the base does not change its shape, so it does not change its inertia.</li><li><strong>Units</strong>: every term must be in N·m (kg·m²·rad/s² or kg·m/s²·m).</li></ul>"],["<ul><li><strong>M est symétrique</strong> : le terme devant <i>θ̈</i><sub>2</sub> sur la liaison 1 est égal au terme devant <i>θ̈</i><sub>1</sub> sur la liaison 2 (les deux valent <i>M</i><sub>12</sub>). Toujours vrai.</li><li><strong>M ne dépend que de θ₂</strong> : faire tourner tout le bras autour de la base ne change pas sa forme, donc pas son inertie.</li><li><strong>Unités</strong> : chaque terme doit être en N·m (kg·m²·rad/s² ou kg·m/s²·m).</li></ul>"]],"eq":[["<i>τ</i><sub>i</sub> = d/d<i>t</i> ( ∂<i>ℒ</i> / ∂<i>q̇</i><sub>i</sub> ) − ∂<i>ℒ</i> / ∂<i>q</i><sub>i</sub>","<i>τ</i> = <i>m</i> <i>l</i>² <i>θ̈</i> + <i>m</i> <i>g</i> <i>l</i> cos <i>θ</i>","<i>x</i><sub>1</sub> = <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub>, <i>y</i><sub>1</sub> = <i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> <i>x</i><sub>2</sub> = <i>x</i><sub>1</sub> + <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>), <i>y</i><sub>2</sub> = <i>y</i><sub>1</sub> + <i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)","<i>v</i><sub>2</sub>² = <i>L</i><sub>1</sub>² <i>θ̇</i><sub>1</sub>² + <i>L</i><sub>2</sub>² (<i>θ̇</i><sub>1</sub> + <i>θ̇</i><sub>2</sub>)² + 2 <i>L</i><sub>1</sub> <i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub> · <i>θ̇</i><sub>1</sub> (<i>θ̇</i><sub>1</sub> + <i>θ̇</i><sub>2</sub>)"],["<i>τ</i><sub>i</sub> = d/d<i>t</i> ( ∂<i>ℒ</i> / ∂<i>q̇</i><sub>i</sub> ) − ∂<i>ℒ</i> / ∂<i>q</i><sub>i</sub>","<i>τ</i> = <i>m</i> <i>l</i>² <i>θ̈</i> + <i>m</i> <i>g</i> <i>l</i> cos <i>θ</i>","<i>x</i><sub>1</sub> = <i>L</i><sub>1</sub> cos <i>θ</i><sub>1</sub>, <i>y</i><sub>1</sub> = <i>L</i><sub>1</sub> sin <i>θ</i><sub>1</sub> <i>x</i><sub>2</sub> = <i>x</i><sub>1</sub> + <i>L</i><sub>2</sub> cos(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>), <i>y</i><sub>2</sub> = <i>y</i><sub>1</sub> + <i>L</i><sub>2</sub> sin(<i>θ</i><sub>1</sub> + <i>θ</i><sub>2</sub>)","<i>v</i><sub>2</sub>² = <i>L</i><sub>1</sub>² <i>θ̇</i><sub>1</sub>² + <i>L</i><sub>2</sub>² (<i>θ̇</i><sub>1</sub> + <i>θ̇</i><sub>2</sub>)² + 2 <i>L</i><sub>1</sub> <i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub> · <i>θ̇</i><sub>1</sub> (<i>θ̇</i><sub>1</sub> + <i>θ̇</i><sub>2</sub>)"]],"kt":[["Lagrangian","kinetic energy","potential energy","inverse dynamics","forward dynamics","inertia matrix","Newton–Euler"],["lagrangien","énergie cinétique","énergie potentielle","dynamique inverse","dynamique directe","matrice d'inertie","Newton–Euler"]]},{"id":"l11","n":"11","m":20,"t":["Control theory 1: transfer functions, poles and stability","Automatique 1 : fonctions de transfert, pôles et stabilité"],"ess":[["A first-order system K/(τs + 1): 63 % of a step after τ, 95 % after 3τ.","Stable if and only if all the poles have a negative real part.","Closed loop F = CG / (1 + CG). A P controller on a first order: τ ÷ (1 + K Kp), final error 1/(1 + K Kp)."],["Un système du premier ordre K/(τs + 1) : 63 % d'un échelon après τ, 95 % après 3τ.","Stable si et seulement si tous les pôles ont une partie réelle négative.","Boucle fermée F = CG / (1 + CG). Un correcteur P sur un premier ordre : τ ÷ (1 + K Kp), erreur finale 1/(1 + K Kp)."]],"keep":[["<p>A system is <strong>stable</strong> if and only if <strong>all its poles have a negative real part</strong> (they are in the left half of the complex plane). The further left, the faster the response; the further from the real axis, the more it oscillates.</p>"],["<p>Un système est <strong>stable</strong> si et seulement si <strong>tous ses pôles ont une partie réelle négative</strong> (ils sont dans la moitié gauche du plan complexe). Plus ils sont à gauche, plus la réponse est rapide ; plus ils sont loin de l'axe réel, plus elle oscille.</p>"]],"eq":[["<i>τ</i> <i>ẏ</i> + <i>y</i> = <i>K</i> <i>u</i>","<i>G</i>(<i>s</i>) = <i>Y</i> / <i>U</i> = <i>K</i> / (<i>τ</i> <i>s</i> + 1) (first order)","<i>G</i>(<i>s</i>) = <i>ω</i><sub>n</sub>² / (<i>s</i>² + 2<i>ζ</i><i>ω</i><sub>n</sub> <i>s</i> + <i>ω</i><sub>n</sub>²) (second order)","<i>F</i>(<i>s</i>) = <i>C</i> <i>G</i> / (1 + <i>C</i> <i>G</i>)"],["<i>τ</i> <i>ẏ</i> + <i>y</i> = <i>K</i> <i>u</i>","<i>G</i>(<i>s</i>) = <i>Y</i> / <i>U</i> = <i>K</i> / (<i>τ</i> <i>s</i> + 1) (premier ordre)","<i>G</i>(<i>s</i>) = <i>ω</i><sub>n</sub>² / (<i>s</i>² + 2<i>ζ</i><i>ω</i><sub>n</sub> <i>s</i> + <i>ω</i><sub>n</sub>²) (second ordre)","<i>F</i>(<i>s</i>) = <i>C</i> <i>G</i> / (1 + <i>C</i> <i>G</i>)"]],"kt":[["first-order system","time constant","transfer function","pole","stability","closed loop","state space"],["système du premier ordre","constante de temps","fonction de transfert","pôle","stabilité","boucle fermée","représentation d'état"]]},{"id":"l12","n":"12","m":20,"t":["Control theory 2: frequency response, margins and digital control","Automatique 2 : réponse en fréquence, marges et commande numérique"],"ess":[["Bode: the gain (in dB) and the lag of the output for each frequency. −3 dB = × 0.707; −20 dB = ÷ 10.","Keep a phase margin of 45° to 60°; a delay T costs ω T radians of margin.","Sample 10 to 30 times faster than the bandwidth; a real PID derives the measurement, filters D and has anti-windup."],["Bode : le gain (en dB) et le retard de la sortie pour chaque fréquence. −3 dB = × 0,707 ; −20 dB = ÷ 10.","Gardez une marge de phase de 45° à 60° ; un retard T coûte ω T radians de marge.","Échantillonnez 10 à 30 fois plus vite que la bande passante ; un vrai PID dérive la mesure, filtre D et a un anti-emballement."]],"keep":[["<ol><li>Model the system (step test, or the dynamic model of lesson 10).</li><li>Choose the wanted behaviour: bandwidth, damping, final error.</li><li>Compute the gains (poles placement, or margins on the Bode diagram).</li><li>Simulate with the delay and the saturation, then try on the real system with low gains first.</li></ol>"],["<ol><li>Modéliser le système (essai indiciel, ou le modèle dynamique de la leçon 10).</li><li>Choisir le comportement voulu : bande passante, amortissement, erreur finale.</li><li>Calculer les gains (placement des pôles, ou marges sur le diagramme de Bode).</li><li>Simuler avec le retard et la saturation, puis essayer sur le vrai système avec des gains faibles d'abord.</li></ol>"]],"eq":[["gain in dB = 20 log<sub>10</sub>( |<i>G</i>(j<i>ω</i>)| )"],["gain en dB = 20 log<sub>10</sub>( |<i>G</i>(j<i>ω</i>)| )"]],"kt":[["frequency response","Bode diagram","bandwidth","phase margin","gain margin","delay","sampling","aliasing","anti-windup"],["réponse en fréquence","diagramme de Bode","bande passante","marge de phase","marge de gain","retard","échantillonnage","repliement","anti-emballement (anti-windup)"]]}],"t":["Dynamics, actuators and control","Dynamique, actionneurs et commande"]},{"page":"learn-intelligence","title":["Perception, planning and AI","Perception, planification et IA"],"lessons":[{"id":"l1","n":"1","m":12,"t":["Sensing the world: the sensors of a robot","Percevoir le monde : les capteurs d'un robot"],"ess":[["Proprioceptive sensors measure the robot itself (encoders, IMU); exteroceptive ones measure the world (camera, lidar, ultrasound).","Time of flight: distance = speed × time / 2 (the signal goes and comes back).","Every sensor has noise, a range and a rate: choose by the need."],["Les capteurs proprioceptifs mesurent le robot lui-même (codeurs, centrale inertielle) ; les extéroceptifs mesurent le monde (caméra, lidar, ultrasons).","Temps de vol : distance = vitesse × temps / 2 (le signal fait l'aller-retour).","Chaque capteur a du bruit, une portée et une fréquence : on choisit selon le besoin."]],"keep":[["<ul><li>No sensor is perfect: <strong>combine</strong> sensors with different weaknesses (sensor fusion, lesson 3).</li><li>Always know the <strong>rate</strong> (Hz), the <strong>latency</strong>, the <strong>range</strong>, the <strong>field of view</strong> and the <strong>noise</strong>.</li><li>Sensors must be <strong>calibrated</strong> (lesson 2) and <strong>time-synchronised</strong>.</li></ul>"],["<ul><li>Aucun capteur n'est parfait : <strong>combinez</strong> des capteurs avec des faiblesses différentes (fusion de capteurs, leçon 3).</li><li>Connaissez toujours la <strong>cadence</strong> (Hz), la <strong>latence</strong>, la <strong>portée</strong>, le <strong>champ de vision</strong> et le <strong>bruit</strong>.</li><li>Les capteurs doivent être <strong>étalonnés</strong> (leçon 2) et <strong>synchronisés dans le temps</strong>.</li></ul>"]],"eq":[["Δ<i>Z</i> ≈ <i>Z</i>² Δ<i>d</i> / (<i>f</i> <i>B</i>)"],["Δ<i>Z</i> ≈ <i>Z</i>² Δ<i>d</i> / (<i>f</i> <i>B</i>)"]],"kt":[["lidar","stereo","RGB-D","baseline","disparity","field of view","sensor fusion","GNSS"],["lidar","stéréo","RVB-D","base","disparité","champ de vision","fusion de capteurs","GNSS"]]},{"id":"l2","n":"2","m":14,"t":["Vision for robots: cameras, calibration, detection, visual servoing","La vision pour les robots : caméras, étalonnage, détection, asservissement visuel"],"ess":[["A camera follows the pinhole model: u = f X / Z (pixels).","Calibration finds f, the image centre and the distortion, plus where the camera is relative to the robot.","With two cameras (stereo): depth Z = f B / d. Visual servoing moves the robot to make the image error zero."],["Une caméra suit le modèle sténopé : u = f X / Z (pixels).","L'étalonnage trouve f, le centre de l'image et la distorsion, plus la position de la caméra par rapport au robot.","Avec deux caméras (stéréo) : profondeur Z = f B / d. L'asservissement visuel bouge le robot pour annuler l'erreur dans l'image."]],"keep":[["<ul><li>A camera measures <em>directions</em> well; depth needs a second view or a depth sensor.</li><li>Calibrate (intrinsics + hand-eye) before blaming the algorithm.</li><li>Deep learning finds <em>what</em> and <em>where roughly</em>; geometry (ICP, PnP) gives the precise pose; servoing closes the last centimetres.</li></ul>"],["<ul><li>Une caméra mesure bien les <em>directions</em> ; la profondeur demande une deuxième vue ou un capteur de profondeur.</li><li>Étalonnez (intrinsèques + œil-main) avant d'accuser l'algorithme.</li><li>L'apprentissage profond trouve <em>quoi</em> et <em>où approximativement</em> ; la géométrie (ICP, PnP) donne la pose précise ; l'asservissement termine les derniers centimètres.</li></ul>"]],"eq":[["<i>u</i> = <i>f</i><sub>x</sub> <i>X</i> / <i>Z</i> + <i>c</i><sub>x</sub>, <i>v</i> = <i>f</i><sub>y</sub> <i>Y</i> / <i>Z</i> + <i>c</i><sub>y</sub>","<i>v</i><sub>c</sub> = −<i>λ</i> <i>L</i><sup>+</sup> <i>e</i>"],["<i>u</i> = <i>f</i><sub>x</sub> <i>X</i> / <i>Z</i> + <i>c</i><sub>x</sub>, <i>v</i> = <i>f</i><sub>y</sub> <i>Y</i> / <i>Z</i> + <i>c</i><sub>y</sub>","<i>v</i><sub>c</sub> = −<i>λ</i> <i>L</i><sup>+</sup> <i>e</i>"]],"kt":[["pinhole model","intrinsic parameters","hand-eye calibration","ArUco / AprilTag","ICP","object detection","visual servoing"],["modèle sténopé","paramètres intrinsèques","étalonnage œil-main","ArUco / AprilTag","ICP","détection d'objets","asservissement visuel"]]},{"id":"l3","n":"3","m":13,"t":["Estimation: filtering noise with Kalman and friends","Estimation : filtrer le bruit avec Kalman et les autres"],"ess":[["Each measure is uncertain; the Kalman filter mixes prediction and measure, giving more weight to the more precise one.","Fusion of two estimates: x = (x₁/σ₁² + x₂/σ₂²) / (1/σ₁² + 1/σ₂²).","The fused uncertainty is always smaller than each one: 1/σ² = 1/σ₁² + 1/σ₂²."],["Chaque mesure est incertaine ; le filtre de Kalman mélange prédiction et mesure, en donnant plus de poids à la plus précise.","Fusion de deux estimations : x = (x₁/σ₁² + x₂/σ₂²) / (1/σ₁² + 1/σ₂²).","L'incertitude fusionnée est toujours plus petite que chacune : 1/σ² = 1/σ₁² + 1/σ₂²."]],"keep":[["<ul><li>Dead reckoning (odometry, gyro integration) <strong>always drifts</strong>; only an external measurement bounds the error.</li><li>The variances <i>Q</i> and <i>R</i> are the tuning knobs: they say how much to trust the model or the sensor.</li><li>Sensor fusion = a filter fed by several sensors, for example wheel odometry + IMU + GNSS.</li></ul>"],["<ul><li>L'estime (odométrie, intégration du gyroscope) <strong>dérive toujours</strong> ; seule une mesure externe borne l'erreur.</li><li>Les variances <i>Q</i> et <i>R</i> sont les boutons de réglage : elles disent combien faire confiance au modèle ou au capteur.</li><li>Fusion de capteurs = un filtre alimenté par plusieurs capteurs, par exemple odométrie des roues + centrale inertielle + GNSS.</li></ul>"]],"eq":[[],[]],"kt":[["prediction / update","variance","Kalman gain","EKF","particle filter","complementary filter","dead reckoning"],["prédiction / correction","variance","gain de Kalman","EKF","filtre à particules","filtre complémentaire","estime"]]},{"id":"l4","n":"4","m":13,"t":["Localisation and mapping: odometry and SLAM","Localisation et cartographie : odométrie et SLAM"],"ess":[["Odometry counts wheel turns: simple but the error grows with the distance travelled (drift).","Localisation corrects the drift with landmarks seen on a known map.","SLAM builds the map and localises at the same time; a loop closure removes the accumulated error."],["L'odométrie compte les tours de roue : simple mais l'erreur grandit avec la distance parcourue (dérive).","La localisation corrige la dérive avec des repères vus sur une carte connue.","Le SLAM construit la carte et se localise en même temps ; une fermeture de boucle supprime l'erreur accumulée."]],"keep":[["<p>Once a map exists, the robot only needs to <strong>localise</strong>: Monte-Carlo localisation (AMCL, a particle filter) compares each scan with the map. If the robot is “kidnapped” (moved without knowing), the particles spread and re-converge: global localisation. Industrial AMRs often combine a lidar map with floor markers or reflectors for centimetre repeatability.</p>"],["<p>Une fois la carte disponible, le robot n'a plus qu'à se <strong>localiser</strong> : la localisation de Monte-Carlo (AMCL, un filtre à particules) compare chaque scan avec la carte. Si le robot est « kidnappé » (déplacé sans le savoir), les particules s'étalent et reconvergent : localisation globale. Les AMR industriels combinent souvent une carte lidar avec des repères au sol ou des réflecteurs pour une répétabilité centimétrique.</p>"]],"eq":[[],[]],"kt":[["odometry","occupancy grid","SLAM","scan matching","loop closure","pose graph","AMCL","kidnapped robot"],["odométrie","grille d'occupation","SLAM","recalage de scan","fermeture de boucle","graphe de poses","AMCL","robot kidnappé"]]},{"id":"l5","n":"5","m":13,"t":["Path planning: Dijkstra, A* and following the path","Planification de chemin : Dijkstra, A* et suivi du chemin"],"ess":[["The map is cut into cells (grid) or nodes (graph); planning = finding the cheapest path.","Dijkstra explores in all directions; A* adds a guess h (distance to the goal) and explores f = g + h first.","If h never overestimates, A* finds the shortest path, much faster."],["La carte est découpée en cases (grille) ou en nœuds (graphe) ; planifier = trouver le chemin le moins cher.","Dijkstra explore dans toutes les directions ; A* ajoute une estimation h (distance au but) et explore d'abord f = g + h.","Si h ne surestime jamais, A* trouve le plus court chemin, bien plus vite."]],"keep":[[],[]],"eq":[[],[]],"kt":[["graph search","Dijkstra","A*","heuristic","admissible","costmap","pure pursuit","DWA"],["recherche dans un graphe","Dijkstra","A*","heuristique","admissible","carte de coûts","poursuite pure","DWA"]]},{"id":"l6","n":"6","m":14,"t":["Motion planning for arms: configuration space, RRT, optimisation","Planification de mouvement pour bras : espace des configurations, RRT, optimisation"],"ess":[["An arm plans in the configuration space (C-space): one axis per joint; obstacles become forbidden zones.","With 6 joints a grid is far too big: we use random sampling (RRT, PRM).","RRT grows a tree of random collision-free steps until it reaches the goal, then smooths the path."],["Un bras planifie dans l'espace des configurations (C-space) : un axe par articulation ; les obstacles deviennent des zones interdites.","Avec 6 articulations, une grille est bien trop grande : on utilise l'échantillonnage aléatoire (RRT, PRM).","RRT fait pousser un arbre de petits pas aléatoires sans collision jusqu'au but, puis lisse le chemin."]],"keep":[[],[]],"eq":[[],[]],"kt":[["configuration space","collision checking","PRM","RRT","probabilistically complete","narrow passage","trajectory optimisation","potential field"],["espace des configurations","test de collision","PRM","RRT","probabilistiquement complet","passage étroit","optimisation de trajectoire","champ de potentiel"]]},{"id":"l7","n":"7","m":12,"t":["Behaviours and task planning: state machines and behaviour trees","Comportements et planification de tâches : automates et arbres de comportement"],"ess":[["A state machine: a few states (wait, pick, place, error) and transitions triggered by events.","A behaviour tree: Sequence (→) does its children in order and fails if one fails; Fallback (?) tries them until one succeeds.","Behaviour trees are easier to extend and reuse in big robots."],["Une machine à états : quelques états (attendre, prendre, poser, erreur) et des transitions déclenchées par des événements.","Un arbre de comportement : Séquence (→) fait ses enfants dans l'ordre et échoue si l'un échoue ; Repli (?) les essaie jusqu'à ce que l'un réussisse.","Les arbres de comportement sont plus faciles à étendre et réutiliser sur les gros robots."]],"keep":[[],[]],"eq":[[],[]],"kt":[["skill","state machine","behaviour tree","sequence / fallback","decorator","PDDL","TAMP","teleoperation"],["compétence","automate à états","arbre de comportement","séquence / repli","décorateur","PDDL","TAMP","téléopération"]]},{"id":"l8","n":"8","m":14,"t":["Learning in robotics: from supervised learning to foundation models","L'apprentissage en robotique : de l'apprentissage supervisé aux modèles de fondation"],"ess":[["Supervised learning: learn from labelled examples (images → \"screw\", \"nut\").","Always test on data the model has never seen (test set).","Reinforcement learning: the robot tries, gets rewards, and maximises the sum of future rewards."],["Apprentissage supervisé : apprendre à partir d'exemples étiquetés (images → « vis », « écrou »).","Toujours tester sur des données que le modèle n'a jamais vues (jeu de test).","Apprentissage par renforcement : le robot essaie, reçoit des récompenses, et maximise la somme des récompenses futures."]],"keep":[[],[]],"eq":[["<i>G</i> = <i>r</i><sub>0</sub> + <i>γ</i> <i>r</i><sub>1</sub> + <i>γ</i>² <i>r</i><sub>2</sub> + …"],["<i>G</i> = <i>r</i><sub>0</sub> + <i>γ</i> <i>r</i><sub>1</sub> + <i>γ</i>² <i>r</i><sub>2</sub> + …"]],"kt":[["supervised learning","reinforcement learning","policy","reward","sim-to-real","domain randomisation","behaviour cloning","VLA"],["apprentissage supervisé","apprentissage par renforcement","politique","récompense","simulation vers réel","randomisation de domaine","clonage de comportement","VLA"]]},{"id":"l9","n":"9","m":11,"t":["Many robots: fleets, swarms and teams with humans","Plusieurs robots : flottes, essaims et équipes avec des humains"],"ess":[["A fleet manager gives missions to many robots, avoids traffic jams and sends them to charge.","Swarms: many simple robots with local rules create a group behaviour.","With humans: share the space safely, show intentions clearly, let people take over."],["Un gestionnaire de flotte donne des missions à de nombreux robots, évite les bouchons et les envoie se recharger.","Essaims : beaucoup de robots simples avec des règles locales créent un comportement de groupe.","Avec les humains : partager l'espace en sécurité, montrer clairement ses intentions, laisser l'humain reprendre la main."]],"keep":[[],[]],"eq":[[],[]],"kt":[["fleet manager","task allocation","MAPF","deadlock","swarm","consensus","HRI","social navigation"],["gestionnaire de flotte","attribution des tâches","MAPF","blocage mutuel","essaim","consensus","HRI","navigation sociale"]]}],"t":["Perception, planning and AI","Perception, planification et IA"]},{"page":"learn-world","title":["Robots in the real world","Les robots dans le monde réel"],"lessons":[{"id":"l1","n":"1","m":14,"t":["The zoo of robots: every family and what makes it special","Le zoo des robots : chaque famille et ce qui la rend spéciale"],"ess":[["Arms (6 axes), SCARA (fast in a plane), delta (very fast picking), cobots (work next to people).","Mobile robots: AGV/AMR on wheels, legged robots, drones, underwater robots, humanoids.","Count the degrees of freedom (DOF) to know what a robot can do."],["Bras (6 axes), SCARA (rapide dans un plan), delta (prise très rapide), cobots (travaillent à côté des humains).","Robots mobiles : AGV/AMR à roues, robots à pattes, drones, robots sous-marins, humanoïdes.","Comptez les degrés de liberté (ddl) pour savoir ce qu'un robot peut faire."]],"keep":[[],[]],"eq":[[],[]],"kt":[["serial / parallel robot","legged robot","humanoid","underactuated","support polygon","ZMP","ROV / AUV","soft robot"],["robot série / parallèle","robot à pattes","humanoïde","sous-actionné","polygone de sustentation","ZMP","ROV / AUV","robot souple"]]},{"id":"l2","n":"2","m":13,"t":["Mechanical design: stiffness, payload, reach, materials","Conception mécanique : rigidité, charge, portée, matériaux"],"ess":[["A good arm is light far from the base and stiff everywhere: motors near the base, hollow links.","Torque at the shoulder grows with the reach: τ = m g d.","Materials: aluminium (light), steel (stiff, cheap), carbon (very light and stiff, expensive)."],["Un bon bras est léger loin de la base et raide partout : moteurs près de la base, segments creux.","Le couple à l'épaule grandit avec la portée : τ = m g d.","Matériaux : aluminium (léger), acier (raide, bon marché), carbone (très léger et raide, cher)."]],"keep":[[],[]],"eq":[["<i>τ</i> ≈ ( <i>m</i><sub>payload</sub> + ½ <i>m</i><sub>arm</sub> ) <i>g</i> <i>L</i>","<i>δ</i> = <i>F</i> <i>L</i>³ / (3 <i>E</i> <i>I</i>)"],["<i>τ</i> ≈ ( <i>m</i><sub>charge</sub> + ½ <i>m</i><sub>bras</sub> ) <i>g</i> <i>L</i>","<i>δ</i> = <i>F</i> <i>L</i>³ / (3 <i>E</i> <i>I</i>)"]],"kt":[["payload","reach","repeatability","stiffness","deflection","counterbalance","IP rating","cross-roller bearing"],["charge utile","portée","répétabilité","rigidité","flèche","équilibrage","indice IP","roulement à rouleaux croisés"]]},{"id":"l3","n":"3","m":13,"t":["End effectors and grasping: grippers, suction, tools","Effecteurs et préhension : pinces, ventouses, outils"],"ess":[["End effectors: two-finger grippers, suction cups, magnets, soft grippers, tools (torch, screwdriver).","A suction cup holds with F = ΔP × A (pressure difference × area).","A gripper holds by friction: 2 μ F ≥ m g, and we add a safety factor (often 2)."],["Effecteurs : pinces à deux doigts, ventouses, aimants, pinces souples, outils (torche, visseuse).","Une ventouse tient avec F = ΔP × A (différence de pression × surface).","Une pince tient par frottement : 2 μ F ≥ m g, et on ajoute un coefficient de sécurité (souvent 2)."]],"keep":[["<ul><li>The gripper is often the real limit of a robot project: choose it first, with the part, not last.</li><li>Test grasps with the real parts, at the real speed and acceleration.</li><li>Release is as important as grasp: pushing air to release a part, or a spring to open on power loss, avoids dropping or sticking.</li></ul>"],["<ul><li>La pince est souvent la vraie limite d'un projet de robot : la choisir en premier, avec la pièce, pas en dernier.</li><li>Testez les prises avec les vraies pièces, à la vraie vitesse et accélération.</li><li>Le relâchement est aussi important que la saisie : souffler de l'air pour lâcher une pièce, ou un ressort pour ouvrir en cas de coupure, évite chute ou collage.</li></ul>"]],"eq":[["2 <i>μ</i> <i>N</i> ≥ <i>SF</i> · <i>m</i> <i>g</i> so <i>N</i> ≥ <i>SF</i> · <i>m</i> <i>g</i> / (2 <i>μ</i>)"],["2 <i>μ</i> <i>N</i> ≥ <i>SF</i> · <i>m</i> <i>g</i> so <i>N</i> ≥ <i>SF</i> · <i>m</i> <i>g</i> / (2 <i>μ</i>)"]],"kt":[["end effector","gripper","vacuum cup","friction grip","form closure","TCP","flange","tool changer"],["effecteur","pince","ventouse","prise par frottement","fermeture de forme","TCP","bride","changeur d'outil"]]},{"id":"l4","n":"4","m":13,"t":["Electronics and embedded systems: power, drivers, controllers, buses","Électronique et systèmes embarqués : énergie, variateurs, contrôleurs, bus"],"ess":[["Power: P = U × I. Batteries are counted in Wh = V × Ah.","Microcontrollers run the real-time loops; a computer runs vision and planning.","An n-bit ADC on U volts reads steps of U / 2ⁿ."],["Puissance : P = U × I. Les batteries se comptent en Wh = V × Ah.","Les microcontrôleurs font tourner les boucles temps réel ; un ordinateur fait la vision et la planification.","Un CAN de n bits sur U volts lit des pas de U / 2ⁿ."]],"keep":[[],[]],"eq":[[],[]],"kt":[["battery management system","motor driver","MCU","PLC","CAN bus","EtherCAT","EMC","PWM"],["système de gestion de batterie","variateur moteur","MCU","automate (API)","bus CAN","EtherCAT","CEM","MLI (PWM)"]]},{"id":"l5","n":"5","m":14,"t":["Software and programming: ROS 2, simulators, robot languages","Logiciel et programmation : ROS 2, simulateurs, langages robots"],"ess":[["ROS 2 splits the software into nodes that talk by topics (streams), services (question/answer) and actions (long tasks).","Simulators (Gazebo, Isaac, MuJoCo, Webots) test the code before the real robot.","Version your code (git), test it, and log the data to understand bugs."],["ROS 2 découpe le logiciel en nœuds qui communiquent par topics (flux), services (question/réponse) et actions (tâches longues).","Les simulateurs (Gazebo, Isaac, MuJoCo, Webots) testent le code avant le vrai robot.","Versionnez votre code (git), testez-le, et enregistrez les données pour comprendre les bugs."]],"keep":[[],[]],"eq":[[],[]],"kt":[["teach pendant","offline programming","ROS 2","node / topic","tf2","URDF","digital twin","reality gap"],["console d'apprentissage","programmation hors ligne","ROS 2","nœud / topic","tf2","URDF","jumeau numérique","écart avec la réalité"]]},{"id":"l6","n":"6","m":13,"t":["Safety and standards: working next to robots","Sécurité et normes : travailler à côté des robots"],"ess":[["Safety first: risk analysis, guards and fences, light curtains, emergency stop, speed limits.","Main standards: ISO 10218 (industrial robots), ISO/TS 15066 (cobots), ISO 13849 (safety functions), ISO 13855 (distances).","Safety distance: S = K × T + C (approach speed × stopping time + margin)."],["La sécurité d'abord : analyse de risques, protecteurs et clôtures, barrières immatérielles, arrêt d'urgence, limites de vitesse.","Normes principales : ISO 10218 (robots industriels), ISO/TS 15066 (cobots), ISO 13849 (fonctions de sécurité), ISO 13855 (distances).","Distance de sécurité : S = K × T + C (vitesse d'approche × temps d'arrêt + marge)."]],"keep":[[],[]],"eq":[[],[]],"kt":[["risk assessment","ISO 10218","ISO/TS 15066","performance level","speed and separation monitoring","power and force limiting","safe torque off","emergency stop"],["analyse de risques","ISO 10218","ISO/TS 15066","niveau de performance","surveillance de vitesse et de distance","limitation de puissance et de force","arrêt de couple sûr","arrêt d'urgence"]]},{"id":"l7","n":"7","m":12,"t":["Calibration, accuracy and testing","Étalonnage, exactitude et essais"],"ess":[["Repeatability: coming back to the same point (very good, ~0.02 mm). Accuracy: reaching a point given in numbers (worse, ~1 mm).","Calibration measures the real geometry (lengths, angle offsets) and corrects the model.","Heat, load and wear change the robot: test and check regularly."],["Répétabilité : revenir au même point (très bonne, ~0,02 mm). Précision : atteindre un point donné en chiffres (moins bonne, ~1 mm).","L'étalonnage mesure la géométrie réelle (longueurs, décalages d'angle) et corrige le modèle.","La chaleur, la charge et l'usure changent le robot : testez et vérifiez régulièrement."]],"keep":[["<p><strong>Calibration improves accuracy, not repeatability.</strong> A robot that is repeatable to ±0.03 mm but 1 mm inaccurate can be taught points by hand and will return to them precisely (teach and repeat). It needs calibration when points come from a CAD model, a vision system, or when a robot is replaced: the program is then sent to a robot with different errors.</p>"],["<p><strong>L'étalonnage améliore l'exactitude, pas la répétabilité.</strong> Un robot répétable à ±0,03 mm mais inexact de 1 mm peut apprendre des points à la main et y reviendra précisément (apprentissage et répétition). Il a besoin d'étalonnage quand les points viennent d'un modèle CAO, d'un système de vision, ou quand un robot est remplacé : le programme est alors envoyé à un robot qui a d'autres erreurs.</p>"]],"eq":[[],[]],"kt":[["geometric error","kinematic calibration","mastering","laser tracker","work object","ISO 9283","warm-up","teach and repeat"],["erreur géométrique","étalonnage cinématique","calage","laser de poursuite","repère pièce","ISO 9283","mise en température","apprentissage et répétition"]]},{"id":"l8","n":"8","m":13,"t":["Applications and choosing a robot for a job","Applications et choix d'un robot pour un travail"],"ess":[["Choose a robot from the task: payload (with the gripper), reach, speed/cycle time, accuracy, environment.","Cycle time sets the production: parts per hour = 3600 / cycle time.","Payback time = cost / savings per year."],["Choisir un robot à partir de la tâche : charge (avec la pince), portée, vitesse/temps de cycle, précision, environnement.","Le temps de cycle fixe la production : pièces par heure = 3600 / temps de cycle.","Temps de retour sur investissement = coût / économies par an."]],"keep":[[],[]],"eq":[[],[]],"kt":[["cycle time","palletising","systems integrator","payback","total cost of ownership","mobile manipulator","feeding"],["temps de cycle","palettisation","intégrateur","retour sur investissement","coût total de possession","manipulateur mobile","alimentation en pièces"]]},{"id":"l9","n":"9","m":12,"t":["Your path: projects, tools, books and careers","Votre chemin : projets, outils, livres et métiers"],"ess":[["Robotics mixes mechanics, electronics, software and maths: start with one, learn the others step by step.","Build small projects (a 2-link arm, a line follower) and simulate before buying hardware.","Jobs: integrator, controls engineer, perception/AI engineer, technician, researcher."],["La robotique mélange mécanique, électronique, logiciel et maths : commencez par l'un, apprenez les autres pas à pas.","Construisez de petits projets (un bras à 2 segments, un suiveur de ligne) et simulez avant d'acheter du matériel.","Métiers : intégrateur, automaticien, ingénieur perception/IA, technicien, chercheur."]],"keep":[["<ul><li><strong>Build things.</strong> A robot that wobbles on your table teaches more than ten chapters.</li><li><strong>Simulate first, then test early on hardware</strong>, and keep a log of what failed.</li><li><strong>Learn the maths and the hardware.</strong> The best roboticists can move between the equation, the code and the screwdriver.</li><li><strong>Respect safety.</strong> Every robot you build can hurt someone; think about it from the first sketch.</li></ul>"],["<ul><li><strong>Construisez des choses.</strong> Un robot qui tremble sur votre table apprend plus que dix chapitres.</li><li><strong>Simulez d'abord, puis testez tôt sur le matériel</strong>, et tenez un journal de ce qui a échoué.</li><li><strong>Apprenez les maths et le matériel.</strong> Les meilleurs roboticiens passent sans mal de l'équation au code et au tournevis.</li><li><strong>Respectez la sécurité.</strong> Tout robot que vous construisez peut blesser quelqu'un ; pensez-y dès le premier croquis.</li></ul>"]],"eq":[[],[]],"kt":[["project ladder","hero project","RoboCup","open source","systems integrator","mechatronics"],["échelle de projets","projet héros","RoboCup","open source","intégrateur","mécatronique"]]}],"t":["Robots in the real world","Les robots dans le monde réel"]},{"page":"learn-armlab","title":["Code a robot arm in Python","Coder un bras robot en Python"],"lessons":[{"id":"l1","n":"1","m":15,"t":["Your workbench and a first arm in code","Votre établi et un premier bras en code"],"ess":[["NumPy works in radians: np.radians() and np.degrees() convert. A @ B is a matrix product.","The tool of a 2-axis arm is the sum of the arrows of the two links.","Test the code with poses you can check by eye before anything else."],["NumPy travaille en radians : np.radians() et np.degrees() convertissent. A @ B est un produit matriciel.","L'outil d'un bras à 2 axes est la somme des flèches des deux segments.","Testez le code avec des poses vérifiables à l'œil avant tout le reste."]],"keep":[["<ul><li>(0°, 0°): the arm is stretched along x, the tool must be at <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub> = 0.9 m.</li><li>(90°, −90°): link 1 points up, link 2 points right: tool at (0.4, 0.5).</li><li>(30°, 45°): the value computed by hand in the maths course, (0.537, 0.636).</li></ul>"],["<ul><li>(0°, 0°) : le bras est tendu selon x, l'outil doit être en <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub> = 0,9 m.</li><li>(90°, −90°) : le segment 1 pointe vers le haut, le segment 2 vers la droite : outil en (0,4 ; 0,5).</li><li>(30°, 45°) : la valeur calculée à la main dans le cours de maths, (0,537 ; 0,636).</li></ul>"]],"eq":[[],[]],"kt":[["NumPy","function","radians","matrix product @","test pose"],["NumPy","fonction","radians","produit matriciel @","pose de test"]]},{"id":"l2","n":"2","m":16,"t":["Any robot from its DH table","N'importe quel robot à partir de son tableau DH"],"ess":[["One function per row (dh_std or dh_mod), one loop that multiplies the rows.","The robot is data: change the table, not the code.","Check: both conventions give the same pose; the zero pose matches the drawing."],["Une fonction par ligne (dh_std ou dh_mod), une boucle qui multiplie les lignes.","Le robot est une donnée : on change le tableau, pas le code.","Vérification : les deux conventions donnent la même pose ; la pose zéro correspond au dessin."]],"keep":[[],[]],"eq":[[],[]],"kt":[["DH table","homogeneous matrix","loop","np.allclose"],["tableau DH","matrice homogène","boucle","np.allclose"]]},{"id":"l3","n":"3","m":16,"t":["Inverse kinematics in closed form","Le modèle inverse en formule fermée"],"ess":[["cos θ2 from the law of cosines; |cos θ2| &gt; 1 means out of reach.","Two solutions: sin θ2 = ±√(1 − cos² θ2), elbow up or down. Always use atan2.","Round trip test: fk(ik(x)) must give x back."],["cos θ2 par la loi des cosinus ; |cos θ2| &gt; 1 veut dire hors d'atteinte.","Deux solutions : sin θ2 = ±√(1 − cos² θ2), coude en haut ou en bas. Toujours atan2.","Test de l'aller-retour : fk(ik(x)) doit redonner x."]],"keep":[["<p>A real controller keeps the solution <strong>closest to the current pose</strong> (smallest joint motion), and checks the joint limits and the obstacles. Switching elbow in the middle of a motion makes the arm flip: never do it while moving.</p>"],["<p>Un vrai contrôleur garde la solution <strong>la plus proche de la pose actuelle</strong> (le plus petit mouvement des liaisons), et vérifie les butées et les obstacles. Changer de coude au milieu d'un mouvement fait basculer le bras : ne le faites jamais en marche.</p>"]],"eq":[["cos <i>θ</i><sub>2</sub> = (<i>x</i>² + <i>y</i>² − <i>L</i><sub>1</sub>² − <i>L</i><sub>2</sub>²) / (2 <i>L</i><sub>1</sub> <i>L</i><sub>2</sub>) <i>θ</i><sub>1</sub> = atan2(<i>y</i>, <i>x</i>) − atan2(<i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>, <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>)"],["cos <i>θ</i><sub>2</sub> = (<i>x</i>² + <i>y</i>² − <i>L</i><sub>1</sub>² − <i>L</i><sub>2</sub>²) / (2 <i>L</i><sub>1</sub> <i>L</i><sub>2</sub>) <i>θ</i><sub>1</sub> = atan2(<i>y</i>, <i>x</i>) − atan2(<i>L</i><sub>2</sub> sin <i>θ</i><sub>2</sub>, <i>L</i><sub>1</sub> + <i>L</i><sub>2</sub> cos <i>θ</i><sub>2</sub>)"]],"kt":[["inverse kinematics","closed form","law of cosines","elbow up / down","round trip test"],["modèle inverse (MGI)","formule fermée","loi des cosinus","coude haut / bas","test de l'aller-retour"]]},{"id":"l4","n":"4","m":18,"t":["The Jacobian and numerical inverse kinematics","La jacobienne et le modèle inverse numérique"],"ess":[["Jacobian by finite differences: turn joint i by h, measure the motion of the tool, divide by h.","Damped least squares: Δq = Jᵀ (J Jᵀ + λ² I)⁻¹ e, repeated until the error is small.","A local search can fail: restart from other guesses and always check the error."],["Jacobienne par différences finies : tourner la liaison i de h, mesurer le mouvement de l'outil, diviser par h.","Moindres carrés amortis : Δq = Jᵀ (J Jᵀ + λ² I)⁻¹ e, répété jusqu'à ce que l'erreur soit petite.","Une recherche locale peut échouer : redémarrer d'autres estimations et toujours vérifier l'erreur."]],"keep":[["<p>A numerical solver can return angles that do not reach the target. Never send its answer to the motors without checking the error with the forward model, as the code does with <code>np.linalg.norm(position(q_sol) - p)</code>.</p>"],["<p>Un solveur numérique peut renvoyer des angles qui n'atteignent pas la cible. N'envoyez jamais sa réponse aux moteurs sans vérifier l'erreur avec le modèle direct, comme le fait le code avec <code>np.linalg.norm(position(q_sol) - p)</code>.</p>"]],"eq":[[],[]],"kt":[["Jacobian","finite difference","damped least squares","local minimum","restart"],["jacobienne","différence finie","moindres carrés amortis","minimum local","redémarrage"]]},{"id":"l5","n":"5","m":22,"t":["From the code to a real arm: trajectories and servos","Du code à un vrai bras : trajectoires et servomoteurs"],"ess":[["Quintic law: zero speed and acceleration at both ends; peak speed = 1.875 × average.","Servo: the pulse width sets the angle (about 500–2500 µs for 0–180°); measure each offset once.","Separate power for the servos, common ground, maths in Python, the Arduino only moves the servos."],["Loi quintique : vitesse et accélération nulles aux deux bouts ; vitesse de pointe = 1,875 × moyenne.","Servo : la largeur d'impulsion fixe l'angle (environ 500–2500 µs pour 0–180°) ; mesurez chaque décalage une fois.","Alimentation séparée pour les servos, masse commune, maths en Python, l'Arduino ne fait que bouger les servos."]],"keep":[[],[]],"eq":[[],[]],"kt":[["quintic trajectory","servo","pulse width","offset calibration","serial link"],["trajectoire quintique","servomoteur","largeur d'impulsion","étalonnage du décalage","liaison série"]]},{"id":"l6","n":"6","m":60,"t":["Final exam and labs: prove it","Examen final et TP : prouvez-le"],"ess":[[],[]],"keep":[[],[]],"eq":[[],[]],"kt":[["exam","lab","pass criterion"],["examen","TP","critère de réussite"]]}],"t":["Code a robot arm in Python","Coder un bras robot en Python"]},{"page":"learn-advanced","title":["Advanced robotics (Master level)","Robotique avancée (niveau Master)"],"lessons":[{"id":"l1","n":"1","m":20,"t":["Parallel robots: the Delta and the Stewart platform","Les robots parallèles : le Delta et la plateforme de Stewart"],"ess":[["Parallel robot: several chains hold the platform; the motors stay on the base: fast and stiff.","Inverse kinematics is easy (one formula per chain); forward kinematics is hard (several solutions).","Stewart: leg length ℓᵢ = ‖p + R bᵢ − aᵢ‖. Beware of parallel (type 2) singularities."],["Robot parallèle : plusieurs chaînes tiennent la plateforme ; les moteurs restent sur la base : rapide et rigide.","Le modèle inverse est facile (une formule par chaîne) ; le modèle direct est difficile (plusieurs solutions).","Stewart : longueur de jambe ℓᵢ = ‖p + R bᵢ − aᵢ‖. Attention aux singularités parallèles (type 2)."]],"keep":[[],[]],"eq":[["<i>k</i> = (<i>x</i><sub>q</sub>² + <i>y</i><sub>q</sub>² + <i>z</i><sub>q</sub>² + <i>L</i>² − <i>l</i>²) / (2<i>L</i>) <i>ρ</i> = √(<i>x</i><sub>q</sub>² + <i>z</i><sub>q</sub>²) <i>θ</i> = −atan2(<i>z</i><sub>q</sub>, <i>x</i><sub>q</sub>) − arccos(<i>k</i> / <i>ρ</i>)","<i>ℓ</i><sub>i</sub> = ‖ <strong>p</strong> + <i>R</i> <strong>b</strong><sub>i</sub> − <strong>a</strong><sub>i</sub> ‖"],["<i>k</i> = (<i>x</i><sub>q</sub>² + <i>y</i><sub>q</sub>² + <i>z</i><sub>q</sub>² + <i>L</i>² − <i>l</i>²) / (2<i>L</i>) <i>ρ</i> = √(<i>x</i><sub>q</sub>² + <i>z</i><sub>q</sub>²) <i>θ</i> = −atan2(<i>z</i><sub>q</sub>, <i>x</i><sub>q</sub>) − arccos(<i>k</i> / <i>ρ</i>)","<i>ℓ</i><sub>i</sub> = ‖ <strong>p</strong> + <i>R</i> <strong>b</strong><sub>i</sub> − <strong>a</strong><sub>i</sub> ‖"]],"kt":[["parallel robot","closed chain","Delta robot","Stewart platform","parallel singularity"],["robot parallèle","chaîne fermée","robot Delta","plateforme de Stewart","singularité parallèle"]]},{"id":"l2","n":"2","m":18,"t":["Optimal control: the LQR","Commande optimale : le LQR"],"ess":[["LQR: minimise ∫ (xᵀQx + uᵀRu) dt; Q = price of the errors, R = price of the commands.","The optimal controller is u = −K x, K = R⁻¹ Bᵀ P with P from the Riccati equation.","Bryson's rule: 1 / (largest acceptable value)² on the diagonal."],["LQR : minimiser ∫ (xᵀQx + uᵀRu) dt ; Q = prix des erreurs, R = prix des commandes.","La commande optimale est u = −K x, K = R⁻¹ Bᵀ P avec P issu de l'équation de Riccati.","Règle de Bryson : 1 / (plus grande valeur acceptable)² sur la diagonale."]],"keep":[["<p>The best controller is always a simple state feedback <strong><i>u</i> = −<i>K x</i></strong>, with <i>K</i> = <i>R</i><sup>−1</sup> <i>B</i><sup>T</sup> <i>P</i>, where <i>P</i> solves the <strong>Riccati equation</strong>:</p> <p class=\"eq\"><i>A</i><sup>T</sup> <i>P</i> + <i>P A</i> − <i>P B R</i><sup>−1</sup> <i>B</i><sup>T</sup> <i>P</i> + <i>Q</i> = 0</p> <p>You never solve it by hand: every library has a function (<code>scipy.linalg.solve_continuous_are</code>, <code>lqr</code> in MATLAB). The closed loop is <strong>always stable</strong> when the system is controllable.</p>"],["<p>La meilleure commande est toujours un simple retour d'état <strong><i>u</i> = −<i>K x</i></strong>, avec <i>K</i> = <i>R</i><sup>−1</sup> <i>B</i><sup>T</sup> <i>P</i>, où <i>P</i> résout l'<strong>équation de Riccati</strong> :</p> <p class=\"eq\"><i>A</i><sup>T</sup> <i>P</i> + <i>P A</i> − <i>P B R</i><sup>−1</sup> <i>B</i><sup>T</sup> <i>P</i> + <i>Q</i> = 0</p> <p>On ne la résout jamais à la main : chaque bibliothèque a une fonction (<code>scipy.linalg.solve_continuous_are</code>, <code>lqr</code> sous MATLAB). La boucle fermée est <strong>toujours stable</strong> quand le système est commandable.</p>"]],"eq":[["<i>J</i> = ∫ ( <i>x</i><sup>T</sup> <i>Q</i> <i>x</i> + <i>u</i><sup>T</sup> <i>R</i> <i>u</i> ) d<i>t</i>","<i>A</i><sup>T</sup> <i>P</i> + <i>P A</i> − <i>P B R</i><sup>−1</sup> <i>B</i><sup>T</sup> <i>P</i> + <i>Q</i> = 0"],["<i>J</i> = ∫ ( <i>x</i><sup>T</sup> <i>Q</i> <i>x</i> + <i>u</i><sup>T</sup> <i>R</i> <i>u</i> ) d<i>t</i>","<i>A</i><sup>T</sup> <i>P</i> + <i>P A</i> − <i>P B R</i><sup>−1</sup> <i>B</i><sup>T</sup> <i>P</i> + <i>Q</i> = 0"]],"kt":[["LQR","cost function","Riccati equation","state feedback","Bryson's rule","LQG"],["LQR","fonction de coût","équation de Riccati","retour d'état","règle de Bryson","LQG"]]},{"id":"l3","n":"3","m":18,"t":["Model predictive control (MPC)","La commande prédictive (MPC)"],"ess":[["MPC: predict over a horizon, optimise the commands under constraints, apply only the first, repeat.","Its main advantage: the limits of the motors are part of the plan.","Fast QP solvers run it at 100 Hz to 1 kHz on legged robots, cars and drones."],["MPC : prédire sur un horizon, optimiser les commandes sous contraintes, n'appliquer que la première, recommencer.","Son principal avantage : les limites des moteurs font partie du plan.","Des solveurs QP rapides la font tourner à 100 Hz – 1 kHz sur les robots à pattes, voitures et drones."]],"keep":[[],[]],"eq":[[],[]],"kt":[["model predictive control (MPC)","horizon","receding horizon","constraint","quadratic programme"],["commande prédictive (MPC)","horizon","horizon glissant","contrainte","programme quadratique"]]},{"id":"l4","n":"4","m":18,"t":["Legged robots: balance, ZMP and the inverted pendulum","Les robots à pattes : équilibre, ZMP et pendule inversé"],"ess":[["Static balance: the centre of mass above the support polygon. Dynamic balance: the ZMP inside it.","Linear inverted pendulum: ẍ = ω²(x − p), ω = √(g/z_c): walking is a controlled fall.","Capture point ξ = x + ẋ/ω: put the foot there to stop."],["Équilibre statique : le centre de masse au-dessus du polygone de sustentation. Équilibre dynamique : le ZMP dedans.","Pendule inversé linéaire : ẍ = ω²(x − p), ω = √(g/z_c) : marcher, c'est tomber de façon contrôlée.","Point de capture ξ = x + ẋ/ω : y poser le pied pour s'arrêter."]],"keep":[[],[]],"eq":[["<i>ẍ</i> = <i>ω</i>² ( <i>x</i> − <i>p</i> ) <i>ω</i> = √( <i>g</i> / <i>z</i><sub>c</sub> )","<i>ξ</i> = <i>x</i> + <i>ẋ</i> / <i>ω</i>"],["<i>ẍ</i> = <i>ω</i>² ( <i>x</i> − <i>p</i> ) <i>ω</i> = √( <i>g</i> / <i>z</i><sub>c</sub> )","<i>ξ</i> = <i>x</i> + <i>ẋ</i> / <i>ω</i>"]],"kt":[["support polygon","zero moment point (ZMP)","linear inverted pendulum","capture point","gait","whole-body control"],["polygone de sustentation","point de moment nul (ZMP)","pendule inversé linéaire","point de capture","allure","commande du corps entier"]]},{"id":"l5","n":"5","m":16,"t":["Aerial robots: how a quadrotor flies and is controlled","Les robots aériens : comment un quadrirotor vole et se commande"],"ess":[["Hover: total thrust = m g, shared by the 4 motors; thrust ∝ (speed of the propeller)².","Underactuated: to move, the drone tilts; a = g tan φ.","Cascade: position (slow) → attitude → angular rate (fast) → mixer → motors."],["Vol stationnaire : poussée totale = m g, partagée par les 4 moteurs ; poussée ∝ (vitesse de l'hélice)².","Sous-actionné : pour se déplacer, le drone s'incline ; a = g tan φ.","Cascade : position (lent) → attitude → vitesse angulaire (rapide) → mélangeur → moteurs."]],"keep":[["<p>Each inner loop is 5 to 10 times faster than the one around it (control course, lesson 8). The outer loop can then consider that its order is executed at once. The attitude is estimated by fusing the gyroscope (fast, drifts) and the accelerometer (slow, noisy) with a complementary or Kalman filter, as quaternions (maths course, lesson 11).</p>"],["<p>Chaque boucle interne est 5 à 10 fois plus rapide que celle qui l'entoure (cours de commande, leçon 8). La boucle externe peut alors considérer que son ordre est exécuté tout de suite. L'attitude est estimée en fusionnant le gyroscope (rapide, dérive) et l'accéléromètre (lent, bruité) avec un filtre complémentaire ou de Kalman, en quaternions (cours de maths, leçon 11).</p>"]],"eq":[[],[]],"kt":[["thrust","underactuated","mixer","attitude","cascade control","ESC"],["poussée","sous-actionné","mélangeur","attitude","commande en cascade","ESC (variateur)"]]},{"id":"l6","n":"6","m":18,"t":["Vision in practice: calibration, markers, hand-eye and point clouds","La vision en pratique : étalonnage, marqueurs, main-œil et nuages de points"],"ess":[["Intrinsic calibration (checkerboard) gives K: focal length and image centre, plus distortion.","A marker gives its pose by PnP; hand-eye calibration (A X = X B) links the camera to the robot.","Depth → point cloud: X = (u − cx) Z / f. RANSAC removes the table; then compute the grasp."],["L'étalonnage intrinsèque (damier) donne K : focale et centre de l'image, plus la distorsion.","Un marqueur donne sa pose par PnP ; l'étalonnage main-œil (A X = X B) relie la caméra au robot.","Profondeur → nuage de points : X = (u − cx) Z / f. RANSAC retire la table ; puis on calcule la prise."]],"keep":[[],[]],"eq":[["<i>u</i> = <i>f</i><sub>x</sub> <i>X</i>/<i>Z</i> + <i>c</i><sub>x</sub> <i>v</i> = <i>f</i><sub>y</sub> <i>Y</i>/<i>Z</i> + <i>c</i><sub>y</sub> <i>K</i> = <span class=\"mx c3\"><span><i>f</i><sub>x</sub></span><span>0</span><span><i>c</i><sub>x</sub></span><span>0</span><span><i>f</i><sub>y</sub></span><span><i>c</i><sub>y</sub></span><span>0</span><span>0</span><span>1</span></span>","<i>X</i> = (<i>u</i> − <i>c</i><sub>x</sub>) <i>Z</i> / <i>f</i><sub>x</sub> <i>Y</i> = (<i>v</i> − <i>c</i><sub>y</sub>) <i>Z</i> / <i>f</i><sub>y</sub>"],["<i>u</i> = <i>f</i><sub>x</sub> <i>X</i>/<i>Z</i> + <i>c</i><sub>x</sub> <i>v</i> = <i>f</i><sub>y</sub> <i>Y</i>/<i>Z</i> + <i>c</i><sub>y</sub> <i>K</i> = <span class=\"mx c3\"><span><i>f</i><sub>x</sub></span><span>0</span><span><i>c</i><sub>x</sub></span><span>0</span><span><i>f</i><sub>y</sub></span><span><i>c</i><sub>y</sub></span><span>0</span><span>0</span><span>1</span></span>","<i>X</i> = (<i>u</i> − <i>c</i><sub>x</sub>) <i>Z</i> / <i>f</i><sub>x</sub> <i>Y</i> = (<i>v</i> − <i>c</i><sub>y</sub>) <i>Z</i> / <i>f</i><sub>y</sub>"]],"kt":[["intrinsic parameters","camera calibration","fiducial marker","PnP","hand-eye calibration","point cloud","RANSAC"],["paramètres intrinsèques","étalonnage de caméra","marqueur fiduciaire","PnP","étalonnage main-œil","nuage de points","RANSAC"]]},{"id":"l7","n":"7","m":18,"t":["Reinforcement learning for robots","L'apprentissage par renforcement pour les robots"],"ess":[["Agent, state, action, reward, policy; goal: maximise G = Σ γᵏ rₖ.","Q-learning: Q ← Q + α (r + γ max Q′ − Q). Continuous actions: policy gradient (PPO, SAC).","Train in simulation with domain randomisation, then transfer with safety layers."],["Agent, état, action, récompense, politique ; but : maximiser G = Σ γᵏ rₖ.","Q-learning : Q ← Q + α (r + γ max Q′ − Q). Actions continues : gradient de politique (PPO, SAC).","Entraîner en simulation avec randomisation de domaine, puis transférer avec des couches de sécurité."]],"keep":[[],[]],"eq":[["<i>G</i> = <i>r</i><sub>0</sub> + <i>γ</i> <i>r</i><sub>1</sub> + <i>γ</i>² <i>r</i><sub>2</sub> + …","<i>Q</i>(<i>s</i>, <i>a</i>) ← <i>Q</i>(<i>s</i>, <i>a</i>) + <i>α</i> [ <i>r</i> + <i>γ</i> max<sub><i>a</i>′</sub> <i>Q</i>(<i>s</i>′, <i>a</i>′) − <i>Q</i>(<i>s</i>, <i>a</i>) ]"],["<i>G</i> = <i>r</i><sub>0</sub> + <i>γ</i> <i>r</i><sub>1</sub> + <i>γ</i>² <i>r</i><sub>2</sub> + …","<i>Q</i>(<i>s</i>, <i>a</i>) ← <i>Q</i>(<i>s</i>, <i>a</i>) + <i>α</i> [ <i>r</i> + <i>γ</i> max<sub><i>a</i>′</sub> <i>Q</i>(<i>s</i>′, <i>a</i>′) − <i>Q</i>(<i>s</i>, <i>a</i>) ]"]],"kt":[["agent / environment","policy","reward","Q-learning","policy gradient (PPO)","reward hacking","sim-to-real","domain randomisation"],["agent / environnement","politique","récompense","Q-learning","gradient de politique (PPO)","détournement de récompense","simulation vers réalité","randomisation de domaine"]]},{"id":"l8","n":"8","m":24,"t":["Grasping in practice: choose, size and test a gripper","La préhension en pratique : choisir, dimensionner et tester un préhenseur"],"ess":[["Start from the part and the cycle: mass, surface, fragility, free faces, accelerations, environment.","Friction grip: n μ N ≥ S m (g + a); V-jaws give μ / sin(α/2); a vacuum cup gives ΔP π d² / 4.","Check the payload and wrist moment on the load diagram, and test at full speed with the real parts."],["Partir de la pièce et du cycle : masse, surface, fragilité, faces libres, accélérations, environnement.","Prise par frottement : n μ N ≥ S m (g + a) ; les mors en V donnent μ / sin(α/2) ; une ventouse donne ΔP π d² / 4.","Vérifier la charge et le moment au poignet sur le diagramme de charge, et tester à pleine vitesse avec les vraies pièces."]],"keep":[["<ul><li>Choose the gripper with the part, at the start of the project, not at the end.</li><li>Size with the worst case: lowest μ, lowest pressure, highest acceleration, and a safety factor.</li><li>Always prove the grasp with real parts at full speed, and check what happens when the energy is lost.</li></ul>"],["<ul><li>Choisissez le préhenseur avec la pièce, au début du projet, pas à la fin.</li><li>Dimensionnez sur le pire cas : μ le plus bas, pression la plus basse, accélération la plus haute, et un coefficient de sécurité.</li><li>Prouvez toujours la prise avec de vraies pièces à pleine vitesse, et vérifiez ce qui se passe en cas de perte d'énergie.</li></ul>"]],"eq":[["<i>n</i> · <i>μ</i> · <i>N</i> ≥ <i>S</i> · <i>m</i> · ( <i>g</i> + <i>a</i> ) ⇒ <i>N</i> ≥ <i>S</i> · <i>m</i> · ( <i>g</i> + <i>a</i> ) / ( <i>n</i> · <i>μ</i> )","<i>F</i><sub>piston</sub> = <i>p</i> · π <i>D</i>² / 4 <i>N</i><sub>jaw</sub> ≈ <i>η</i> · <i>F</i><sub>piston</sub> / <i>n</i>","<i>F</i><sub>cup</sub> = Δ<i>P</i> · π <i>d</i>² / 4 number of cups ≥ <i>S</i> · <i>m</i> · ( <i>g</i> + <i>a</i> ) / <i>F</i><sub>cup</sub>","<i>m</i><sub>t</sub> = <i>m</i><sub>g</sub> + <i>m</i><sub>p</sub> <i>d</i> = ( <i>m</i><sub>g</sub> <i>d</i><sub>g</sub> + <i>m</i><sub>p</sub> <i>d</i><sub>p</sub> ) / <i>m</i><sub>t</sub> <i>M</i><sub>wrist</sub> = <i>m</i><sub>t</sub> · <i>g</i> · <i>d</i>"],["<i>n</i> · <i>μ</i> · <i>N</i> ≥ <i>S</i> · <i>m</i> · ( <i>g</i> + <i>a</i> ) ⇒ <i>N</i> ≥ <i>S</i> · <i>m</i> · ( <i>g</i> + <i>a</i> ) / ( <i>n</i> · <i>μ</i> )","<i>F</i><sub>piston</sub> = <i>p</i> · π <i>D</i>² / 4 <i>N</i><sub>mors</sub> ≈ <i>η</i> · <i>F</i><sub>piston</sub> / <i>n</i>","<i>F</i><sub>ventouse</sub> = Δ<i>P</i> · π <i>d</i>² / 4 nombre de ventouses ≥ <i>S</i> · <i>m</i> · ( <i>g</i> + <i>a</i> ) / <i>F</i><sub>ventouse</sub>","<i>m</i><sub>t</sub> = <i>m</i><sub>p</sub> + <i>m</i><sub>pi</sub> <i>d</i> = ( <i>m</i><sub>p</sub> <i>d</i><sub>p</sub> + <i>m</i><sub>pi</sub> <i>d</i><sub>pi</sub> ) / <i>m</i><sub>t</sub> <i>M</i><sub>poignet</sub> = <i>m</i><sub>t</sub> · <i>g</i> · <i>d</i>"]],"kt":[["force-fit / form-fit grip","safety factor S","V-jaw","pneumatic / electric gripper","vacuum cup, venturi ejector","load diagram","friction cone","antipodal grasp","force closure"],["prise par frottement / par forme","coefficient de sécurité S","mors en V","pince pneumatique / électrique","ventouse, éjecteur venturi","diagramme de charge","cône de frottement","prise antipodale","fermeture en force"]]}],"t":["Advanced robotics (Master)","Robotique avancée (Master)"]},{"page":"learn-ros","title":["ROS 2 from zero","ROS 2 depuis zéro"],"lessons":[{"id":"l1","n":"1","m":10,"t":["What ROS 2 is, and why robots use it","Ce qu'est ROS 2, et pourquoi les robots l'utilisent"],"ess":[["ROS 2 is not an operating system: it is the software that lets the programs of a robot talk to each other, plus tools and libraries.","A robot is split into small programs (nodes) that each do one job.","In every new terminal: <code>source /opt/ros/jazzy/setup.bash</code>."],["ROS 2 n'est pas un système d'exploitation : c'est le logiciel qui fait se parler les programmes d'un robot, plus des outils et des bibliothèques.","Un robot est découpé en petits programmes (nœuds) qui font chacun un seul travail.","Dans chaque nouveau terminal : <code>source /opt/ros/jazzy/setup.bash</code>."]],"keep":[["<p><code>ros2: command not found</code> means you forgot <code>source /opt/ros/jazzy/setup.bash</code> in this terminal. Every new terminal needs it.</p>"],["<p><code>ros2: command not found</code> veut dire que vous avez oublié <code>source /opt/ros/jazzy/setup.bash</code> dans ce terminal. Chaque nouveau terminal en a besoin.</p>"]],"eq":[[],[]],"kt":[["middleware","node","distribution","LTS","colcon"],["intergiciel","nœud","distribution","LTS","colcon"]]},{"id":"l2","n":"2","m":12,"t":["Nodes, topics and messages","Nœuds, topics et messages"],"ess":[["A node publishes messages on a topic; any node can subscribe to it. Nobody answers.","Each topic has one message type. Units are always metres, seconds and radians.","<code>ros2 topic list / echo / hz / info</code> show what really happens."],["Un nœud publie des messages sur un topic ; n'importe quel nœud peut s'y abonner. Personne ne répond.","Chaque topic a un seul type de message. Les unités sont toujours le mètre, la seconde et le radian.","<code>ros2 topic list / echo / hz / info</code> montrent ce qui se passe vraiment."]],"keep":[["<p>ROS uses SI units everywhere: <strong>metres, seconds, radians, kilograms</strong>. Never degrees, never millimetres. The x axis of a robot points <strong>forward</strong>, y to the <strong>left</strong>, z <strong>up</strong>.</p>"],["<p>ROS utilise partout les unités SI : <strong>mètres, secondes, radians, kilogrammes</strong>. Jamais de degrés, jamais de millimètres. L'axe x d'un robot pointe vers l'<strong>avant</strong>, y vers la <strong>gauche</strong>, z vers le <strong>haut</strong>.</p>"]],"eq":[[],[]],"kt":[["node","topic","publisher","subscriber","message type","quality of service (QoS)"],["nœud","topic","éditeur","abonné","type de message","qualité de service (QoS)"]]},{"id":"l3","n":"3","m":14,"t":["Your first nodes in Python","Vos premiers nœuds en Python"],"ess":[["A node is a class: it creates publishers, subscribers and timers.","ROS 2 calls your callbacks when a message arrives or a timer fires; keep them short.","Build with <code>colcon build</code>, then <code>source install/setup.bash</code>, then <code>ros2 run</code>."],["Un nœud est une classe : il crée des éditeurs, des abonnés et des minuteries.","ROS 2 appelle vos callbacks quand un message arrive ou qu'une minuterie sonne ; gardez-les courts.","Compilez avec <code>colcon build</code>, puis <code>source install/setup.bash</code>, puis <code>ros2 run</code>."]],"keep":[[],[]],"eq":[[],[]],"kt":[["workspace","package","rclpy","callback","timer","spin"],["espace de travail","paquet","rclpy","callback (fonction de rappel)","minuterie","spin"]]},{"id":"l4","n":"4","m":13,"t":["Services, actions and parameters","Services, actions et paramètres"],"ess":[["Topic: data that flows. Service: a quick question and its answer. Action: a long task you can follow and cancel.","A parameter is a named setting of a node; it can be changed while the node runs.","Use the standard interfaces whenever one fits."],["Topic : des données qui coulent. Service : une question rapide et sa réponse. Action : une tâche longue que l'on peut suivre et annuler.","Un paramètre est un réglage nommé d'un nœud ; on peut le changer pendant que le nœud tourne.","Utilisez les interfaces standards dès qu'une convient."]],"keep":[["<ul><li>Data that flows without being asked → <strong>topic</strong>.</li><li>A question with a quick answer (less than a second) → <strong>service</strong>.</li><li>A task that takes time, that you want to follow or cancel → <strong>action</strong>.</li></ul>"],["<ul><li>Des données qui coulent sans qu'on les demande → <strong>topic</strong>.</li><li>Une question avec une réponse rapide (moins d'une seconde) → <strong>service</strong>.</li><li>Une tâche qui prend du temps, que l'on veut suivre ou annuler → <strong>action</strong>.</li></ul>"]],"eq":[[],[]],"kt":[["service","request / response","action","goal / feedback / result","parameter","interface"],["service","requête / réponse","action","but / retour / résultat","paramètre","interface"]]},{"id":"l5","n":"5","m":10,"t":["Launch files: start a whole robot with one command","Fichiers de lancement : démarrer tout un robot en une commande"],"ess":[["A launch file starts many nodes with one command.","Parameters change the settings, remapping changes a topic name, a namespace adds a prefix to all the names.","Names without a leading slash follow the namespace: the same code works for several robots."],["Un fichier de lancement démarre beaucoup de nœuds en une commande.","Les paramètres changent les réglages, le renommage change un nom de topic, un espace de noms ajoute un préfixe à tous les noms.","Les noms sans barre oblique au début suivent l'espace de noms : le même code fonctionne pour plusieurs robots."]],"keep":[["<pre class=\"code\" tabindex=\"0\"><code>my_robot/ package.xml dependencies setup.py nodes and installed files my_robot/ the Python nodes launch/ *.launch.py config/ *.yaml (parameters) urdf/ the model of the robot (lesson 6)</code></pre>"],["<pre class=\"code\" tabindex=\"0\"><code>my_robot/ package.xml dependencies setup.py nodes and installed files my_robot/ the Python nodes launch/ *.launch.py config/ *.yaml (parameters) urdf/ the model of the robot (lesson 6)</code></pre>"]],"eq":[[],[]],"kt":[["launch file","launch argument","remapping","namespace","YAML"],["fichier de lancement","argument de lancement","renommage (remapping)","espace de noms","YAML"]]},{"id":"l6","n":"6","m":14,"t":["Frames and the robot model: tf2 and URDF","Les repères et le modèle du robot : tf2 et URDF"],"ess":[["tf2 keeps the tree of all the frames and gives the transform between any two of them.","Usual chain of a mobile robot: map → odom → base_link → sensors.","The URDF describes links and joints; robot_state_publisher turns it into frames."],["tf2 tient l'arbre de tous les repères et donne la transformation entre deux d'entre eux.","Chaîne habituelle d'un robot mobile : map → odom → base_link → capteurs.","L'URDF décrit les segments et les liaisons ; robot_state_publisher le transforme en repères."]],"keep":[[],[]],"eq":[[],[]],"kt":[["tf2","frame","transform","URDF","link / joint","robot_state_publisher","RViz"],["tf2","repère","transformation","URDF","segment / liaison","robot_state_publisher","RViz"]]},{"id":"l7","n":"7","m":12,"t":["Simulation and tools: Gazebo, RViz, rosbag","Simulation et outils : Gazebo, RViz, rosbag"],"ess":[["The simulator offers the same topics as the real robot: the same nodes work on both.","A mobile robot: you send <code>/cmd_vel</code>, it gives <code>/odom</code> and <code>/scan</code>.","rosbag records the topics of a test and replays them at your desk."],["Le simulateur offre les mêmes topics que le vrai robot : les mêmes nœuds fonctionnent sur les deux.","Un robot mobile : on envoie <code>/cmd_vel</code>, il donne <code>/odom</code> et <code>/scan</code>.","rosbag enregistre les topics d'un essai et les rejoue à votre bureau."]],"keep":[[],[]],"eq":[[],[]],"kt":[["simulator","Gazebo","rosbag","teleoperation","simulated time","LaserScan"],["simulateur","Gazebo","rosbag","téléopération","temps simulé","LaserScan"]]},{"id":"l8","n":"8","m":14,"t":["The big stacks: Nav2, MoveIt 2 and ros2_control","Les grandes piles logicielles : Nav2, MoveIt 2 et ros2_control"],"ess":[["slam_toolbox builds the map; Nav2 drives a mobile robot from A to B in it.","MoveIt 2 plans the motion of an arm without collision.","ros2_control links the controllers to the motors. Safety stays outside ROS 2."],["slam_toolbox construit la carte ; Nav2 y conduit un robot mobile de A à B.","MoveIt 2 planifie le mouvement d'un bras sans collision.","ros2_control relie les contrôleurs aux moteurs. La sécurité reste hors de ROS 2."]],"keep":[[],[]],"eq":[[],[]],"kt":[["SLAM","Nav2","AMCL","costmap","MoveIt 2","ros2_control","hardware interface"],["SLAM","Nav2","AMCL","carte de coût","MoveIt 2","ros2_control","interface matérielle"]]},{"id":"l9","n":"9","m":15,"t":["Project: a robot that drives and avoids obstacles","Projet : un robot qui roule et évite les obstacles"],"ess":[["Sense → think → act: subscribe to the sensor, decide in a timer, publish the command.","Parameters let you tune the node without editing it.","Always send a zero speed when the node stops."],["Percevoir → réfléchir → agir : s'abonner au capteur, décider dans une minuterie, publier la commande.","Les paramètres permettent de régler le nœud sans le modifier.","Envoyez toujours une vitesse nulle quand le nœud s'arrête."]],"keep":[[],[]],"eq":[[],[]],"kt":[["control loop","sensor QoS","TwistStamped","teleoperation"],["boucle de commande","QoS capteur","TwistStamped","téléopération"]]}],"t":["ROS 2 from zero","ROS 2 depuis zéro"]},{"page":"learn-mobile","title":["Wheeled mobile robots, part 1: how a robot rolls","Robots mobiles à roues, partie 1 : comment un robot roule"],"lessons":[{"id":"l1","n":"1","m":24,"t":["The maths toolbox: everything you need, from zero","La boîte à outils mathématique : tout ce qu'il faut, depuis zéro"],"ess":[["Work in SI units (m, s, rad, kg) and convert at once: 1 rev = 2π rad, rpm × 2π / 60 = rad/s.","Use atan2(y, x), not atan(y / x), to get an angle in the right quadrant.","A pose is integrated from speeds step by step: x ← x + v cos θ Δt, y ← y + v sin θ Δt, θ ← θ + ω Δt."],["Travaillez en unités SI (m, s, rad, kg) et convertissez tout de suite : 1 tour = 2π rad, tr/min × 2π / 60 = rad/s.","Utilisez atan2(y, x), pas atan(y / x), pour obtenir un angle dans le bon quadrant.","Une pose s'obtient en intégrant les vitesses pas à pas : x ← x + v cos θ Δt, y ← y + v sin θ Δt, θ ← θ + ω Δt."]],"keep":[[],[]],"eq":[["<i>s</i> = <i>r</i> <i>θ</i>","| <i>a</i> | = √( <i>a</i><sub>x</sub>² + <i>a</i><sub>y</sub>² ) &nbsp;&nbsp;&nbsp; direction = atan2( <i>a</i><sub>y</sub> , <i>a</i><sub>x</sub> )","<i>a</i> · <i>b</i> = <i>a</i><sub>x</sub> <i>b</i><sub>x</sub> + <i>a</i><sub>y</sub> <i>b</i><sub>y</sub> = | <i>a</i> | | <i>b</i> | cos( angle between them )","<span class=\"mx c2\"><span>a</span><span>b</span><span>c</span><span>d</span></span> <span class=\"mx c1\"><span>x</span><span>y</span></span> = <span class=\"mx c1\"><span>a x + b y</span><span>c x + d y</span></span>"],["<i>s</i> = <i>r</i> <i>θ</i>","| <i>a</i> | = √( <i>a</i><sub>x</sub>² + <i>a</i><sub>y</sub>² ) &nbsp;&nbsp;&nbsp; direction = atan2( <i>a</i><sub>y</sub> , <i>a</i><sub>x</sub> )","<i>a</i> · <i>b</i> = <i>a</i><sub>x</sub> <i>b</i><sub>x</sub> + <i>a</i><sub>y</sub> <i>b</i><sub>y</sub> = | <i>a</i> | | <i>b</i> | cos( angle entre eux )","<span class=\"mx c2\"><span>a</span><span>b</span><span>c</span><span>d</span></span> <span class=\"mx c1\"><span>x</span><span>y</span></span> = <span class=\"mx c1\"><span>a x + b y</span><span>c x + d y</span></span>"]],"kt":[["SI units","radian","atan2","unit vector","dot product","rotation matrix","integration (Euler)","rank / null space"],["unités SI","radian","atan2","vecteur unitaire","produit scalaire","matrice de rotation","intégration (Euler)","rang / espace nul"]]},{"id":"l2","n":"2","m":10,"t":["What is a wheeled mobile robot? Locomotion, kinematics and dynamics","Qu'est-ce qu'un robot mobile à roues ? Locomotion, cinématique et dynamique"],"ess":[["A robot senses, decides and acts: a wheeled mobile robot has locomotion, sensing, localisation, planning and control.","Kinematics links the wheel speeds to the motion of the robot, without the forces; dynamics adds the forces and masses.","Odometry computes the pose from the wheel motions: it is simple and fast, but it drifts."],["Un robot perçoit, décide et agit : un robot mobile à roues a une locomotion, des capteurs, une localisation, une planification et une commande.","La cinématique relie les vitesses des roues au mouvement du robot, sans les forces ; la dynamique ajoute les forces et les masses.","L'odométrie calcule la pose à partir des mouvements des roues : elle est simple et rapide, mais elle dérive."]],"keep":[[],[]],"eq":[[],[]],"kt":[["wheeled mobile robot (WMR)","locomotion","kinematics","dynamics","odometry","mobile manipulator"],["robot mobile à roues (WMR)","locomotion","cinématique","dynamique","odométrie","manipulateur mobile"]]},{"id":"l3","n":"3","m":11,"t":["Where is the robot? Pose, frames and the rotation matrix","Où est le robot ? Pose, repères et matrice de rotation"],"ess":[["On the floor the pose has three numbers: ξ = (x, y, θ).","R(θ) converts a velocity from the global frame to the robot frame: ξ̇_R = R(θ) ξ̇_I, and back with Rᵀ.","Forward kinematics: wheel speeds → robot velocity; inverse kinematics: wanted velocity → wheel speeds."],["Sur le sol, la pose a trois nombres : ξ = (x, y, θ).","R(θ) convertit une vitesse du repère global au repère robot : ξ̇_R = R(θ) ξ̇_I, et inversement avec Rᵀ.","Cinématique directe : vitesses des roues → vitesse du robot ; cinématique inverse : vitesse voulue → vitesses des roues."]],"keep":[[],[]],"eq":[["<i>ξ</i><sub>I</sub> = ( <i>x</i> , <i>y</i> , <i>θ</i> )<sup>T</sup> &nbsp;&nbsp; and its velocity &nbsp;&nbsp; <i>ξ̇</i><sub>I</sub> = ( <i>ẋ</i> , <i>ẏ</i> , <i>θ̇</i> )<sup>T</sup>","<i>R</i>(<i>θ</i>) = <span class=\"mx c3\"><span>cos θ</span><span>sin θ</span><span>0</span><span>− sin θ</span><span>cos θ</span><span>0</span><span>0</span><span>0</span><span>1</span></span> &nbsp;&nbsp;&nbsp; <i>ξ̇</i><sub>R</sub> = <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> &nbsp;&nbsp;&nbsp; <i>ξ̇</i><sub>I</sub> = <i>R</i>(<i>θ</i>)<sup>−1</sup> <i>ξ̇</i><sub>R</sub> = <i>R</i>(<i>θ</i>)<sup>T</sup> <i>ξ̇</i><sub>R</sub>"],["<i>ξ</i><sub>I</sub> = ( <i>x</i> , <i>y</i> , <i>θ</i> )<sup>T</sup> &nbsp;&nbsp; et sa vitesse &nbsp;&nbsp; <i>ξ̇</i><sub>I</sub> = ( <i>ẋ</i> , <i>ẏ</i> , <i>θ̇</i> )<sup>T</sup>","<i>R</i>(<i>θ</i>) = <span class=\"mx c3\"><span>cos θ</span><span>sin θ</span><span>0</span><span>− sin θ</span><span>cos θ</span><span>0</span><span>0</span><span>0</span><span>1</span></span> &nbsp;&nbsp;&nbsp; <i>ξ̇</i><sub>R</sub> = <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> &nbsp;&nbsp;&nbsp; <i>ξ̇</i><sub>I</sub> = <i>R</i>(<i>θ</i>)<sup>−1</sup> <i>ξ̇</i><sub>R</sub> = <i>R</i>(<i>θ</i>)<sup>T</sup> <i>ξ̇</i><sub>R</sub>"]],"kt":[["pose / posture","global (inertial) frame","robot frame","rotation matrix","forward / inverse kinematics"],["pose / posture","repère global (inertiel)","repère robot","matrice de rotation","cinématique directe / inverse"]]},{"id":"l4","n":"4","m":15,"t":["Wheels and their constraints: rolling and sliding","Les roues et leurs contraintes : roulement et glissement"],"ess":[["Five wheel types: fixed standard, steered standard, castor, Swedish (Mecanum) and spherical.","Rolling constraint: the contact point moves along the wheel plane at r φ̇ (pure rolling).","Sliding constraint: no speed across the wheel plane; only fixed and steered standard wheels impose it."],["Cinq types de roues : standard fixe, standard orientable, folle, suédoise (Mecanum) et sphérique.","Contrainte de roulement : le point de contact avance dans le plan de la roue à r φ̇ (roulement pur).","Contrainte de glissement : aucune vitesse en travers du plan de la roue ; seules les roues standard fixes et orientables l'imposent."]],"keep":[[],[]],"eq":[["<strong>Rolling:</strong> &nbsp; [ sin(<i>α</i>+<i>β</i>) &nbsp; −cos(<i>α</i>+<i>β</i>) &nbsp; −<i>l</i> cos <i>β</i> ] &nbsp; <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> − <i>r</i> <i>φ̇</i> = 0","<strong>Sliding:</strong> &nbsp; [ cos(<i>α</i>+<i>β</i>) &nbsp; sin(<i>α</i>+<i>β</i>) &nbsp; <i>l</i> sin <i>β</i> ] &nbsp; <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> = 0"],["<strong>Roulement :</strong> &nbsp; [ sin(<i>α</i>+<i>β</i>) &nbsp; −cos(<i>α</i>+<i>β</i>) &nbsp; −<i>l</i> cos <i>β</i> ] &nbsp; <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> − <i>r</i> <i>φ̇</i> = 0","<strong>Glissement :</strong> &nbsp; [ cos(<i>α</i>+<i>β</i>) &nbsp; sin(<i>α</i>+<i>β</i>) &nbsp; <i>l</i> sin <i>β</i> ] &nbsp; <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> = 0"]],"kt":[["rolling constraint","sliding constraint","fixed / steered standard wheel","castor wheel","Swedish (Mecanum) wheel","spherical wheel"],["contrainte de roulement","contrainte de glissement","roue standard fixe / orientable","roue folle","roue suédoise (Mecanum)","roue sphérique"]]},{"id":"l5","n":"5","m":16,"t":["Differential drive: the simplest mobile robot","Le robot différentiel : le robot mobile le plus simple"],"ess":[["v = (V_R + V_L) / 2 and ω = (V_R − V_L) / L, with V = r φ̇ for each wheel.","Inverse: V_R = v + ω L / 2 and V_L = v − ω L / 2.","Turning radius R = v / ω: equal speeds go straight, opposite speeds turn on the spot."],["v = (V_R + V_L) / 2 et ω = (V_R − V_L) / L, avec V = r φ̇ pour chaque roue.","Inverse : V_R = v + ω L / 2 et V_L = v − ω L / 2.","Rayon de virage R = v / ω : des vitesses égales vont tout droit, des vitesses opposées tournent sur place."]],"keep":[[],[]],"eq":[["<i>U</i> = ( <i>v</i> , <i>ω</i> )<sup>T</sup> &nbsp;&nbsp; <i>v</i> = linear speed of the robot (m/s) &nbsp;&nbsp; <i>ω</i> = angular speed (rad/s)","<i>V</i><sub>R</sub> = <i>r</i> <i>φ̇</i><sub>R</sub> &nbsp;&nbsp; <i>V</i><sub>L</sub> = <i>r</i> <i>φ̇</i><sub>L</sub> &nbsp;&nbsp;&nbsp;&nbsp; <i>v</i> = ( <i>V</i><sub>R</sub> + <i>V</i><sub>L</sub> ) / 2 &nbsp;&nbsp;&nbsp;&nbsp; <i>ω</i> = ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) / <i>L</i>","<strong>Inverse:</strong> &nbsp; <i>V</i><sub>R</sub> = <i>v</i> + <i>ω</i> <i>L</i> / 2 &nbsp;&nbsp;&nbsp; <i>V</i><sub>L</sub> = <i>v</i> − <i>ω</i> <i>L</i> / 2","<i>R</i> = ( <i>L</i> / 2 ) · ( <i>V</i><sub>R</sub> + <i>V</i><sub>L</sub> ) / ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) = <i>v</i> / <i>ω</i> &nbsp;&nbsp;&nbsp; ICC = ( <i>x</i> − <i>R</i> sin <i>θ</i> , &nbsp; <i>y</i> + <i>R</i> cos <i>θ</i> )"],["<i>U</i> = ( <i>v</i> , <i>ω</i> )<sup>T</sup> &nbsp;&nbsp; <i>v</i> = vitesse linéaire du robot (m/s) &nbsp;&nbsp; <i>ω</i> = vitesse angulaire (rad/s)","<i>V</i><sub>R</sub> = <i>r</i> <i>φ̇</i><sub>R</sub> &nbsp;&nbsp; <i>V</i><sub>L</sub> = <i>r</i> <i>φ̇</i><sub>L</sub> &nbsp;&nbsp;&nbsp;&nbsp; <i>v</i> = ( <i>V</i><sub>R</sub> + <i>V</i><sub>L</sub> ) / 2 &nbsp;&nbsp;&nbsp;&nbsp; <i>ω</i> = ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) / <i>L</i>","<strong>Inverse :</strong> &nbsp; <i>V</i><sub>R</sub> = <i>v</i> + <i>ω</i> <i>L</i> / 2 &nbsp;&nbsp;&nbsp; <i>V</i><sub>L</sub> = <i>v</i> − <i>ω</i> <i>L</i> / 2","<i>R</i> = ( <i>L</i> / 2 ) · ( <i>V</i><sub>R</sub> + <i>V</i><sub>L</sub> ) / ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) = <i>v</i> / <i>ω</i> &nbsp;&nbsp;&nbsp; ICC = ( <i>x</i> − <i>R</i> sin <i>θ</i> , &nbsp; <i>y</i> + <i>R</i> cos <i>θ</i> )"]],"kt":[["differential drive","ICC / ICR","turning radius","odometry","encoder","castor / ball wheel"],["entraînement différentiel","CIC / CIR","rayon de virage","odométrie","codeur","roue folle / bille"]]},{"id":"l6","n":"6","m":18,"t":["Tricycle, bicycle and car: steering and the Ackermann rule","Tricycle, vélo et voiture : braquage et règle d'Ackermann"],"ess":[["Bicycle model: ω = v tan δ / ℓ (wheelbase ℓ, steering angle δ); the ICR is on the rear axle.","Ackermann: the inside front wheel turns more than the outside one so that all wheel axes meet at the ICR.","A car has a minimum turning radius: it cannot turn on the spot or move sideways."],["Modèle bicyclette : ω = v tan δ / ℓ (empattement ℓ, angle de braquage δ) ; le CIR est sur l'essieu arrière.","Ackermann : la roue avant intérieure braque plus que l'extérieure pour que tous les axes de roues se coupent au CIR.","Une voiture a un rayon de virage minimal : elle ne peut ni tourner sur place ni aller de côté."]],"keep":[[],[]],"eq":[["<i>R</i> = <i>d</i> / tan <i>α</i> &nbsp;&nbsp;&nbsp; <i>v</i> = <i>v</i><sub>s</sub> cos <i>α</i> &nbsp;&nbsp;&nbsp; <i>ω</i> = ( <i>v</i><sub>s</sub> / <i>d</i> ) sin <i>α</i>","<span class=\"mx c1\"><span>ẋ</span><span>ẏ</span><span>θ̇</span></span> = <span class=\"mx c2\"><span>cos θ</span><span>0</span><span>sin θ</span><span>0</span><span>0</span><span>1</span></span> <span class=\"mx c1\"><span>v<sub>s</sub> cos α</span><span>(v<sub>s</sub> / d) sin α</span></span>","<i>φ̇</i><sub>C</sub> = <i>v</i> / <i>r</i><sub>C</sub> &nbsp;&nbsp;&nbsp; <i>φ̇</i><sub>F</sub> = <i>v</i> cos <i>δ</i> / <i>r</i><sub>F</sub> &nbsp;&nbsp;&nbsp; ( <i>ω</i> = <i>v</i> sin <i>δ</i> / <i>e</i> , &nbsp; <i>R</i> = <i>e</i> / tan <i>δ</i> )","<i>φ̇</i><sub>F1</sub> = <i>ω</i> ( <i>R</i> − <i>L</i>/2 ) / <i>r</i><sub>F1</sub> &nbsp;&nbsp; <i>φ̇</i><sub>F2</sub> = <i>ω</i> ( <i>R</i> + <i>L</i>/2 ) / <i>r</i><sub>F2</sub>"],["<i>R</i> = <i>d</i> / tan <i>α</i> &nbsp;&nbsp;&nbsp; <i>v</i> = <i>v</i><sub>s</sub> cos <i>α</i> &nbsp;&nbsp;&nbsp; <i>ω</i> = ( <i>v</i><sub>s</sub> / <i>d</i> ) sin <i>α</i>","<span class=\"mx c1\"><span>ẋ</span><span>ẏ</span><span>θ̇</span></span> = <span class=\"mx c2\"><span>cos θ</span><span>0</span><span>sin θ</span><span>0</span><span>0</span><span>1</span></span> <span class=\"mx c1\"><span>v<sub>s</sub> cos α</span><span>(v<sub>s</sub> / d) sin α</span></span>","<i>φ̇</i><sub>C</sub> = <i>v</i> / <i>r</i><sub>C</sub> &nbsp;&nbsp;&nbsp; <i>φ̇</i><sub>F</sub> = <i>v</i> cos <i>δ</i> / <i>r</i><sub>F</sub> &nbsp;&nbsp;&nbsp; ( <i>ω</i> = <i>v</i> sin <i>δ</i> / <i>e</i> , &nbsp; <i>R</i> = <i>e</i> / tan <i>δ</i> )","<i>φ̇</i><sub>F1</sub> = <i>ω</i> ( <i>R</i> − <i>L</i>/2 ) / <i>r</i><sub>F1</sub> &nbsp;&nbsp; <i>φ̇</i><sub>F2</sub> = <i>ω</i> ( <i>R</i> + <i>L</i>/2 ) / <i>r</i><sub>F2</sub>"]],"kt":[["tricycle","bicycle model","steering angle δ","wheelbase / track","Ackermann steering","ICC on the rear axle"],["tricycle","modèle bicyclette","angle de braquage δ","empattement / voie","Direction d'Ackermann","CIR sur l'essieu arrière"]]},{"id":"l7","n":"7","m":15,"t":["Omnidirectional robots and synchro drive","Robots omnidirectionnels et entraînement synchrone"],"ess":[["Swedish (omni) wheels roll along their rollers too, so the robot can move in any direction and rotate at once.","With three 90° Swedish wheels at 120°, every wheel speed is a linear combination of (v_x, v_y, ω): a 3 × 3 matrix and its inverse.","Synchro drive: all wheels are driven and steered together; it moves in any direction but cannot turn its body freely."],["Les roues suédoises (omni) roulent aussi le long de leurs rouleaux : le robot peut aller dans toutes les directions et tourner en même temps.","Avec trois roues suédoises à 90° placées à 120°, chaque vitesse de roue est une combinaison linéaire de (v_x, v_y, ω) : une matrice 3 × 3 et son inverse.","Entraînement synchrone : toutes les roues sont entraînées et orientées ensemble ; il va dans toutes les directions mais ne peut pas tourner son châssis librement."]],"keep":[[],[]],"eq":[["<i>J</i><sub>1</sub> = <span class=\"mx c3\"><span>√3 / 2</span><span>−1/2</span><span>−l</span><span>0</span><span>1</span><span>−l</span><span>−√3 / 2</span><span>−1/2</span><span>−l</span></span> &nbsp;&nbsp;&nbsp; <i>J</i><sub>1</sub> <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> = <i>r</i> ( <i>φ̇</i><sub>1</sub> , <i>φ̇</i><sub>2</sub> , <i>φ̇</i><sub>3</sub> )<sup>T</sup>","<i>ξ̇</i><sub>I</sub> = <i>R</i>(<i>θ</i>)<sup>−1</sup> <span class=\"mx c3\"><span>1/√3</span><span>0</span><span>−1/√3</span><span>−1/3</span><span>2/3</span><span>−1/3</span><span>−1/(3l)</span><span>−1/(3l)</span><span>−1/(3l)</span></span> <i>r</i> <span class=\"mx c1\"><span>φ̇<sub>1</sub></span><span>φ̇<sub>2</sub></span><span>φ̇<sub>3</sub></span></span>"],["<i>J</i><sub>1</sub> = <span class=\"mx c3\"><span>√3 / 2</span><span>−1/2</span><span>−l</span><span>0</span><span>1</span><span>−l</span><span>−√3 / 2</span><span>−1/2</span><span>−l</span></span> &nbsp;&nbsp;&nbsp; <i>J</i><sub>1</sub> <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> = <i>r</i> ( <i>φ̇</i><sub>1</sub> , <i>φ̇</i><sub>2</sub> , <i>φ̇</i><sub>3</sub> )<sup>T</sup>","<i>ξ̇</i><sub>I</sub> = <i>R</i>(<i>θ</i>)<sup>−1</sup> <span class=\"mx c3\"><span>1/√3</span><span>0</span><span>−1/√3</span><span>−1/3</span><span>2/3</span><span>−1/3</span><span>−1/(3l)</span><span>−1/(3l)</span><span>−1/(3l)</span></span> <i>r</i> <span class=\"mx c1\"><span>φ̇<sub>1</sub></span><span>φ̇<sub>2</sub></span><span>φ̇<sub>3</sub></span></span>"]],"kt":[["omnidirectional robot","Swedish 90° wheel","Mecanum wheel","holonomic","synchro drive","turret"],["robot omnidirectionnel","roue suédoise à 90°","roue Mecanum","holonome","entraînement synchrone","tourelle"]]},{"id":"l8","n":"8","m":16,"t":["More drives: Mecanum, swerve and skid-steer","Autres motorisations : Mecanum, swerve et direction par glissement"],"ess":[["Mecanum (X layout): each wheel speed = (v_x ∓ v_y ∓ (a + b) ω) / r, and FL + FR = RL + RR.","Swerve: each module gets its speed and angle from u = (v_x − ω y, v_y + ω x).","When a motor saturates, scale all the commands by the same factor: never clip one wheel alone."],["Mecanum (en X) : chaque vitesse de roue = (v_x ∓ v_y ∓ (a + b) ω) / r, et AVG + AVD = ARG + ARD.","Swerve : chaque module reçoit sa vitesse et son angle de u = (v_x − ω y, v_y + ω x).","Quand un moteur sature, réduisez toutes les commandes du même facteur : n'écrêtez jamais une seule roue."]],"keep":[[],[]],"eq":[["<span class=\"mx c1\"><span>φ̇<sub>FL</sub></span><span>φ̇<sub>FR</sub></span><span>φ̇<sub>RL</sub></span><span>φ̇<sub>RR</sub></span></span> = ( 1 / <i>r</i> ) <span class=\"mx c3\"><span>1</span><span>−1</span><span>−k</span><span>1</span><span>1</span><span>k</span><span>1</span><span>1</span><span>−k</span><span>1</span><span>−1</span><span>k</span></span> <span class=\"mx c1\"><span>v<sub>x</sub></span><span>v<sub>y</sub></span><span>ω</span></span>","<i>v</i><sub>x</sub> = ( <i>r</i> / 4 ) ( φ̇<sub>FL</sub> + φ̇<sub>FR</sub> + φ̇<sub>RL</sub> + φ̇<sub>RR</sub> ) &nbsp;&nbsp; <i>v</i><sub>y</sub> = ( <i>r</i> / 4 ) ( −φ̇<sub>FL</sub> + φ̇<sub>FR</sub> + φ̇<sub>RL</sub> − φ̇<sub>RR</sub> ) &nbsp;&nbsp; <i>ω</i> = ( <i>r</i> / 4<i>k</i> ) ( −φ̇<sub>FL</sub> + φ̇<sub>FR</sub> − φ̇<sub>RL</sub> + φ̇<sub>RR</sub> )","<i>u</i><sub>x</sub> = <i>v</i><sub>x</sub> − <i>ω</i> <i>y</i><sub>i</sub> &nbsp;&nbsp; <i>u</i><sub>y</sub> = <i>v</i><sub>y</sub> + <i>ω</i> <i>x</i><sub>i</sub> &nbsp;&nbsp; speed = √( <i>u</i><sub>x</sub>² + <i>u</i><sub>y</sub>² ) &nbsp;&nbsp; steering angle = atan2( <i>u</i><sub>y</sub> , <i>u</i><sub>x</sub> )","<i>ω</i> = ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) / ( <i>χ</i> <i>L</i> ) &nbsp;&nbsp;&nbsp; <i>χ</i> = ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) / ( <i>L</i> <i>ω</i><sub>measured</sub> )"],["<span class=\"mx c1\"><span>φ̇<sub>FL</sub></span><span>φ̇<sub>FR</sub></span><span>φ̇<sub>RL</sub></span><span>φ̇<sub>RR</sub></span></span> = ( 1 / <i>r</i> ) <span class=\"mx c3\"><span>1</span><span>−1</span><span>−k</span><span>1</span><span>1</span><span>k</span><span>1</span><span>1</span><span>−k</span><span>1</span><span>−1</span><span>k</span></span> <span class=\"mx c1\"><span>v<sub>x</sub></span><span>v<sub>y</sub></span><span>ω</span></span>","<i>v</i><sub>x</sub> = ( <i>r</i> / 4 ) ( φ̇<sub>FL</sub> + φ̇<sub>FR</sub> + φ̇<sub>RL</sub> + φ̇<sub>RR</sub> ) &nbsp;&nbsp; <i>v</i><sub>y</sub> = ( <i>r</i> / 4 ) ( −φ̇<sub>FL</sub> + φ̇<sub>FR</sub> + φ̇<sub>RL</sub> − φ̇<sub>RR</sub> ) &nbsp;&nbsp; <i>ω</i> = ( <i>r</i> / 4<i>k</i> ) ( −φ̇<sub>FL</sub> + φ̇<sub>FR</sub> − φ̇<sub>RL</sub> + φ̇<sub>RR</sub> )","<i>u</i><sub>x</sub> = <i>v</i><sub>x</sub> − <i>ω</i> <i>y</i><sub>i</sub> &nbsp;&nbsp; <i>u</i><sub>y</sub> = <i>v</i><sub>y</sub> + <i>ω</i> <i>x</i><sub>i</sub> &nbsp;&nbsp; vitesse = √( <i>u</i><sub>x</sub>² + <i>u</i><sub>y</sub>² ) &nbsp;&nbsp; angle de braquage = atan2( <i>u</i><sub>y</sub> , <i>u</i><sub>x</sub> )","<i>ω</i> = ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) / ( <i>χ</i> <i>L</i> ) &nbsp;&nbsp;&nbsp; <i>χ</i> = ( <i>V</i><sub>R</sub> − <i>V</i><sub>L</sub> ) / ( <i>L</i> <i>ω</i><sub>mesurée</sub> )"]],"kt":[["Mecanum wheel","swerve module","holonomic","saturation / scaling","skid steering","effective track χL","suspension"],["roue Mecanum","module swerve","holonome","saturation / mise à l'échelle","direction par glissement","voie effective χL","suspension"]]},{"id":"l9","n":"9","m":17,"t":["Maneuverability: how freely can a robot move?","Manœuvrabilité : quelle liberté de mouvement a un robot ?"],"ess":[["Stack the sliding constraints of all the wheels: the robot can only move in their null space.","The ICR is where all the zero-motion lines of the wheels meet.","δm = 3 − rank(C₁), δs = rank(C₁s), δM = δm + δs: differential (2, 0, 2), car (1, 1, 2), omni (3, 0, 3)."],["Empilez les contraintes de glissement de toutes les roues : le robot ne peut bouger que dans leur noyau.","Le CIR est le point où se coupent toutes les droites de vitesse nulle des roues.","δm = 3 − rang(C₁), δs = rang(C₁s), δM = δm + δs : différentiel (2, 0, 2), voiture (1, 1, 2), omni (3, 0, 3)."]],"keep":[[],[]],"eq":[["<strong>Rolling:</strong> &nbsp; <i>J</i><sub>1</sub>(<i>β</i><sub>s</sub>) <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> − <i>J</i><sub>2</sub> <i>φ̇</i> = 0 &nbsp;&nbsp;&nbsp; <strong>Sliding:</strong> &nbsp; <i>C</i><sub>1</sub>(<i>β</i><sub>s</sub>) <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> = 0"],["<strong>Roulement :</strong> &nbsp; <i>J</i><sub>1</sub>(<i>β</i><sub>s</sub>) <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> − <i>J</i><sub>2</sub> <i>φ̇</i> = 0 &nbsp;&nbsp;&nbsp; <strong>Glissement :</strong> &nbsp; <i>C</i><sub>1</sub>(<i>β</i><sub>s</sub>) <i>R</i>(<i>θ</i>) <i>ξ̇</i><sub>I</sub> = 0"]],"kt":[["null space","rank","zero-motion line","ICR","degree of mobility δm","degree of steerability δs","degree of maneuverability δM"],["espace nul","rang","ligne de mouvement nul","CIR","degré de mobilité δm","degré d'orientabilité δs","degré de manœuvrabilité δM"]]},{"id":"l10","n":"10","m":14,"t":["Holonomic or not? Degrees of freedom, paths and trajectories","Holonome ou non ? Degrés de liberté, chemins et trajectoires"],"ess":[["DOF = poses the robot can reach; DDOF = velocities it can produce at one instant.","Holonomic: DDOF = DOF. Nonholonomic: velocity constraints that cannot be integrated into position constraints.","A path is a curve in (x, y, θ); a trajectory is the same curve with the time."],["DDL = poses que le robot peut atteindre ; DDDL = vitesses qu'il peut produire à un instant.","Holonome : DDDL = DDL. Non holonome : des contraintes de vitesse qu'on ne peut pas intégrer en contraintes de position.","Un chemin est une courbe dans (x, y, θ) ; une trajectoire est la même courbe avec le temps."]],"keep":[[],[]],"eq":[["DDOF ≤ <i>δ</i><sub>M</sub> ≤ DOF","∂²<i>s</i> / ∂<i>x</i>∂<i>θ</i> = ∂²<i>s</i> / ∂<i>θ</i>∂<i>x</i> &nbsp;&nbsp; etc."],["DDDL ≤ <i>δ</i><sub>M</sub> ≤ DDL","∂²<i>s</i> / ∂<i>x</i>∂<i>θ</i> = ∂²<i>s</i> / ∂<i>θ</i>∂<i>x</i> &nbsp;&nbsp; etc."]],"kt":[["DOF / DDOF","holonomic","nonholonomic","integrable","path / trajectory","parallel parking"],["DDL / DDDL","holonome","non holonome","intégrable","chemin / trajectoire","créneau"]]}],"t":["Wheeled mobile robots, part 1","Robots mobiles à roues, partie 1"]},{"page":"learn-mobile-pro","title":["Wheeled mobile robots, part 2: professional level","Robots mobiles à roues, partie 2 : niveau professionnel"],"lessons":[{"id":"l11","n":"11","m":18,"t":["Motion control: driving a robot to a goal pose","Commande du mouvement : conduire un robot vers une pose but"],"ess":[["Open loop drives blind and accumulates errors; feedback measures the error and corrects it.","Polar coordinates of the goal: distance ρ, bearing α, and final heading error β.","v = kρ ρ, ω = kα α + kβ β is stable if kρ &gt; 0, kβ &lt; 0 and kα − kρ &gt; 0."],["La boucle ouverte conduit à l'aveugle et accumule les erreurs ; la rétroaction mesure l'erreur et la corrige.","Coordonnées polaires du but : distance ρ, angle d'approche α et erreur de cap finale β.","v = kρ ρ, ω = kα α + kβ β est stable si kρ &gt; 0, kβ &lt; 0 et kα − kρ &gt; 0."]],"keep":[[],[]],"eq":[["( <i>v</i> , <i>ω</i> )<sup>T</sup> = <i>K</i> · <i>e</i> = <i>K</i> · ( <i>x</i> , <i>y</i> , <i>θ</i> )<sup>T</sup> &nbsp;&nbsp; drive the error to zero: &nbsp; lim<sub><i>t</i>→∞</sub> <i>e</i>(<i>t</i>) = 0","<i>ρ</i> = √( Δ<i>x</i>² + Δ<i>y</i>² ) &nbsp;&nbsp; <i>α</i> = −<i>θ</i> + atan2( Δ<i>y</i> , Δ<i>x</i> ) &nbsp;&nbsp; <i>β</i> = −<i>θ</i> − <i>α</i> &nbsp;&nbsp; (goal angle <i>θ</i><sub>g</sub> = 0)","<i>ρ̇</i> = −<i>v</i> cos <i>α</i> &nbsp;&nbsp;&nbsp; <i>α̇</i> = ( <i>v</i> sin <i>α</i> ) / <i>ρ</i> − <i>ω</i> &nbsp;&nbsp;&nbsp; <i>β̇</i> = −( <i>v</i> sin <i>α</i> ) / <i>ρ</i>","<i>v</i> = <i>k</i><sub>ρ</sub> <i>ρ</i> &nbsp;&nbsp;&nbsp; <i>ω</i> = <i>k</i><sub>α</sub> <i>α</i> + <i>k</i><sub>β</sub> <i>β</i>"],["( <i>v</i> , <i>ω</i> )<sup>T</sup> = <i>K</i> · <i>e</i> = <i>K</i> · ( <i>x</i> , <i>y</i> , <i>θ</i> )<sup>T</sup> &nbsp;&nbsp; conduisent l'erreur à zéro : &nbsp; lim<sub><i>t</i>→∞</sub> <i>e</i>(<i>t</i>) = 0","<i>ρ</i> = √( Δ<i>x</i>² + Δ<i>y</i>² ) &nbsp;&nbsp; <i>α</i> = −<i>θ</i> + atan2( Δ<i>y</i> , Δ<i>x</i> ) &nbsp;&nbsp; <i>β</i> = −<i>θ</i> − <i>α</i> &nbsp;&nbsp; (angle du but <i>θ</i><sub>g</sub> = 0)","<i>ρ̇</i> = −<i>v</i> cos <i>α</i> &nbsp;&nbsp;&nbsp; <i>α̇</i> = ( <i>v</i> sin <i>α</i> ) / <i>ρ</i> − <i>ω</i> &nbsp;&nbsp;&nbsp; <i>β̇</i> = −( <i>v</i> sin <i>α</i> ) / <i>ρ</i>","<i>v</i> = <i>k</i><sub>ρ</sub> <i>ρ</i> &nbsp;&nbsp;&nbsp; <i>ω</i> = <i>k</i><sub>α</sub> <i>α</i> + <i>k</i><sub>β</sub> <i>β</i>"]],"kt":[["open-loop / feedback control","polar coordinates ρ, α, β","control gain","stability","singularity at ρ = 0","saturation"],["commande en boucle ouverte / fermée","coordonnées polaires ρ, α, β","gain de commande","stabilité","singularité en ρ = 0","saturation"]]},{"id":"l12","n":"12","m":18,"t":["Following a path: pure pursuit, Stanley and trajectory tracking","Suivre un chemin : poursuite pure, Stanley et suivi de trajectoire"],"ess":[["Pure pursuit steers on the circle through a look-ahead point: κ = 2 y_g / L_d².","A longer look-ahead is smoother but cuts corners; a shorter one is precise but oscillates; grow it with speed and delay.","Stanley corrects the heading and the cross-track error at the front axle; trajectory tracking also follows the time."],["La poursuite pure braque sur le cercle qui passe par un point d'anticipation : κ = 2 y_g / L_d².","Une anticipation longue est plus douce mais coupe les virages ; une courte est précise mais oscille ; augmentez-la avec la vitesse et le retard.","Stanley corrige le cap et l'écart latéral à l'essieu avant ; le suivi de trajectoire suit aussi le temps."]],"keep":[[],[]],"eq":[["<i>κ</i> = 2 <i>y</i><sub>g</sub> / <i>L</i><sub>d</sub>² &nbsp;&nbsp;&nbsp; <i>R</i> = 1 / <i>κ</i> &nbsp;&nbsp;&nbsp; differential robot: <i>ω</i> = <i>v</i> <i>κ</i> &nbsp;&nbsp;&nbsp; car: <i>δ</i> = arctan( <i>e</i> <i>κ</i> )","<i>δ</i> = <i>e</i><sub>θ</sub> + arctan( <i>k</i> <i>e</i><sub>y</sub> / <i>v</i> ) &nbsp;&nbsp; (then limit <i>δ</i> to the steering range of the car)","<i>v</i> = <i>v</i><sub>r</sub> cos <i>e</i><sub>θ</sub> + <i>k</i><sub>x</sub> <i>e</i><sub>x</sub> &nbsp;&nbsp;&nbsp; <i>ω</i> = <i>ω</i><sub>r</sub> + <i>v</i><sub>r</sub> ( <i>k</i><sub>y</sub> <i>e</i><sub>y</sub> + <i>k</i><sub>θ</sub> sin <i>e</i><sub>θ</sub> ) &nbsp;&nbsp;&nbsp; <i>k</i><sub>x</sub>, <i>k</i><sub>y</sub>, <i>k</i><sub>θ</sub> &gt; 0"],["<i>κ</i> = 2 <i>y</i><sub>g</sub> / <i>L</i><sub>d</sub>² &nbsp;&nbsp;&nbsp; <i>R</i> = 1 / <i>κ</i> &nbsp;&nbsp;&nbsp; robot différentiel : <i>ω</i> = <i>v</i> <i>κ</i> &nbsp;&nbsp;&nbsp; voiture : <i>δ</i> = arctan( <i>e</i> <i>κ</i> )","<i>δ</i> = <i>e</i><sub>θ</sub> + arctan( <i>k</i> <i>e</i><sub>y</sub> / <i>v</i> ) &nbsp;&nbsp; (puis limiter <i>δ</i> à la plage de braquage de la voiture)","<i>v</i> = <i>v</i><sub>r</sub> cos <i>e</i><sub>θ</sub> + <i>k</i><sub>x</sub> <i>e</i><sub>x</sub> &nbsp;&nbsp;&nbsp; <i>ω</i> = <i>ω</i><sub>r</sub> + <i>v</i><sub>r</sub> ( <i>k</i><sub>y</sub> <i>e</i><sub>y</sub> + <i>k</i><sub>θ</sub> sin <i>e</i><sub>θ</sub> ) &nbsp;&nbsp;&nbsp; <i>k</i><sub>x</sub>, <i>k</i><sub>y</sub>, <i>k</i><sub>θ</sub> &gt; 0"]],"kt":[["path / trajectory tracking","cross-track error","look-ahead distance","pure pursuit","Stanley controller","feed-forward / feedback","curvature κ"],["suivi de chemin / de trajectoire","erreur transversale","distance d'anticipation","poursuite pure","contrôleur de Stanley","anticipation / retour","courbure κ"]]},{"id":"l13","n":"13","m":18,"t":["Planning paths for nonholonomic robots: Dubins, parking and speed profiles","Planifier des chemins pour robots non holonomes : Dubins, créneaux et profils de vitesse"],"ess":[["A car-like robot needs paths whose curvature never exceeds 1 / R_min.","Dubins: the shortest forward path is one of six words of arcs and lines (LSL, RSR, LSR, RSL, LRL, RLR); Reeds–Shepp adds reversing.","The speed profile limits the speed in the curves (a_lat = v² κ) and smooths the accelerations (jerk)."],["Un robot de type voiture a besoin de chemins dont la courbure ne dépasse jamais 1 / R_min.","Dubins : le plus court chemin en avant est l'un de six mots d'arcs et de droites (LSL, RSR, LSR, RSL, LRL, RLR) ; Reeds–Shepp ajoute la marche arrière.","Le profil de vitesse limite la vitesse dans les virages (a_lat = v² κ) et adoucit les accélérations (à-coup)."]],"keep":[[],[]],"eq":[["| <i>κ</i> | ≤ 1 / <i>R</i><sub>min</sub>","<strong>LSL:</strong> &nbsp; <i>p</i>² = 2 + <i>d</i>² − 2 cos(<i>α</i>−<i>β</i>) + 2<i>d</i> ( sin <i>α</i> − sin <i>β</i> ) &nbsp; <i>tmp</i> = atan2( cos <i>β</i> − cos <i>α</i> , <i>d</i> + sin <i>α</i> − sin <i>β</i> ) &nbsp; <i>t</i> = −<i>α</i> + <i>tmp</i> &nbsp; <i>q</i> = <i>β</i> − <i>tmp</i>","<i>θ</i> = atan2( <i>ẏ</i> , <i>ẋ</i> ) &nbsp;&nbsp; <i>v</i> = √( <i>ẋ</i>² + <i>ẏ</i>² ) &nbsp;&nbsp; <i>ω</i> = ( <i>ẋ</i> <i>ÿ</i> − <i>ẏ</i> <i>ẍ</i> ) / ( <i>ẋ</i>² + <i>ẏ</i>² ) = <i>κ</i> <i>v</i>"],["| <i>κ</i> | ≤ 1 / <i>R</i><sub>min</sub>","<strong>LSL:</strong> &nbsp; <i>p</i>² = 2 + <i>d</i>² − 2 cos(<i>α</i>−<i>β</i>) + 2<i>d</i> ( sin <i>α</i> − sin <i>β</i> ) &nbsp; <i>tmp</i> = atan2( cos <i>β</i> − cos <i>α</i> , <i>d</i> + sin <i>α</i> − sin <i>β</i> ) &nbsp; <i>t</i> = −<i>α</i> + <i>tmp</i> &nbsp; <i>q</i> = <i>β</i> − <i>tmp</i>","<i>θ</i> = atan2( <i>ẏ</i> , <i>ẋ</i> ) &nbsp;&nbsp; <i>v</i> = √( <i>ẋ</i>² + <i>ẏ</i>² ) &nbsp;&nbsp; <i>ω</i> = ( <i>ẋ</i> <i>ÿ</i> − <i>ẏ</i> <i>ẍ</i> ) / ( <i>ẋ</i>² + <i>ẏ</i>² ) = <i>κ</i> <i>v</i>"]],"kt":[["minimum turning radius","curvature","Dubins path (LSL, RSR…)","Reeds–Shepp path","clothoid","differential flatness","speed profile / jerk"],["rayon de virage minimal","courbure","chemin de Dubins (LSL, RSR…)","chemin de Reeds–Shepp","clothoïde","platitude différentielle","profil de vitesse / jerk"]]},{"id":"l14","n":"14","m":22,"t":["Odometry in practice: encoders, errors and calibration","L'odométrie en pratique : codeurs, erreurs et étalonnage"],"ess":[["Distance per count = 2π r / (counts per turn × gear ratio); quadrature gives the direction and 4× the counts.","Systematic errors (radii, track) can be calibrated; non-systematic ones (slip, bumps) only filtered.","Calibrate with a straight line and square tests (UMBmark); a gyroscope fixes the heading but has a bias."],["Distance par impulsion = 2π r / (impulsions par tour × rapport de réduction) ; la quadrature donne le sens et 4× les impulsions.","Les erreurs systématiques (rayons, voie) s'étalonnent ; les non systématiques (glissement, bosses) se filtrent seulement.","Étalonnez avec une ligne droite et des carrés (UMBmark) ; un gyroscope corrige le cap mais a un biais."]],"keep":[[],[]],"eq":[["counts per wheel turn = 4 <i>N</i> <i>G</i> &nbsp;&nbsp;&nbsp; distance per count = 2π <i>r</i> / ( 4 <i>N</i> <i>G</i> ) &nbsp;&nbsp;&nbsp; Δ<i>s</i> = ( counts<sub>now</sub> − counts<sub>before</sub> ) × distance per count"],["impulsions par tour de roue = 4 <i>N</i> <i>G</i> &nbsp;&nbsp;&nbsp; distance par impulsion = 2π <i>r</i> / ( 4 <i>N</i> <i>G</i> ) &nbsp;&nbsp;&nbsp; Δ<i>s</i> = ( impulsions<sub>maintenant</sub> − impulsions<sub>avant</sub> ) × distance par impulsion"]],"kt":[["encoder / quadrature","counts per turn","systematic / non-systematic error","calibration","UMBmark","gyroscope bias"],["codeur / quadrature","impulsions par tour","erreur systématique / non systématique","étalonnage","UMBmark","biais du gyroscope"]]},{"id":"l15","n":"15","m":24,"t":["Knowing where you are: the Kalman filter and the EKF","Savoir où l'on est : le filtre de Kalman et l'EKF"],"ess":[["A Kalman filter mixes a prediction and a measurement according to their uncertainties: K = P / (P + R) in 1D.","The EKF predicts with the motion model and its Jacobian G (P ← G P Gᵀ + Q), then corrects with each measurement.","Check a filter with the innovation and a Mahalanobis gate; tune Q and R from real measurements."],["Un filtre de Kalman mélange une prédiction et une mesure selon leurs incertitudes : K = P / (P + R) en 1D.","L'EKF prédit avec le modèle de mouvement et sa jacobienne G (P ← G P Gᵀ + Q), puis corrige avec chaque mesure.","Vérifiez un filtre avec l'innovation et une porte de Mahalanobis ; réglez Q et R à partir de mesures réelles."]],"keep":[[],[]],"eq":[["<i>K</i> = <i>P</i> / ( <i>P</i> + <i>R</i> ) &nbsp;&nbsp; <i>x</i> ← <i>x</i><sub>pred</sub> + <i>K</i> ( <i>z</i> − <i>x</i><sub>pred</sub> ) &nbsp;&nbsp; <i>P</i> ← ( 1 − <i>K</i> ) <i>P</i>","<strong>Prediction</strong> (every odometry step): &nbsp; <i>μ</i> ← ( <i>x</i> + <i>v</i> Δ<i>t</i> cos <i>θ</i> , &nbsp; <i>y</i> + <i>v</i> Δ<i>t</i> sin <i>θ</i> , &nbsp; <i>θ</i> + <i>ω</i> Δ<i>t</i> ) &nbsp;&nbsp; <i>Σ</i> ← <i>G</i> <i>Σ</i> <i>G</i><sup>T</sup> + <i>Q</i>","<i>G</i> = <span class=\"mx c3\"><span>1</span><span>0</span><span>−v Δt sin θ</span><span>0</span><span>1</span><span>v Δt cos θ</span><span>0</span><span>0</span><span>1</span></span>","<strong>Update</strong> (when a measurement <i>z</i> arrives, <i>z</i> = <i>H</i> <i>μ</i> + noise of covariance <i>R</i>): &nbsp; <i>K</i> = <i>Σ</i> <i>H</i><sup>T</sup> ( <i>H</i> <i>Σ</i> <i>H</i><sup>T</sup> + <i>R</i> )<sup>−1</sup> &nbsp;&nbsp; <i>μ</i> ← <i>μ</i> + <i>K</i> ( <i>z</i> − <i>H</i> <i>μ</i> ) &nbsp;&nbsp; <i>Σ</i> ← ( <i>I</i> − <i>K</i> <i>H</i> ) <i>Σ</i>"],["<i>K</i> = <i>P</i> / ( <i>P</i> + <i>R</i> ) &nbsp;&nbsp; <i>x</i> ← <i>x</i><sub>pred</sub> + <i>K</i> ( <i>z</i> − <i>x</i><sub>pred</sub> ) &nbsp;&nbsp; <i>P</i> ← ( 1 − <i>K</i> ) <i>P</i>","<strong>Prédiction</strong> (à chaque pas d'odométrie) : &nbsp; <i>μ</i> ← ( <i>x</i> + <i>v</i> Δ<i>t</i> cos <i>θ</i> , &nbsp; <i>y</i> + <i>v</i> Δ<i>t</i> sin <i>θ</i> , &nbsp; <i>θ</i> + <i>ω</i> Δ<i>t</i> ) &nbsp;&nbsp; <i>Σ</i> ← <i>G</i> <i>Σ</i> <i>G</i><sup>T</sup> + <i>Q</i>","<i>G</i> = <span class=\"mx c3\"><span>1</span><span>0</span><span>−v Δt sin θ</span><span>0</span><span>1</span><span>v Δt cos θ</span><span>0</span><span>0</span><span>1</span></span>","<strong>Mise à jour</strong> (quand une mesure <i>z</i> arrive, <i>z</i> = <i>H</i> <i>μ</i> + bruit de covariance <i>R</i>) : &nbsp; <i>K</i> = <i>Σ</i> <i>H</i><sup>T</sup> ( <i>H</i> <i>Σ</i> <i>H</i><sup>T</sup> + <i>R</i> )<sup>−1</sup> &nbsp;&nbsp; <i>μ</i> ← <i>μ</i> + <i>K</i> ( <i>z</i> − <i>H</i> <i>μ</i> ) &nbsp;&nbsp; <i>Σ</i> ← ( <i>I</i> − <i>K</i> <i>H</i> ) <i>Σ</i>"]],"kt":[["Kalman gain","covariance matrix","EKF","Jacobian G","innovation","Mahalanobis gate","process / measurement noise"],["gain de Kalman","matrice de covariance","EKF","jacobienne G","innovation","porte de Mahalanobis","bruit de processus / de mesure"]]},{"id":"l16","n":"16","m":26,"t":["Dynamics and sizing: forces, motors, traction, tipping and battery","Dynamique et dimensionnement : forces, moteurs, adhérence, basculement et batterie"],"ess":[["Wheel force F = m a + c_rr m g + m g sin(slope); torque at the motor = F r / (gear ratio × efficiency).","Size the motor on the peak torque and on the RMS torque of the cycle (below the continuous torque).","Check traction (F ≤ μ N), tipping (stopping deceleration) and the battery: energy = power × time with a margin."],["Force aux roues F = m a + c_rr m g + m g sin(pente) ; couple au moteur = F r / (rapport × rendement).","Dimensionnez le moteur sur le couple crête et sur le couple RMS du cycle (sous le couple continu).","Vérifiez l'adhérence (F ≤ μ N), le basculement (décélération de freinage) et la batterie : énergie = puissance × temps avec une marge."]],"keep":[[],[]],"eq":[["<i>F</i> = <i>m</i> <i>a</i> + <i>c</i><sub>rr</sub> <i>m</i> <i>g</i> cos <i>α</i> + <i>m</i> <i>g</i> sin <i>α</i>","<i>τ</i><sub>wheel</sub> = <i>F</i> <i>r</i> / <i>n</i> &nbsp;&nbsp; <i>τ</i><sub>motor</sub> = <i>τ</i><sub>wheel</sub> / ( <i>G</i> <i>η</i><sub>g</sub> ) &nbsp;&nbsp; <i>ω</i><sub>motor</sub> = <i>G</i> <i>v</i> / <i>r</i> &nbsp;&nbsp; <i>n</i><sub>rpm</sub> = <i>ω</i><sub>motor</sub> × 60 / 2π","<i>τ</i><sub>RMS</sub> = √( ( Σ <i>τ</i><sub>i</sub>² <i>t</i><sub>i</sub> ) / Σ <i>t</i><sub>i</sub> )","<i>P</i><sub>el</sub> = <i>P</i><sub>m</sub> / <i>η</i> + <i>P</i><sub>electronics</sub> &nbsp;&nbsp;&nbsp; runtime = 0.8 × <i>E</i><sub>battery</sub> / <i>P</i><sub>el</sub>"],["<i>F</i> = <i>m</i> <i>a</i> + <i>c</i><sub>rr</sub> <i>m</i> <i>g</i> cos <i>α</i> + <i>m</i> <i>g</i> sin <i>α</i>","<i>τ</i><sub>wheel</sub> = <i>F</i> <i>r</i> / <i>n</i> &nbsp;&nbsp; <i>τ</i><sub>motor</sub> = <i>τ</i><sub>wheel</sub> / ( <i>G</i> <i>η</i><sub>g</sub> ) &nbsp;&nbsp; <i>ω</i><sub>motor</sub> = <i>G</i> <i>v</i> / <i>r</i> &nbsp;&nbsp; <i>n</i><sub>rpm</sub> = <i>ω</i><sub>motor</sub> × 60 / 2π","<i>τ</i><sub>RMS</sub> = √( ( Σ <i>τ</i><sub>i</sub>² <i>t</i><sub>i</sub> ) / Σ <i>t</i><sub>i</sub> )","<i>P</i><sub>él</sub> = <i>P</i><sub>m</sub> / <i>η</i> + <i>P</i><sub>électronique</sub> &nbsp;&nbsp;&nbsp; autonomie = 0,8 × <i>E</i><sub>batterie</sub> / <i>P</i><sub>él</sub>"]],"kt":[["rolling resistance c_rr","gear ratio / efficiency","peak / continuous / RMS torque","traction limit μ","tip-over","runtime / C-rate","feed-forward"],["résistance au roulement c_rr","rapport / rendement du réducteur","couple de crête / continu / RMS","limite d'adhérence μ","basculement","autonomie / régime C","anticipation"]]},{"id":"l17","n":"17","m":22,"t":["Software: a clean kinematics module, ROS 2 and the pitfalls","Logiciel : un module de cinématique propre, ROS 2 et les pièges"],"ess":[["Keep the kinematics in one small module with SI units and unit tests.","ROS 2: cmd_vel (Twist: linear.x = v, angular.z = ω) in, odom → base_link transform out, with tf2.","Add a watchdog that stops the robot when commands stop; most first bugs are units, signs and frames."],["Gardez la cinématique dans un petit module en unités SI, avec des tests unitaires.","ROS 2 : cmd_vel (Twist : linear.x = v, angular.z = ω) en entrée, la transformation odom → base_link en sortie, avec tf2.","Ajoutez un chien de garde qui arrête le robot quand les commandes s'arrêtent ; la plupart des premiers bugs sont des unités, des signes et des repères."]],"keep":[[],[]],"eq":[[],[]],"kt":[["ROS 2 node / topic","cmd_vel (Twist)","odom → base_link","tf2","watchdog","unit test","Nav2"],["nœud / topic ROS 2","cmd_vel (Twist)","odom → base_link","tf2","chien de garde","test unitaire","Nav2"]]},{"id":"l18","n":"18","m":22,"t":["Safety, testing and metrics: how a professional proves a robot works","Sécurité, essais et métriques : comment un professionnel prouve qu'un robot fonctionne"],"ess":[["Stopping distance = v t_r + v² / (2a): the reaction travel plus the braking.","Safety functions (protective fields, emergency stop, STO) follow standards such as ISO 3691-4.","A professional test has a plan, metrics, enough trials, a confidence interval and a pass criterion."],["Distance d'arrêt = v t_r + v² / (2a) : la course de réaction plus le freinage.","Les fonctions de sécurité (champs de protection, arrêt d'urgence, STO) suivent des normes comme l'ISO 3691-4.","Un essai professionnel a un plan, des indicateurs, assez d'essais, un intervalle de confiance et un critère de réussite."]],"keep":[[],[]],"eq":[["<i>s</i><sub>stop</sub> = <i>v</i> <i>t</i><sub>r</sub> + <i>v</i>² / ( 2 <i>a</i> ) &nbsp;&nbsp;&nbsp; for a free distance <i>d</i>: &nbsp; <i>v</i><sub>safe</sub> = −<i>a</i> <i>t</i><sub>r</sub> + √( ( <i>a</i> <i>t</i><sub>r</sub> )² + 2 <i>a</i> <i>d</i> )"],["<i>s</i><sub>arrêt</sub> = <i>v</i> <i>t</i><sub>r</sub> + <i>v</i>² / ( 2 <i>a</i> ) &nbsp;&nbsp;&nbsp; pour une distance libre <i>d</i> : &nbsp; <i>v</i><sub>sûre</sub> = −<i>a</i> <i>t</i><sub>r</sub> + √( ( <i>a</i> <i>t</i><sub>r</sub> )² + 2 <i>a</i> <i>d</i> )"]],"kt":[["reaction time / stopping distance","protective field","STO (safe torque off)","ISO 3691-4","confidence interval","pass criterion"],["durée de réaction / distance d'arrêt","champ de protection","STO (suppression sûre du couple)","ISO 3691-4","intervalle de confiance","critère de réussite"]]},{"id":"l19","n":"19","m":30,"t":["Capstone project: design a hospital delivery robot from the specification","Projet de synthèse : concevoir un robot de livraison d'hôpital à partir du cahier des charges"],"ess":[["Start from a written specification with numbers, then take each decision in the order of the course.","Justify every choice (drive, motors, battery, sensors, speeds) with a calculation and a margin.","Finish with a test plan that proves each requirement."],["Partez d'un cahier des charges chiffré, puis prenez chaque décision dans l'ordre du cours.","Justifiez chaque choix (motorisation, moteurs, batterie, capteurs, vitesses) par un calcul et une marge.","Terminez par un plan d'essais qui prouve chaque exigence."]],"keep":[[],[]],"eq":[[],[]],"kt":[["specification","decision matrix","worst case / typical case","design margin","acceptance test","design review"],["cahier des charges","matrice de décision","pire cas / cas typique","marge de conception","essai de réception","revue de conception"]]},{"id":"l20","n":"20","m":90,"t":["Final exam and practical tests: prove it","Examen final et épreuves pratiques : prouvez-le"],"ess":[["The written exam checks the theory and the calculations of the whole course.","The challenges check that you can tune and drive a robot, in the browser.","The labs prove it on code and on a real robot, with a short test report."],["L'examen écrit vérifie la théorie et les calculs de tout le cours.","Les défis vérifient que vous savez régler et conduire un robot, dans le navigateur.","Les TP le prouvent sur du code et sur un vrai robot, avec un court rapport d'essai."]],"keep":[[],[]],"eq":[[],[]],"kt":[["written exam","challenge","lab","pass criterion","test report"],["examen écrit","défi","TP","critère de réussite","rapport d'essais"]]}],"t":["Wheeled mobile robots, part 2","Robots mobiles à roues, partie 2"]}];
